fn default_object_placement_mode() -> ObjectPlacementMode {
    match env::var("CCBG_OBJECT_PLACEMENT_MODE")
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "prefer_high_speed" => ObjectPlacementMode::PreferHighSpeed,
        "balance_high_speed" => ObjectPlacementMode::BalanceHighSpeed,
        _ => ObjectPlacementMode::PreferPrimary,
    }
}

