#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum EncryptionAlgorithmPreference {
    #[default]
    Auto,
    #[serde(rename = "aes_256_gcm")]
    Aes256Gcm,
    #[serde(rename = "chacha20_poly1305")]
    Chacha20Poly1305,
}

impl EncryptionAlgorithmPreference {
    fn to_crypto(self) -> CryptoAlgorithmPreference {
        match self {
            Self::Auto => CryptoAlgorithmPreference::Auto,
            Self::Aes256Gcm => CryptoAlgorithmPreference::Aes256Gcm,
            Self::Chacha20Poly1305 => CryptoAlgorithmPreference::ChaCha20Poly1305,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum EncryptionKeySourceKind {
    #[default]
    EnvVar,
    FilePath,
    ExternalKms,
    GatewayManaged,
}

impl EncryptionKeySourceKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::EnvVar => "env_var",
            Self::FilePath => "file_path",
            Self::ExternalKms => "external_kms",
            Self::GatewayManaged => "gateway_managed",
        }
    }
}

#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum ManagedEncryptionKeyKind {
    #[default]
    Raw256Bit,
}

impl ManagedEncryptionKeyKind {
    fn key_material_len(self) -> usize {
        match self {
            Self::Raw256Bit => 32,
        }
    }
}

