impl<'a> MakeWriter<'a> for AdminLogWriterFactory {
    type Writer = AdminLogWriter;
    fn make_writer(&'a self) -> Self::Writer {
        AdminLogWriter {
            ring: self.ring.clone(),
            stderr: std::io::stderr(),
        }
    }
}

impl std::io::Write for AdminLogWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let written = self.stderr.write(buf)?;
        let captured = String::from_utf8_lossy(&buf[..written]);
        if let Ok(mut ring) = self.ring.lock() {
            for line in captured.lines() {
                ring.push_line(line);
            }
        }
        Ok(written)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.stderr.flush()
    }
}

impl AdminLogSource for InMemoryAdminLogSource {
    fn query(&self, query: &AdminLogQuery) -> AdminLogQueryResult {
        let requested_limit = query
            .limit
            .unwrap_or(DEFAULT_ADMIN_LOG_QUERY_LIMIT)
            .clamp(1, MAX_ADMIN_LOG_QUERY_LIMIT);
        let before_seq = query
            .cursor
            .as_deref()
            .and_then(|raw| raw.trim().parse::<u64>().ok());
        let level = query
            .level
            .as_deref()
            .map(|value| value.trim().to_ascii_lowercase())
            .filter(|value| !value.is_empty() && value != "all");
        let keyword = query
            .keyword
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| {
                let mut owned = value.to_ascii_lowercase();
                if owned.len() > MAX_ADMIN_LOG_KEYWORD_BYTES {
                    owned.truncate(MAX_ADMIN_LOG_KEYWORD_BYTES);
                }
                owned
            });
        let snapshot = self
            .ring
            .lock()
            .map(|ring| ring.entries.iter().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        let mut filtered: Vec<AdminLogEntryPayload> = snapshot
            .into_iter()
            .filter(|entry| {
                if let Some(cursor) = before_seq {
                    if entry.seq >= cursor {
                        return false;
                    }
                }
                if let Some(expected) = level.as_deref() {
                    if entry.level != expected {
                        return false;
                    }
                }
                if let Some(term) = keyword.as_deref() {
                    let haystack = format!("{} {}", entry.level, entry.line).to_ascii_lowercase();
                    if !haystack.contains(term) {
                        return false;
                    }
                }
                true
            })
            .collect();
        let has_more = filtered.len() > requested_limit;
        if has_more {
            filtered = filtered
                .into_iter()
                .rev()
                .take(requested_limit)
                .collect::<Vec<_>>()
                .into_iter()
                .rev()
                .collect();
        } else if filtered.len() > requested_limit {
            filtered = filtered.split_off(filtered.len().saturating_sub(requested_limit));
        }
        let next_cursor = filtered.first().map(|entry| entry.seq.to_string());
        AdminLogQueryResult {
            entries: filtered,
            next_cursor,
            has_more,
            limit: requested_limit,
        }
    }
}

async fn list_admin_logs(
    State(state): State<AppState>,
    Query(query): Query<AdminLogQuery>,
) -> Result<Json<AdminLogQueryResult>, ApiError> {
    let route_enabled = env::var("CCBG_ADMIN_LOG_ROUTE_ENABLED")
        .ok()
        .map(|raw| {
            matches!(
                raw.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(DEFAULT_ADMIN_LOG_ROUTE_ENABLED);
    if !route_enabled {
        return Err(ApiError(BlobError::Configuration(
            "admin logs route disabled".to_string(),
        )));
    }
    Ok(Json(state.admin_log_source.query(&query)))
}

