fn current_write_targets(state: &AppState) -> Vec<ProviderId> {
    let snapshot = control_plane_snapshot(state);
    let normalized = normalize_write_targets(
        snapshot.write_targets,
        snapshot.topology.primary_provider,
        state.config.onedrive.enabled,
    );
    if normalized.is_empty() {
        vec![snapshot.topology.primary_provider]
    } else {
        normalized
    }
}

