            (
                entry.catalog.provider.clone(),
                json!({
                    "provider": entry.catalog.provider,
                    "surface": entry.catalog.surface,
                    "source_path": entry.source_path.display().to_string(),
                    "catalog": entry.catalog,
                }),
            )
