async fn admin_login_page(State(state): State<AppState>, headers: HeaderMap) -> Response {
    if let Some(expected_api_key) = state.config.control_api_key.as_deref() {
        if control_api_key_matches_headers(&headers, expected_api_key) {
            return (
                StatusCode::FOUND,
                [(LOCATION, HeaderValue::from_static("/"))],
            )
                .into_response();
        }
    }
    if lookup_admin_browser_session(&state, &headers).is_some() {
        return (
            StatusCode::FOUND,
            [(LOCATION, HeaderValue::from_static("/"))],
        )
            .into_response();
    }
    let mut response = Html(admin_login_page_html(&state, None)).into_response();
    if cookie_value_from_headers(&headers, ADMIN_SESSION_COOKIE).is_some() {
        response.headers_mut().append(
            SET_COOKIE,
            HeaderValue::from_str(&expire_cookie_header(ADMIN_SESSION_COOKIE))
                .expect("expired admin session cookie should be valid"),
        );
    }
    if cookie_value_from_headers(&headers, CONTROL_API_KEY_COOKIE).is_some() {
        response.headers_mut().append(
            SET_COOKIE,
            HeaderValue::from_str(&expire_cookie_header(CONTROL_API_KEY_COOKIE))
                .expect("expired control api key cookie should be valid"),
        );
    }
    response
}

async fn admin_login(
    State(state): State<AppState>,
    Json(input): Json<AdminLoginInput>,
) -> Result<Response, ControlApiError> {
    let username = input.username.trim();
    let password = input.password;
    if username.is_empty() || password.is_empty() {
        return Err(ControlApiError::unauthorized(
            "username and password are both required",
        ));
    }
    if !verify_admin_browser_credentials(&state, username, &password)? {
        return Err(ControlApiError::unauthorized(
            "invalid username or password",
        ));
    }

    let must_change_password = admin_default_credentials_active(&state);
    let (session_id, expires_at_unix_ms) =
        create_admin_browser_session(&state, username, must_change_password);
    let mut response = Json(AdminLoginPayload {
        ok: true,
        redirect_to: if must_change_password {
            "/?tab=access"
        } else {
            "/"
        }
        .to_string(),
        username: username.to_string(),
        expires_at_unix_ms,
        must_change_password,
    })
    .into_response();
    response.headers_mut().append(
        SET_COOKIE,
        HeaderValue::from_str(&admin_session_cookie_header(
            &session_id,
            state.config.admin_session_ttl_seconds,
        ))
        .expect("admin session cookie should be valid"),
    );
    response.headers_mut().append(
        SET_COOKIE,
        HeaderValue::from_str(&expire_cookie_header(CONTROL_API_KEY_COOKIE))
            .expect("expired control api key cookie should be valid"),
    );
    Ok(response)
}

async fn admin_change_password(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<AdminChangePasswordInput>,
) -> Result<Json<AdminChangePasswordPayload>, ControlApiError> {
    let current_password = input.current_password.trim().to_string();
    let new_password = input.new_password.trim().to_string();
    let confirm_password = input.confirm_password.trim().to_string();
    if current_password.is_empty() || new_password.is_empty() || confirm_password.is_empty() {
        return Err(ControlApiError::unauthorized(
            "current password, new password, and confirmation are all required",
        ));
    }
    if new_password != confirm_password {
        return Err(ControlApiError::unauthorized(
            "new password and confirmation do not match",
        ));
    }
    if new_password.len() < 8 {
        return Err(ControlApiError::unauthorized(
            "new password must be at least 8 characters long",
        ));
    }
    let (_, session) = lookup_admin_browser_session(&state, &headers).ok_or_else(|| {
        let mut error = ControlApiError::unauthorized("admin login required");
        error.set_cookie = Some(expire_cookie_header(ADMIN_SESSION_COOKIE));
        error
    })?;
    if !verify_admin_browser_credentials(&state, &session.username, &current_password)? {
        return Err(ControlApiError::unauthorized("current password is invalid"));
    }
    if current_password == new_password {
        return Err(ControlApiError::unauthorized(
            "new password must be different from the current password",
        ));
    }
    let password_hash = hash_admin_password(&new_password)?;
    let password_changed_at_unix_ms = persist_admin_password_hash(&state, password_hash)?;
    if let Some((session_id, _)) = lookup_admin_browser_session(&state, &headers) {
        update_admin_browser_session_password_state(&state, &session_id, false);
    }
    Ok(Json(AdminChangePasswordPayload {
        ok: true,
        must_change_password: false,
        password_changed_at_unix_ms,
    }))
}

async fn admin_logout(State(state): State<AppState>, headers: HeaderMap) -> Response {
    remove_admin_browser_session_by_headers(&state, &headers);
    let mut response = StatusCode::NO_CONTENT.into_response();
    response.headers_mut().append(
        SET_COOKIE,
        HeaderValue::from_str(&expire_cookie_header(ADMIN_SESSION_COOKIE))
            .expect("expired admin session cookie should be valid"),
    );
    response.headers_mut().append(
        SET_COOKIE,
        HeaderValue::from_str(&expire_cookie_header(CONTROL_API_KEY_COOKIE))
            .expect("expired control api key cookie should be valid"),
    );
    response
}

const ADMIN_INDEX_TEMPLATE: &str = include_str!("../assets/admin/index.html");

fn admin_index_template_candidates() -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    if let Ok(current_exe) = env::current_exe() {
        if let Some(bin_dir) = current_exe.parent() {
            candidates.push(bin_dir.join("assets/admin/index.html"));
            if let Some(prefix_dir) = bin_dir.parent() {
                candidates.push(prefix_dir.join("assets/admin/index.html"));
            }
        }
    }
    candidates.push(PathBuf::from("assets/admin/index.html"));
    candidates.push(PathBuf::from("crates/gatewayd/assets/admin/index.html"));
    candidates
}

fn admin_index_template_source() -> String {
    if let Some(path) = env_opt_or_file(
        "CCBG_ADMIN_INDEX_TEMPLATE",
        "CCBG_ADMIN_INDEX_TEMPLATE_FILE",
    ) {
        match fs::read_to_string(&path) {
            Ok(contents) => return contents,
            Err(error) => eprintln!("failed to read CCBG_ADMIN_INDEX_TEMPLATE {path}: {error}"),
        }
    }
    for candidate in admin_index_template_candidates() {
        match fs::read_to_string(&candidate) {
            Ok(contents) => return contents,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => eprintln!(
                "failed to read admin template {}: {error}",
                candidate.display()
            ),
        }
    }
    ADMIN_INDEX_TEMPLATE.to_string()
}

fn render_admin_index_html_from_template_source(template_source: &str) -> String {
    let provider_credentials_template =
        ROUTE_PROVIDER_CREDENTIALS.replace("{provider}", "${encodeURIComponent(provider)}");
    let browser_flow_handoff_template = ROUTE_BROWSER_FLOW_SESSION_HANDOFF
        .replace("{session_id}", "${encodeURIComponent(sessionId)}");
    template_source
        .replace("{admin_favicon}", &admin_favicon_data_url())
        .replace("{admin_api_version}", ADMIN_API_VERSION)
        .replace("{route_status}", ROUTE_STATUS)
        .replace("{route_admin_logout}", ROUTE_ADMIN_LOGOUT)
        .replace("{route_admin_change_password}", ROUTE_ADMIN_CHANGE_PASSWORD)
        .replace("{route_admin_logs}", ROUTE_ADMIN_LOGS)
        .replace("{route_topology_update}", ROUTE_TOPOLOGY_UPDATE)
        .replace("{route_auth_capture_policy}", ROUTE_AUTH_CAPTURE_POLICY)
        .replace(
            "{route_provider_credentials_template}",
            &provider_credentials_template,
        )
        .replace(
            "{route_browser_flow_session_handoff_template}",
            &browser_flow_handoff_template,
        )
}

fn render_admin_index_html() -> String {
    render_admin_index_html_from_template_source(&admin_index_template_source())
}

async fn admin_index() -> Html<String> {
    Html(render_admin_index_html())
}

async fn admin_showcase_feed(
    Query(query): Query<HashMap<String, String>>,
) -> Result<Response, Response> {
    let limit = query
        .get("limit")
        .and_then(|value| value.trim().parse::<u32>().ok())
        .map(|value| value.clamp(1, 24))
        .unwrap_or(12);
    let remote_url = format!("https://llm-router.agi2030.online/v1/feeds/showcase?limit={limit}");
    let client = HttpClient::builder().build().map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            Json(serde_json::json!({
                "error": format!("failed to build showcase proxy client: {error}"),
                "api_version": ADMIN_API_VERSION,
            })),
        )
            .into_response()
    })?;
    let response = client.get(remote_url).send().await.map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            Json(serde_json::json!({
                "error": format!("failed to fetch llm-router showcase feed: {error}"),
                "api_version": ADMIN_API_VERSION,
            })),
        )
            .into_response()
    })?;
    let status = response.status();
    let payload = response.text().await.map_err(|error| {
        (
            StatusCode::BAD_GATEWAY,
            Json(serde_json::json!({
                "error": format!("failed to read llm-router showcase feed: {error}"),
                "api_version": ADMIN_API_VERSION,
            })),
        )
            .into_response()
    })?;
    Ok((
        status,
        [(
            CONTENT_TYPE,
            HeaderValue::from_static("application/json; charset=utf-8"),
        )],
        payload,
    )
        .into_response())
}

async fn admin_status(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<AdminStatusPayload>, ApiError> {
    let gateway_write_ahead_log = gateway_write_ahead_log_status_payload(&state)?;
    let replication_state = replication_state_payload(&state)?;
    let provider_health = provider_health_payloads(&state).await?;
    let onedrive_auth = read_onedrive_auth_status(&state);
    let alerts = build_admin_alerts(&state, &provider_health, &replication_state, &onedrive_auth);
    let suppressed_alerts = current_suppressed_admin_alerts(&state);
    let object_action_history = control_plane_snapshot(&state).object_action_history;
    let monitoring = monitoring_summary_payload(
        &provider_health,
        &replication_state,
        &object_action_history,
        &alerts,
    );
    let notify = current_notify_status_payload(&state);
    let operations_overview =
        operations_overview_payload(&state, &replication_state, &monitoring, &notify);
    let mut runtime_topology = runtime_topology_payload(&runtime_topology(&state));
    runtime_topology.write_targets = current_write_target_names(&state);
    runtime_topology.high_speed_providers = current_high_speed_provider_names(&state);
    runtime_topology.object_placement_mode = current_object_placement_mode(&state).as_str();
    let must_change_password = lookup_admin_browser_session(&state, &headers)
        .map(|(_, session)| session.must_change_password)
        .unwrap_or(false);
    let admin_auth = AdminAuthStatusPayload {
        username: admin_username_for_config(&state.config),
        default_credentials_active: admin_default_credentials_active(&state),
        must_change_password,
        password_changed_at_unix_ms: admin_password_changed_at_unix_ms(&state),
    };
    let topology_provider_catalog = topology_provider_catalog(
        state.config.onedrive.enabled,
        &current_high_speed_providers(&state),
    );
    Ok(Json(AdminStatusPayload {
        runtime: runtime_status_payload(&state),
        admin_client_ip: state
            .admin_client_ip
            .lock()
            .expect("admin client ip store poisoned")
            .clone(),
        admin_auth,
        gateway_backup: gateway_backup_status_payload(&state),
        gateway_write_ahead_log,
        desktop_mount_seed: desktop_mount_seed_payload(&state),
        topology_provider_catalog,
        provider_bridge_catalog_seed: provider_bridge_catalog_seed_payload(&state),
        provider_limit_probes: current_provider_limit_probes(&state),
        provider_limit_profiles: current_provider_limit_profiles(&state),
        monitoring,
        operations_overview,
        notify,
        runtime_topology,
        desired_topology: desired_topology_payload(&state),
        replication_state,
        object_action_history,
        object_action_history_limit: state.config.object_action_history_limit,
        provider_health,
        alerts,
        suppressed_alerts,
        onedrive_auth,
    }))
}

