async fn update_gateway_backup_policy(
    State(state): State<AppState>,
    Json(input): Json<GatewayBackupPolicyInput>,
) -> Result<Json<GatewayBackupStatusPayload>, ApiError> {
    save_gateway_backup_policy(&state, input)?;
    Ok(Json(gateway_backup_status_payload(&state)))
}

