async fn update_gateway_write_ahead_log_policy(
    State(state): State<AppState>,
    Json(input): Json<GatewayWriteAheadLogPolicyInput>,
) -> Result<Json<GatewayWriteAheadLogStatusPayload>, ApiError> {
    let remote_provider = input
        .remote_provider
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ProviderId::parse)
        .transpose()
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let policy = normalize_gateway_write_ahead_log_policy(
        GatewayWriteAheadLogPolicy {
            enabled: input.enabled,
            remote_provider,
            application_ids: input.application_ids,
        },
        state.config.onedrive.enabled,
        &current_data_plane_applications(&state),
    )?;
    {
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        control_plane.gateway_write_ahead_log_policy = policy;
        persist_control_plane_state(&state.config.control_plane_file, &control_plane)
            .map_err(|error| BlobError::Configuration(error.to_string()))?;
    }
    let status = inspect_gateway_write_ahead_log_remote_status(&state).await?;
    Ok(Json(status))
}

