async fn run_provider_limit_probe_stream(
    State(state): State<AppState>,
    Path(provider): Path<String>,
    Json(input): Json<ProviderLimitProbeInput>,
) -> Result<Response, ApiError> {
    let (sender, receiver) = mpsc::unbounded_channel();

    let handle = tokio::spawn(async move {
        match execute_provider_limit_probe(state, provider, input, Some(sender.clone())).await {
            Ok(payload) => send_provider_limit_probe_event(
                &Some(sender),
                ProviderLimitProbeEventPayload {
                    event: "completed",
                    checked_at_unix_ms: current_unix_ms(),
                    message: format!("size probe completed for {}", payload.label),
                    size_bytes: None,
                    probe_chunk_size_bytes: None,
                    key: None,
                    read_bytes: None,
                    read_elapsed_ms: None,
                    read_bytes_per_sec: None,
                    step: None,
                    payload: Some(payload),
                    error: None,
                },
            ),
            Err(error) => send_provider_limit_probe_event(
                &Some(sender),
                ProviderLimitProbeEventPayload {
                    event: "error",
                    checked_at_unix_ms: current_unix_ms(),
                    message: error.to_string(),
                    size_bytes: None,
                    probe_chunk_size_bytes: None,
                    key: None,
                    read_bytes: None,
                    read_elapsed_ms: None,
                    read_bytes_per_sec: None,
                    step: None,
                    payload: None,
                    error: Some(error.to_string()),
                },
            ),
        }
    });

    let body_stream = stream::unfold(
        ProviderLimitProbeStreamState {
            receiver,
            _abort_on_drop: AbortProviderLimitProbeOnDrop { handle },
        },
        |mut state| async move {
            if let Some(event) = state.receiver.recv().await {
                let line = provider_limit_probe_event_line(&event);
                Some((line, state))
            } else {
                None
            }
        },
    );
    let mut headers = HeaderMap::new();
    headers.insert(
        CONTENT_TYPE,
        HeaderValue::from_static("application/x-ndjson; charset=utf-8"),
    );
    headers.insert(
        CACHE_CONTROL,
        HeaderValue::from_static("no-cache, no-transform"),
    );
    headers.insert(
        HeaderName::from_static("x-accel-buffering"),
        HeaderValue::from_static("no"),
    );
    Ok((StatusCode::OK, headers, Body::from_stream(body_stream)).into_response())
}

async fn clear_provider_limit_probe_cleanup(
    State(state): State<AppState>,
    Path(provider): Path<String>,
) -> Result<Json<ProviderLimitProbeCleanupClearPayload>, ApiError> {
    let provider = ProviderId::parse(&provider)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let cleanup_alert_id = format!(
        "provider_limit_probe_cleanup_required_{}",
        provider.as_str()
    );
    let mut control_plane = state
        .control_plane
        .lock()
        .expect("control plane state poisoned");
    let mut probe_directory_key = None;
    let mut cleared_profile = false;
    let mut cleared_probe_result = false;

    if let Some(profile) = control_plane.provider_limit_profiles.get_mut(&provider) {
        probe_directory_key = profile.latest_probe_directory_key.clone();
        if profile.latest_probe_cleanup_required {
            cleared_profile = true;
        }
        profile.latest_probe_cleanup_required = false;
    }

    if let Some(probe) = control_plane.provider_limit_probes.get_mut(&provider) {
        if probe_directory_key.is_none() {
            probe_directory_key = Some(probe.probe_directory_key.clone());
        }
        if probe.cleanup_required || probe.results.iter().any(|step| step.cleanup_required) {
            cleared_probe_result = true;
        }
        probe.cleanup_required = false;
        for step in &mut probe.results {
            step.cleanup_required = false;
        }
    }

    let previous_suppressed_len = control_plane.suppressed_admin_alerts.len();
    control_plane
        .suppressed_admin_alerts
        .retain(|record| record.id != cleanup_alert_id);
    let cleared_closed_alert =
        control_plane.suppressed_admin_alerts.len() != previous_suppressed_len;

    if cleared_profile || cleared_probe_result || cleared_closed_alert {
        persist_control_plane_state(&state.config.control_plane_file, &control_plane).map_err(
            |error| {
                BlobError::Configuration(format!(
                    "failed to clear provider limit probe cleanup marker: {error}"
                ))
            },
        )?;
    }

    Ok(Json(ProviderLimitProbeCleanupClearPayload {
        provider: provider.as_str().to_string(),
        label: provider_label(provider).to_string(),
        cleanup_required: false,
        probe_directory_key,
        cleared_profile,
        cleared_probe_result,
        cleared_closed_alert,
    }))
}

async fn execute_provider_limit_probe(
    state: AppState,
    provider: String,
    input: ProviderLimitProbeInput,
    event_sender: Option<mpsc::UnboundedSender<ProviderLimitProbeEventPayload>>,
) -> Result<ProviderLimitProbePayload, BlobError> {
    let provider = ProviderId::parse(&provider)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let backend = backend_for_provider(&state, provider)?;
    let capabilities = backend.capabilities();
    if !capabilities.write {
        return Err(BlobError::NotImplemented(format!(
            "{} does not support writes, so size probing cannot run",
            provider_label(provider)
        ))
        .into());
    }
    if !capabilities.streaming_put {
        return Err(BlobError::NotImplemented(format!(
            "{} does not support streaming writes, so size probing is disabled to avoid buffering large probe bodies in memory",
            provider_label(provider)
        ))
        .into());
    }
    if input.read_back && !capabilities.read {
        return Err(BlobError::NotImplemented(format!(
            "{} does not support reads, so read-back size probing cannot run",
            provider_label(provider)
        ))
        .into());
    }

    let bucket = input
        .bucket
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("root")
        .to_string();
    let key_prefix = normalize_probe_key_prefix(input.key_prefix.as_deref());
    let sizes = provider_limit_probe_sizes(&input)?;
    let chunk_sizes = provider_limit_probe_chunk_sizes(&input, &capabilities)?;
    let probe_chunk_size = chunk_sizes
        .first()
        .copied()
        .unwrap_or(PROVIDER_LIMIT_PROBE_MIN_CHUNK_SIZE_BYTES);
    let mut results = Vec::new();
    let mut max_verified_upload_bytes = None;
    let mut max_verified_download_bytes = None;
    let mut pending_sizes = sizes.clone();
    let mut seen_sizes = sizes.iter().copied().collect::<BTreeSet<_>>();
    let run_id = current_unix_ms();
    let probe_directory_key = format!("{key_prefix}/{}-{run_id}", provider.as_str());
    send_provider_limit_probe_event(
        &event_sender,
        ProviderLimitProbeEventPayload {
            event: "started",
            checked_at_unix_ms: current_unix_ms(),
            message: format!(
                "starting size probe for {} in {probe_directory_key}",
                provider_label(provider)
            ),
            size_bytes: None,
            probe_chunk_size_bytes: Some(probe_chunk_size),
            key: Some(probe_directory_key.clone()),
            read_bytes: None,
            read_elapsed_ms: None,
            read_bytes_per_sec: None,
            step: None,
            payload: None,
            error: None,
        },
    );
    let mut upload_limit_found = false;
    let mut download_limit_found = !input.read_back;

    while !pending_sizes.is_empty() {
        let size = pending_sizes.remove(0);
        if input.stop_after_first_success && upload_limit_found && download_limit_found {
            let step = skipped_provider_limit_probe_step(
                size,
                probe_chunk_size,
                &probe_directory_key,
                "a larger candidate already verified the requested limits",
            );
            send_provider_limit_probe_event(
                &event_sender,
                ProviderLimitProbeEventPayload {
                    event: "skipped",
                    checked_at_unix_ms: current_unix_ms(),
                    message: format!(
                        "skipping {} because a larger candidate already passed",
                        format_bytes_for_log(size)
                    ),
                    size_bytes: Some(size),
                    probe_chunk_size_bytes: Some(probe_chunk_size),
                    key: Some(step.key.clone()),
                    read_bytes: None,
                    read_elapsed_ms: None,
                    read_bytes_per_sec: None,
                    step: Some(step.clone()),
                    payload: None,
                    error: None,
                },
            );
            results.push(step);
            continue;
        }

        let mut uploaded_step = None;
        for (chunk_index, chunk_size) in chunk_sizes.iter().copied().enumerate() {
            let key = provider_limit_probe_attempt_key(
                &probe_directory_key,
                size,
                chunk_size,
                chunk_index,
            );
            let mut step =
                new_provider_limit_probe_step(size, chunk_size, chunk_index + 1, key.clone());
            send_provider_limit_probe_event(
                &event_sender,
                ProviderLimitProbeEventPayload {
                    event: "attempt_started",
                    checked_at_unix_ms: current_unix_ms(),
                    message: format!(
                        "uploading {} with upload part {} to {key}",
                        format_bytes_for_log(size),
                        format_bytes_for_log(chunk_size)
                    ),
                    size_bytes: Some(size),
                    probe_chunk_size_bytes: Some(chunk_size),
                    key: Some(key.clone()),
                    read_bytes: None,
                    read_elapsed_ms: None,
                    read_bytes_per_sec: None,
                    step: None,
                    payload: None,
                    error: None,
                },
            );

            let write_started_at = current_unix_ms();
            let mut upload_attempt_count = 0u32;
            let upload_result = loop {
                upload_attempt_count += 1;
                let result = backend
                    .put_object(PutObjectRequest {
                        container: bucket.clone(),
                        key: key.clone(),
                        body: zero_probe_body(size, chunk_size),
                        size: Some(size),
                        content_type: Some("application/octet-stream".to_string()),
                        preferred_upload_part_size_bytes: Some(chunk_size),
                    })
                    .await;
                match &result {
                    Err(error)
                        if upload_attempt_count < 3
                            && provider_limit_probe_error_suggests_directory_retry(error) =>
                    {
                        send_provider_limit_probe_event(
                            &event_sender,
                            ProviderLimitProbeEventPayload {
                                event: "attempt_retrying",
                                checked_at_unix_ms: current_unix_ms(),
                                message: format!(
                                    "upload saw a transient directory lookup error for {}; retrying same key",
                                    key
                                ),
                                size_bytes: Some(size),
                                probe_chunk_size_bytes: Some(chunk_size),
                                key: Some(key.clone()),
                                read_bytes: None,
                                read_elapsed_ms: None,
                                read_bytes_per_sec: None,
                                step: None,
                                payload: None,
                                error: Some(error.to_string()),
                            },
                        );
                        sleep(Duration::from_millis(1_000)).await;
                    }
                    _ => break result,
                }
            };
            match upload_result {
                Ok(result) => {
                    step.upload_ok = true;
                    let upload_elapsed_ms =
                        current_unix_ms().saturating_sub(write_started_at).max(1);
                    step.upload_elapsed_ms = Some(upload_elapsed_ms);
                    step.upload_first_response_latency_ms = result.first_response_latency_ms;
                    step.upload_bytes_per_sec =
                        provider_io_throughput_bytes_per_sec(size, upload_elapsed_ms);
                    state.provider_io_stats.record_success_with_response(
                        provider.as_str(),
                        ProviderIoOperationKind::Write,
                        upload_elapsed_ms,
                        result.first_response_latency_ms,
                        Some(size),
                    );
                    max_verified_upload_bytes =
                        Some(max_verified_upload_bytes.unwrap_or(0).max(size));
                    uploaded_step = Some(step);
                    break;
                }
                Err(error) => {
                    step.upload_elapsed_ms =
                        Some(current_unix_ms().saturating_sub(write_started_at));
                    step.upload_error = Some(error.to_string());
                    state.provider_io_stats.record_failure(
                        provider.as_str(),
                        ProviderIoOperationKind::Write,
                        &error.to_string(),
                    );
                    cleanup_provider_limit_probe_key(
                        backend.as_ref(),
                        &capabilities,
                        provider,
                        &bucket,
                        &key,
                        input.delete_after,
                        &mut step,
                    )
                    .await;
                    let retry_smaller_chunk =
                        provider_limit_probe_error_suggests_chunk_retry(&error)
                            && chunk_index + 1 < chunk_sizes.len();
                    send_provider_limit_probe_event(
                        &event_sender,
                        ProviderLimitProbeEventPayload {
                            event: "attempt_finished",
                            checked_at_unix_ms: current_unix_ms(),
                            message: if retry_smaller_chunk {
                                format!(
                                    "upload failed for {} with upload part {}; retrying smaller part",
                                    format_bytes_for_log(size),
                                    format_bytes_for_log(chunk_size)
                                )
                            } else {
                                format!(
                                    "upload failed for {} with upload part {}; moving to next size",
                                    format_bytes_for_log(size),
                                    format_bytes_for_log(chunk_size)
                                )
                            },
                            size_bytes: Some(size),
                            probe_chunk_size_bytes: Some(chunk_size),
                            key: Some(key.clone()),
                            read_bytes: None,
                            read_elapsed_ms: None,
                            read_bytes_per_sec: None,
                            step: Some(step.clone()),
                            payload: None,
                            error: step.upload_error.clone(),
                        },
                    );
                    results.push(step);
                    if retry_smaller_chunk {
                        continue;
                    }
                    break;
                }
            }
        }

        let Some(mut step) = uploaded_step else {
            if results.last().is_some_and(|step| {
                step.upload_error
                    .as_deref()
                    .map(|message| {
                        provider_limit_probe_error_stops_size_discovery(&BlobError::Upstream(
                            message.to_string(),
                        ))
                    })
                    .unwrap_or(false)
            }) {
                pending_sizes.clear();
            } else {
                maybe_enqueue_smaller_probe_size(
                    size,
                    input.stop_after_first_success,
                    &mut pending_sizes,
                    &mut seen_sizes,
                );
            }
            continue;
        };

        upload_limit_found = true;

        if input.read_back {
            let read_total_timeout = provider_limit_probe_read_total_timeout(size, &input);
            let read_progress_interval = provider_limit_probe_read_progress_interval(&input);
            send_provider_limit_probe_event(
                &event_sender,
                ProviderLimitProbeEventPayload {
                    event: "read_started",
                    checked_at_unix_ms: current_unix_ms(),
                    message: format!(
                        "reading back {} from {}",
                        format_bytes_for_log(size),
                        step.key
                    ),
                    size_bytes: Some(size),
                    probe_chunk_size_bytes: Some(step.probe_chunk_size_bytes),
                    key: Some(step.key.clone()),
                    read_bytes: None,
                    read_elapsed_ms: None,
                    read_bytes_per_sec: None,
                    step: None,
                    payload: None,
                    error: None,
                },
            );
            let read_started_at = current_unix_ms();
            match backend.get_object(&bucket, &step.key).await {
                Ok(payload) => {
                    let probe_chunk_size_bytes = step.probe_chunk_size_bytes;
                    let progress_key = step.key.clone();
                    match drain_probe_body_with_first_progress(
                        payload.body,
                        read_started_at,
                        read_total_timeout,
                        read_progress_interval,
                        |progress| {
                            send_provider_limit_probe_event(
                                &event_sender,
                                ProviderLimitProbeEventPayload {
                                    event: "read_progress",
                                    checked_at_unix_ms: current_unix_ms(),
                                    message: format!(
                                        "read back {} bytes from {} so far",
                                        progress.read_bytes, progress_key
                                    ),
                                    size_bytes: Some(size),
                                    probe_chunk_size_bytes: Some(probe_chunk_size_bytes),
                                    key: Some(progress_key.clone()),
                                    read_bytes: Some(progress.read_bytes),
                                    read_elapsed_ms: Some(progress.elapsed_ms),
                                    read_bytes_per_sec: progress.bytes_per_sec,
                                    step: None,
                                    payload: None,
                                    error: None,
                                },
                            );
                        },
                    )
                    .await
                    {
                        Ok((read_bytes, read_first_response_latency_ms)) if read_bytes == size => {
                            let read_elapsed_ms =
                                current_unix_ms().saturating_sub(read_started_at).max(1);
                            step.read_first_response_latency_ms = read_first_response_latency_ms;
                            step.read_ok = Some(true);
                            step.read_bytes = Some(read_bytes);
                            step.read_elapsed_ms = Some(read_elapsed_ms);
                            step.read_bytes_per_sec =
                                provider_io_throughput_bytes_per_sec(read_bytes, read_elapsed_ms);
                            state.provider_io_stats.record_success_with_response(
                                provider.as_str(),
                                ProviderIoOperationKind::Read,
                                read_elapsed_ms,
                                step.read_first_response_latency_ms,
                                Some(read_bytes),
                            );
                            max_verified_download_bytes =
                                Some(max_verified_download_bytes.unwrap_or(0).max(size));
                            download_limit_found = true;
                        }
                        Ok((read_bytes, read_first_response_latency_ms)) => {
                            step.read_first_response_latency_ms = read_first_response_latency_ms;
                            step.read_ok = Some(false);
                            step.read_bytes = Some(read_bytes);
                            step.read_elapsed_ms =
                                Some(current_unix_ms().saturating_sub(read_started_at));
                            step.read_error = Some(format!(
                                "read-back size mismatch: expected {size} bytes, got {read_bytes}"
                            ));
                            state.provider_io_stats.record_failure(
                                provider.as_str(),
                                ProviderIoOperationKind::Read,
                                step.read_error
                                    .as_deref()
                                    .unwrap_or("read-back size mismatch"),
                            );
                        }
                        Err(error) => {
                            step.read_ok = Some(false);
                            step.read_bytes = Some(error.read_bytes);
                            step.read_elapsed_ms = Some(error.elapsed_ms);
                            step.read_first_response_latency_ms = error.first_response_latency_ms;
                            step.read_bytes_per_sec = error.bytes_per_sec;
                            step.read_error = Some(error.error.to_string());
                            state.provider_io_stats.record_failure(
                                provider.as_str(),
                                ProviderIoOperationKind::Read,
                                step.read_error.as_deref().unwrap_or("read-back failed"),
                            );
                        }
                    }
                }
                Err(error) => {
                    step.read_ok = Some(false);
                    step.read_elapsed_ms = Some(current_unix_ms().saturating_sub(read_started_at));
                    step.read_error = Some(error.to_string());
                    state.provider_io_stats.record_failure(
                        provider.as_str(),
                        ProviderIoOperationKind::Read,
                        &error.to_string(),
                    );
                }
            }
        }

        send_provider_limit_probe_event(
            &event_sender,
            ProviderLimitProbeEventPayload {
                event: "cleanup_started",
                checked_at_unix_ms: current_unix_ms(),
                message: format!("cleaning probe object {}", step.key),
                size_bytes: Some(size),
                probe_chunk_size_bytes: Some(step.probe_chunk_size_bytes),
                key: Some(step.key.clone()),
                read_bytes: step.read_bytes,
                read_elapsed_ms: step.read_elapsed_ms,
                read_bytes_per_sec: step.read_bytes_per_sec,
                step: None,
                payload: None,
                error: None,
            },
        );
        let cleanup_key = step.key.clone();
        cleanup_provider_limit_probe_key(
            backend.as_ref(),
            &capabilities,
            provider,
            &bucket,
            &cleanup_key,
            input.delete_after,
            &mut step,
        )
        .await;

        send_provider_limit_probe_event(
            &event_sender,
            ProviderLimitProbeEventPayload {
                event: "attempt_finished",
                checked_at_unix_ms: current_unix_ms(),
                message: if step.read_ok == Some(false) {
                    format!(
                        "upload passed but read-back failed for {}",
                        format_bytes_for_log(size)
                    )
                } else if step.delete_ok == Some(false) {
                    format!(
                        "probe passed but cleanup failed for {}",
                        format_bytes_for_log(size)
                    )
                } else {
                    format!(
                        "probe passed for {} with upload part {}",
                        format_bytes_for_log(size),
                        format_bytes_for_log(step.probe_chunk_size_bytes)
                    )
                },
                size_bytes: Some(size),
                probe_chunk_size_bytes: Some(step.probe_chunk_size_bytes),
                key: Some(step.key.clone()),
                read_bytes: step.read_bytes,
                read_elapsed_ms: step.read_elapsed_ms,
                read_bytes_per_sec: step.read_bytes_per_sec,
                step: Some(step.clone()),
                payload: None,
                error: step
                    .upload_error
                    .clone()
                    .or_else(|| step.read_error.clone())
                    .or_else(|| step.delete_error.clone()),
            },
        );
        results.push(step);

        if results.last().is_some_and(|step| {
            step.read_ok == Some(false)
                && step
                    .read_error
                    .as_deref()
                    .map(|message| {
                        !provider_limit_probe_error_stops_size_discovery(&BlobError::Upstream(
                            message.to_string(),
                        ))
                    })
                    .unwrap_or(true)
        }) {
            maybe_enqueue_smaller_probe_size(
                size,
                input.stop_after_first_success,
                &mut pending_sizes,
                &mut seen_sizes,
            );
        }

        if input.stop_after_first_success && upload_limit_found && download_limit_found {
            continue;
        }
    }

    let cleanup_required = results.iter().any(|step| step.cleanup_required);
    let payload = ProviderLimitProbePayload {
        provider: provider.as_str().to_string(),
        label: provider_label(provider).to_string(),
        bucket,
        key_prefix,
        probe_directory_key,
        checked_at_unix_ms: current_unix_ms(),
        capabilities,
        probe_chunk_size_bytes: probe_chunk_size,
        probe_chunk_size_candidates_bytes: chunk_sizes,
        max_verified_upload_bytes,
        max_verified_download_bytes,
        cleanup_required,
        latency_semantics_version: PROVIDER_LIMIT_PROBE_LATENCY_SEMANTICS_VERSION_V2,
        results,
    };
    persist_provider_limit_probe_payload(&state, provider, payload.clone())?;
    Ok(payload)
}

fn maybe_enqueue_smaller_probe_size(
    failed_size: u64,
    auto_discover: bool,
    pending_sizes: &mut Vec<u64>,
    seen_sizes: &mut BTreeSet<u64>,
) {
    if !auto_discover || failed_size <= 1 {
        return;
    }
    let next_size = failed_size / 2;
    if next_size == 0 || !seen_sizes.insert(next_size) {
        return;
    }
    pending_sizes.push(next_size);
    pending_sizes.sort_unstable_by(|left, right| right.cmp(left));
}

fn provider_limit_probe_error_stops_size_discovery(error: &BlobError) -> bool {
    let message = error.to_string().to_ascii_lowercase();
    [
        "userdayflowoverlimited",
        "data flow is out",
        "quota exceeded",
        "out of quota",
        "rate limit",
        "too many requests",
        "account suspended",
        "session expired",
        "invalidsessionkey",
        "cookieusersession is null or invalid",
        "credential",
        "unauthorized",
        "forbidden",
        "access denied",
    ]
    .iter()
    .any(|needle| message.contains(needle))
}

fn persist_provider_limit_probe_payload(
    state: &AppState,
    provider: ProviderId,
    payload: ProviderLimitProbePayload,
) -> Result<(), BlobError> {
    let mut control_plane = state
        .control_plane
        .lock()
        .expect("control plane state poisoned");
    let profile = merged_provider_limit_profile(
        provider,
        &payload,
        control_plane.provider_limit_profiles.get(&provider),
    );
    control_plane
        .provider_limit_probes
        .insert(provider, payload);
    control_plane
        .provider_limit_profiles
        .insert(provider, profile);
    persist_control_plane_state(&state.config.control_plane_file, &control_plane).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to persist provider limit probe result: {error}"
        ))
    })
}

fn merged_provider_limit_profile(
    provider: ProviderId,
    payload: &ProviderLimitProbePayload,
    previous: Option<&ProviderLimitProfilePayload>,
) -> ProviderLimitProfilePayload {
    let latency_versions_match = previous
        .map(|profile| profile.latency_semantics_version == payload.latency_semantics_version)
        .unwrap_or(true);
    let upload_candidate = payload
        .max_verified_upload_bytes
        .map(|bytes| (bytes, payload.checked_at_unix_ms));
    let download_candidate = payload
        .max_verified_download_bytes
        .map(|bytes| (bytes, payload.checked_at_unix_ms));
    let part_candidate = provider_limit_probe_verified_upload_part_size(payload)
        .map(|bytes| (bytes, payload.checked_at_unix_ms));
    let upload_speed_candidate = provider_limit_probe_max_upload_bytes_per_sec(payload)
        .map(|speed| (speed, payload.checked_at_unix_ms));
    let download_speed_candidate = provider_limit_probe_max_download_bytes_per_sec(payload)
        .map(|speed| (speed, payload.checked_at_unix_ms));
    let upload_response_candidate =
        provider_limit_probe_min_upload_first_response_latency_ms(payload)
            .map(|latency| (latency, payload.checked_at_unix_ms));
    let download_response_candidate =
        provider_limit_probe_min_download_first_response_latency_ms(payload)
            .map(|latency| (latency, payload.checked_at_unix_ms));

    let (max_verified_upload_bytes, max_verified_upload_checked_at_unix_ms) =
        merge_limit_profile_dimension(
            previous.and_then(|profile| profile.max_verified_upload_bytes),
            previous.and_then(|profile| profile.max_verified_upload_checked_at_unix_ms),
            upload_candidate,
        );
    let (max_verified_download_bytes, max_verified_download_checked_at_unix_ms) =
        merge_limit_profile_dimension(
            previous.and_then(|profile| profile.max_verified_download_bytes),
            previous.and_then(|profile| profile.max_verified_download_checked_at_unix_ms),
            download_candidate,
        );
    let (max_verified_upload_part_size_bytes, max_verified_upload_part_checked_at_unix_ms) =
        merge_limit_profile_dimension(
            previous.and_then(|profile| profile.max_verified_upload_part_size_bytes),
            previous.and_then(|profile| profile.max_verified_upload_part_checked_at_unix_ms),
            part_candidate,
        );
    let (max_verified_upload_bytes_per_sec, max_verified_upload_speed_checked_at_unix_ms) =
        merge_limit_profile_float_max_dimension(
            previous.and_then(|profile| profile.max_verified_upload_bytes_per_sec),
            previous.and_then(|profile| profile.max_verified_upload_speed_checked_at_unix_ms),
            upload_speed_candidate,
        );
    let (max_verified_download_bytes_per_sec, max_verified_download_speed_checked_at_unix_ms) =
        merge_limit_profile_float_max_dimension(
            previous.and_then(|profile| profile.max_verified_download_bytes_per_sec),
            previous.and_then(|profile| profile.max_verified_download_speed_checked_at_unix_ms),
            download_speed_candidate,
        );
    let (
        min_verified_upload_first_response_latency_ms,
        min_verified_upload_first_response_checked_at_unix_ms,
    ) = merge_limit_profile_latency_min_dimension(
        if latency_versions_match {
            previous.and_then(|profile| profile.min_verified_upload_first_response_latency_ms)
        } else {
            None
        },
        if latency_versions_match {
            previous
                .and_then(|profile| profile.min_verified_upload_first_response_checked_at_unix_ms)
        } else {
            None
        },
        upload_response_candidate,
    );
    let (
        min_verified_download_first_response_latency_ms,
        min_verified_download_first_response_checked_at_unix_ms,
    ) = merge_limit_profile_latency_min_dimension(
        if latency_versions_match {
            previous.and_then(|profile| profile.min_verified_download_first_response_latency_ms)
        } else {
            None
        },
        if latency_versions_match {
            previous
                .and_then(|profile| profile.min_verified_download_first_response_checked_at_unix_ms)
        } else {
            None
        },
        download_response_candidate,
    );

    ProviderLimitProfilePayload {
        provider: provider.as_str().to_string(),
        label: provider_label(provider).to_string(),
        updated_at_unix_ms: payload.checked_at_unix_ms,
        max_verified_upload_bytes,
        max_verified_upload_checked_at_unix_ms,
        max_verified_download_bytes,
        max_verified_download_checked_at_unix_ms,
        max_verified_upload_part_size_bytes,
        max_verified_upload_part_checked_at_unix_ms,
        max_verified_upload_bytes_per_sec,
        max_verified_upload_speed_checked_at_unix_ms,
        max_verified_download_bytes_per_sec,
        max_verified_download_speed_checked_at_unix_ms,
        min_verified_upload_first_response_latency_ms,
        min_verified_upload_first_response_checked_at_unix_ms,
        min_verified_download_first_response_latency_ms,
        min_verified_download_first_response_checked_at_unix_ms,
        latency_semantics_version: payload.latency_semantics_version,
        latest_probe_directory_key: Some(payload.probe_directory_key.clone()),
        latest_probe_cleanup_required: payload.cleanup_required,
        latest_probe_hit_daily_flow_limit: provider_limit_probe_hit_daily_flow_limit(payload),
    }
}

fn provider_limit_probe_hit_daily_flow_limit(payload: &ProviderLimitProbePayload) -> bool {
    payload.results.iter().any(|step| {
        step.upload_error
            .as_deref()
            .is_some_and(provider_limit_probe_error_mentions_daily_flow_limit)
            || step
                .read_error
                .as_deref()
                .is_some_and(provider_limit_probe_error_mentions_daily_flow_limit)
            || step
                .delete_error
                .as_deref()
                .is_some_and(provider_limit_probe_error_mentions_daily_flow_limit)
    })
}

fn provider_limit_probe_error_mentions_daily_flow_limit(message: &str) -> bool {
    let message = message.to_ascii_lowercase();
    message.contains("userdayflowoverlimited")
        || message.contains("data flow is out")
        || message.contains("daily flow")
}

fn merge_limit_profile_dimension(
    previous_value: Option<u64>,
    previous_checked_at: Option<u64>,
    candidate: Option<(u64, u64)>,
) -> (Option<u64>, Option<u64>) {
    match (previous_value, candidate) {
        (Some(previous), Some((candidate, checked_at))) if candidate > previous => {
            (Some(candidate), Some(checked_at))
        }
        (Some(previous), _) => (Some(previous), previous_checked_at),
        (None, Some((candidate, checked_at))) => (Some(candidate), Some(checked_at)),
        (None, None) => (None, None),
    }
}

fn merge_limit_profile_float_max_dimension(
    previous_value: Option<f64>,
    previous_checked_at: Option<u64>,
    candidate: Option<(f64, u64)>,
) -> (Option<f64>, Option<u64>) {
    let previous_value = previous_value.filter(|value| value.is_finite() && *value > 0.0);
    let candidate = candidate.filter(|(value, _)| value.is_finite() && *value > 0.0);
    match (previous_value, candidate) {
        (Some(previous), Some((candidate, checked_at))) if candidate > previous => {
            (Some(candidate), Some(checked_at))
        }
        (Some(previous), _) => (Some(previous), previous_checked_at),
        (None, Some((candidate, checked_at))) => (Some(candidate), Some(checked_at)),
        (None, None) => (None, None),
    }
}

fn merge_limit_profile_latency_min_dimension(
    previous_value: Option<u64>,
    previous_checked_at: Option<u64>,
    candidate: Option<(u64, u64)>,
) -> (Option<u64>, Option<u64>) {
    let previous_value = previous_value.filter(|value| *value > 0);
    let candidate = candidate.filter(|(value, _)| *value > 0);
    match (previous_value, candidate) {
        (Some(previous), Some((candidate, checked_at))) if candidate < previous => {
            (Some(candidate), Some(checked_at))
        }
        (Some(previous), _) => (Some(previous), previous_checked_at),
        (None, Some((candidate, checked_at))) => (Some(candidate), Some(checked_at)),
        (None, None) => (None, None),
    }
}

fn provider_limit_probe_verified_upload_part_size(
    payload: &ProviderLimitProbePayload,
) -> Option<u64> {
    payload
        .results
        .iter()
        .filter(|step| step.upload_ok)
        .map(|step| step.probe_chunk_size_bytes)
        .max()
}

fn provider_limit_probe_max_upload_bytes_per_sec(
    payload: &ProviderLimitProbePayload,
) -> Option<f64> {
    payload
        .results
        .iter()
        .filter(|step| step.upload_ok)
        .filter_map(|step| step.upload_bytes_per_sec)
        .filter(|value| value.is_finite() && *value > 0.0)
        .max_by(|left, right| left.total_cmp(right))
}

fn provider_limit_probe_max_download_bytes_per_sec(
    payload: &ProviderLimitProbePayload,
) -> Option<f64> {
    payload
        .results
        .iter()
        .filter(|step| step.read_ok == Some(true))
        .filter_map(|step| step.read_bytes_per_sec)
        .filter(|value| value.is_finite() && *value > 0.0)
        .max_by(|left, right| left.total_cmp(right))
}

fn provider_limit_probe_min_upload_first_response_latency_ms(
    payload: &ProviderLimitProbePayload,
) -> Option<u64> {
    payload
        .results
        .iter()
        .filter(|step| step.upload_ok)
        .filter_map(|step| step.upload_first_response_latency_ms)
        .filter(|value| *value > 0)
        .min()
}

fn provider_limit_probe_min_download_first_response_latency_ms(
    payload: &ProviderLimitProbePayload,
) -> Option<u64> {
    payload
        .results
        .iter()
        .filter(|step| step.read_ok == Some(true))
        .filter_map(|step| step.read_first_response_latency_ms)
        .filter(|value| *value > 0)
        .min()
}

fn send_provider_limit_probe_event(
    sender: &Option<mpsc::UnboundedSender<ProviderLimitProbeEventPayload>>,
    event: ProviderLimitProbeEventPayload,
) {
    if let Some(sender) = sender {
        let _ = sender.send(event);
    }
}

fn provider_limit_probe_event_line(
    event: &ProviderLimitProbeEventPayload,
) -> Result<Bytes, std::io::Error> {
    let mut line = serde_json::to_vec(event).map_err(std::io::Error::other)?;
    line.push(b'\n');
    Ok(Bytes::from(line))
}

fn new_provider_limit_probe_step(
    size_bytes: u64,
    probe_chunk_size_bytes: u64,
    attempt_index: usize,
    key: String,
) -> ProviderLimitProbeStepPayload {
    ProviderLimitProbeStepPayload {
        size_bytes,
        probe_chunk_size_bytes,
        attempt_index,
        key,
        skipped: false,
        skip_reason: None,
        upload_ok: false,
        upload_elapsed_ms: None,
        upload_first_response_latency_ms: None,
        upload_bytes_per_sec: None,
        upload_error: None,
        read_ok: None,
        read_elapsed_ms: None,
        read_first_response_latency_ms: None,
        read_bytes: None,
        read_bytes_per_sec: None,
        read_error: None,
        delete_ok: None,
        delete_error: None,
        cleanup_required: false,
    }
}

fn skipped_provider_limit_probe_step(
    size_bytes: u64,
    probe_chunk_size_bytes: u64,
    probe_directory_key: &str,
    reason: &str,
) -> ProviderLimitProbeStepPayload {
    ProviderLimitProbeStepPayload {
        skipped: true,
        skip_reason: Some(reason.to_string()),
        ..new_provider_limit_probe_step(
            size_bytes,
            probe_chunk_size_bytes,
            0,
            format!("{probe_directory_key}/size-{size_bytes}-skipped.probe"),
        )
    }
}

fn provider_limit_probe_attempt_key(
    probe_directory_key: &str,
    size: u64,
    chunk_size: u64,
    chunk_index: usize,
) -> String {
    format!(
        "{probe_directory_key}/size-{size}-chunk-{chunk_size}-attempt-{}.probe",
        chunk_index + 1
    )
}

async fn cleanup_provider_limit_probe_key(
    backend: &dyn BlobBackend,
    capabilities: &blob_core::BackendCapabilities,
    provider: ProviderId,
    bucket: &str,
    key: &str,
    delete_after: bool,
    step: &mut ProviderLimitProbeStepPayload,
) {
    if delete_after {
        if capabilities.delete {
            match backend.delete_object(bucket, key).await {
                Ok(()) | Err(BlobError::NotFound(_)) => {
                    step.delete_ok = Some(true);
                }
                Err(error) => {
                    step.delete_ok = Some(false);
                    step.delete_error = Some(error.to_string());
                    step.cleanup_required = true;
                }
            }
        } else {
            step.delete_ok = Some(false);
            step.delete_error = Some(format!(
                "{} does not currently support delete_object",
                provider_label(provider)
            ));
            step.cleanup_required = true;
        }
    } else {
        step.cleanup_required = true;
    }
}

fn provider_limit_probe_error_suggests_chunk_retry(error: &BlobError) -> bool {
    let message = error.to_string().to_ascii_lowercase();
    [
        "chunk",
        "part",
        "partsize",
        "part size",
        "piece",
        "segment",
        "分片",
        "切片",
        "块",
    ]
    .iter()
    .any(|needle| message.contains(needle))
}

fn provider_limit_probe_error_suggests_directory_retry(error: &BlobError) -> bool {
    let message = error.to_string().to_ascii_lowercase();
    message.contains("not found")
        || message.contains("entry not found")
        || message.contains("directory")
        || message.contains("folder")
        || message.contains("目录")
        || message.contains("文件夹")
}

fn format_bytes_for_log(value: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut size = value as f64;
    let mut unit = 0usize;
    while size >= 1024.0 && unit < UNITS.len() - 1 {
        size /= 1024.0;
        unit += 1;
    }
    if size >= 100.0 || unit == 0 {
        format!("{size:.0} {}", UNITS[unit])
    } else {
        format!("{size:.1} {}", UNITS[unit])
    }
}

fn replication_dlq_entry_payload(
    entry: metadata_store::ReplicationDeadLetterEntry,
) -> ReplicationDlqEntryPayload {
    ReplicationDlqEntryPayload {
        original_job_id: entry.original_job.job_id,
        status: entry.status.as_str().to_string(),
        target: entry.original_job.target,
        bucket: entry.original_job.object.bucket,
        key: entry.original_job.object.key,
        operation: entry.original_job.operation.as_str().to_string(),
        attempts: entry.original_job.attempts,
        dead_lettered_at_unix_ms: entry.dead_lettered_at_unix_ms,
        reason: entry.reason,
        replay_count: entry.replay_count,
        last_replayed_job_id: entry.last_replayed_job_id,
        last_replayed_at_unix_ms: entry.last_replayed_at_unix_ms,
    }
}

async fn list_replication_dlq_api(
    State(state): State<AppState>,
    Query(query): Query<ReplicationDlqQuery>,
) -> Result<Json<ReplicationDlqListPayload>, ApiError> {
    let target = query.target.and_then(|value| {
        let trimmed = value.trim().to_ascii_lowercase();
        (!trimmed.is_empty()).then_some(trimmed)
    });
    let include_replayed = query.include_replayed.unwrap_or(false);
    let limit = query.limit.unwrap_or(100).clamp(1, 500);
    let entries = state
        .metadata_store
        .list_dead_letter_jobs(target.as_deref(), include_replayed, limit)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let open_count = state
        .metadata_store
        .count_dead_letter_jobs(target.as_deref(), false)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let entries = entries
        .into_iter()
        .map(replication_dlq_entry_payload)
        .collect::<Vec<_>>();
    Ok(Json(ReplicationDlqListPayload {
        open_count,
        returned_count: entries.len(),
        entries,
    }))
}

async fn replay_replication_dlq_job_api(
    State(state): State<AppState>,
    Path(job_id): Path<u64>,
) -> Result<Json<ReplicationDlqReplayPayload>, ApiError> {
    let replayed_job_id = state.replication.allocate_job_id();
    let replayed = state
        .metadata_store
        .replay_dead_letter_job(job_id, replayed_job_id, u128::from(current_unix_ms()))
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    state.replication.enqueue_existing_job(replayed.clone());
    Ok(Json(ReplicationDlqReplayPayload {
        original_job_id: job_id,
        replayed_job_id: replayed.job_id,
        status: replayed.status.as_str().to_string(),
        target: replayed.target,
        bucket: replayed.object.bucket,
        key: replayed.object.key,
    }))
}

async fn replay_replication_dlq_target_api(
    State(state): State<AppState>,
    Path(target): Path<String>,
) -> Result<Json<ReplicationDlqTargetReplayPayload>, ApiError> {
    let target = ProviderId::parse(&target)
        .map_err(|error| BlobError::Configuration(error.to_string()))?
        .as_str()
        .to_string();
    let open_count = state
        .metadata_store
        .count_dead_letter_jobs(Some(&target), false)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let replay_limit = open_count.min(MAX_REPLICATION_DLQ_TARGET_REPLAY_BATCH_SIZE);
    let replayed_job_ids = (0..replay_limit)
        .map(|_| state.replication.allocate_job_id())
        .collect::<Vec<_>>();
    let replayed_jobs = state
        .metadata_store
        .replay_dead_letter_jobs_for_target(
            &target,
            &replayed_job_ids,
            u128::from(current_unix_ms()),
            replay_limit,
        )
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let mut jobs = Vec::with_capacity(replayed_jobs.len());
    for (original_job_id, replayed) in replayed_jobs {
        state.replication.enqueue_existing_job(replayed.clone());
        jobs.push(ReplicationDlqReplayPayload {
            original_job_id,
            replayed_job_id: replayed.job_id,
            status: replayed.status.as_str().to_string(),
            target: replayed.target,
            bucket: replayed.object.bucket,
            key: replayed.object.key,
        });
    }
    Ok(Json(ReplicationDlqTargetReplayPayload {
        target,
        replayed_jobs: jobs.len(),
        jobs,
    }))
}

async fn retry_replication_job_api(
    State(state): State<AppState>,
    Path(job_id): Path<u64>,
) -> Result<Json<ReplicationRetryPayload>, ApiError> {
    let retried_job = state
        .metadata_store
        .retry_failed_job(job_id, u128::from(current_unix_ms()))
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    state.replication.enqueue_existing_job(retried_job.clone());

    Ok(Json(ReplicationRetryPayload {
        job_id: retried_job.job_id,
        status: retried_job.status.as_str().to_string(),
        target: retried_job.target,
        bucket: retried_job.object.bucket,
        key: retried_job.object.key,
    }))
}

async fn retry_replication_target_api(
    State(state): State<AppState>,
    Path(target): Path<String>,
) -> Result<Json<ReplicationTargetRetryPayload>, ApiError> {
    let target = ProviderId::parse(&target)
        .map_err(|error| BlobError::Configuration(error.to_string()))?
        .as_str()
        .to_string();
    let retried_jobs = state
        .metadata_store
        .retry_failed_jobs_for_target(&target, u128::from(current_unix_ms()))
        .map_err(|error| BlobError::Configuration(error.to_string()))?;

    for job in &retried_jobs {
        state.replication.enqueue_existing_job(job.clone());
    }

    Ok(Json(ReplicationTargetRetryPayload {
        target,
        retried_jobs: retried_jobs.len(),
        jobs: retried_jobs
            .into_iter()
            .map(|job| ReplicationTargetRetryJobPayload {
                job_id: job.job_id,
                status: job.status.as_str(),
                bucket: job.object.bucket,
                key: job.object.key,
            })
            .collect(),
    }))
}

