fn normalize_object_placement_sample_limit(limit: Option<usize>) -> usize {
    match limit {
        Some(limit) => limit.clamp(1, MAX_OBJECT_PLACEMENT_SAMPLE_LIMIT),
        None => DEFAULT_OBJECT_PLACEMENT_SAMPLE_LIMIT,
    }
}

fn normalize_object_placement_record_limit(limit: Option<usize>) -> usize {
    match limit {
        Some(limit) => limit.clamp(1, MAX_OBJECT_PLACEMENT_RECORD_LIMIT),
        None => DEFAULT_OBJECT_PLACEMENT_RECORD_LIMIT,
    }
}

fn normalize_object_browser_limit(limit: Option<usize>) -> usize {
    match limit {
        Some(limit) => limit.clamp(1, MAX_OBJECT_BROWSER_LIMIT),
        None => DEFAULT_OBJECT_BROWSER_LIMIT,
    }
}

fn normalize_optional_admin_filter(raw: Option<String>) -> Option<String> {
    raw.and_then(|value| {
        let trimmed = value.trim();
        if trimmed.is_empty() || trimmed.eq_ignore_ascii_case("all") {
            None
        } else {
            Some(trimmed.to_string())
        }
    })
}

