async fn handoff_browser_flow_session(
    State(state): State<AppState>,
    Path(session_id): Path<String>,
    Json(input): Json<BrowserFlowSessionHandoffInput>,
) -> Result<Json<BrowserFlowSessionHandoffPayload>, ApiError> {
    let session =
        browser_flow_auth_session_snapshot(&state, &session_id).map_err(ApiError::from)?;
    let provider = ProviderId::parse(&session.provider)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    if !matches!(
        provider,
        ProviderId::Unicom | ProviderId::Telecom | ProviderId::Mobile
    ) {
        return Err(BlobError::Configuration(format!(
            "provider {} does not support browser-flow session handoff",
            provider.as_str()
        ))
        .into());
    }
    if session.status != BROWSER_FLOW_AUTH_SESSION_STATUS_COMPLETED || session.report.is_none() {
        return Err(BlobError::Configuration(format!(
            "browser-flow session {} is not completed",
            session.session_id
        ))
        .into());
    }
    let bridge = state
        .provider_bridge_catalogs
        .get(provider.as_str())
        .ok_or_else(|| {
            BlobError::Configuration(format!(
                "provider bridge catalog not found for {}",
                provider.as_str()
            ))
        })?;
    let existing_record = load_provider_credential_record_or_default(&state.config, provider);
    let (mut next_record, credential_keys, runtime_keys) =
        apply_session_runtime_to_provider_credentials(&session.runtime, &existing_record, bridge);
    next_record.capture_cdp_endpoint_url = session.cdp_endpoint_url.clone();
    next_record.capture_cdp_target_selector = session.cdp_target_selector.clone();
    if credential_keys.is_empty() {
        return Err(BlobError::Configuration(format!(
            "session {} does not include any runtime credential mappings",
            session.session_id
        ))
        .into());
    }
    next_record = next_record.normalize();
    validate_provider_credential_record(&next_record)?;
    persist_provider_credential_record(&state.config, provider, &next_record)?;
    let handoff_at_unix_ms = current_unix_ms();
    let operator = normalize_secret_field(input.operator);
    let reason = normalize_secret_field(input.reason);
    let handoff_record = AuthSessionHandoffRecord {
        schema_version: AUTH_SESSION_HANDOFF_RECORD_SCHEMA_VERSION,
        session_id: session.session_id.clone(),
        provider: session.provider.clone(),
        surface: session.surface.clone(),
        flow_id: session.flow_id.clone(),
        status: session.status.clone(),
        credential_keys: credential_keys.clone(),
        runtime_keys: runtime_keys.clone(),
        created_at_unix_ms: session.created_at_unix_ms,
        updated_at_unix_ms: session.updated_at_unix_ms,
        handoff_at_unix_ms,
        operator,
        reason,
        report_summary: session
            .report
            .as_ref()
            .map(|report| AuthSessionHandoffReportSummary {
                mode: format!("{:?}", report.mode).to_ascii_lowercase(),
                flow_id: report.flow_id.clone(),
                step_count: report.step_count,
            }),
    };
    let audit_path = persist_auth_session_handoff_record(&state.config, &handoff_record)?;
    if provider_supports_credential_lease_probe(provider) {
        reset_provider_credential_lease_on_save(&state.config, provider)?;
        state
            .credential_lease_probe
            .lock()
            .expect("credential lease probe state poisoned")
            .next_probe_at_unix_ms_by_provider
            .insert(provider, handoff_at_unix_ms);
        state.credential_lease_probe_wake.notify_one();
    }
    rebuild_backend_for_provider(&state, provider)?;

    Ok(Json(BrowserFlowSessionHandoffPayload {
        session_id: session.session_id,
        provider: provider.as_str().to_string(),
        status: "accepted".to_string(),
        handoff_at_unix_ms,
        credential_keys,
        runtime_keys,
        audit_path: audit_path.display().to_string(),
    }))
}

async fn get_browser_flow_session_manual_challenge_artifact(
    State(state): State<AppState>,
    Path(session_id): Path<String>,
) -> Result<Response, ApiError> {
    let session = state
        .auth
        .browser_flow_sessions
        .lock()
        .expect("browser flow auth session store poisoned")
        .get(&session_id)
        .cloned()
        .ok_or_else(|| {
            BlobError::NotFound(format!("browser flow auth session not found: {session_id}"))
        })?;
    let artifact = session
        .manual_challenge
        .as_ref()
        .and_then(|challenge| challenge.artifact.as_ref())
        .ok_or_else(|| {
            BlobError::NotFound(format!(
                "browser flow manual challenge artifact not found: {session_id}"
            ))
        })?;
    let bytes = fs::read(&artifact.path).map_err(|error| {
        BlobError::Upstream(format!(
            "read browser flow manual challenge artifact '{}': {error}",
            artifact.path
        ))
    })?;
    Ok(([(CONTENT_TYPE, artifact.mime_type.clone())], bytes).into_response())
}

