async fn explain_error_with_llm(
    State(state): State<AppState>,
    Json(input): Json<LlmErrorExplainInput>,
) -> Result<Json<LlmErrorExplainPayload>, ApiError> {
    let context = normalize_llm_error_context(input.context);
    let provider = normalize_llm_error_provider(input.provider);
    let error_text = input.error_text.trim().to_string();
    if error_text.is_empty() {
        return Err(ApiError(BlobError::Configuration(
            "error_text is required".to_string(),
        )));
    }

    let policy = current_auth_capture_policy(&state);
    if !policy.llm_analysis_enabled {
        return Err(ApiError(BlobError::NotImplemented(
            "LLM 辅助未启用：请先在“LLM 辅助”标签页开启并保存。".to_string(),
        )));
    }
    let endpoints = enabled_auth_capture_llm_endpoints(&policy);
    if endpoints.is_empty() {
        return Err(ApiError(BlobError::NotImplemented(
            "没有可用的 LLM 端点：请先在“LLM 辅助”标签页至少配置并启用一个端点。".to_string(),
        )));
    }

    let faq_hits = collect_llm_error_faq_hits(&error_text);
    let prompt =
        build_llm_error_explain_prompt(&context, provider.as_deref(), &error_text, &faq_hits);

    let mut failures = Vec::new();
    for endpoint in &endpoints {
        match request_llm_error_explain_response(&state.auth.http_client, endpoint, &prompt).await {
            Ok(analysis_text) => {
                return Ok(Json(LlmErrorExplainPayload {
                    context,
                    provider,
                    endpoint: auth_capture_llm_endpoint_display_name(endpoint),
                    model_id: endpoint.model_id.clone(),
                    faq_hits,
                    analysis_text,
                }));
            }
            Err(error) => failures.push(format!(
                "{}: {}",
                auth_capture_llm_endpoint_display_name(endpoint),
                error
            )),
        }
    }

    Err(ApiError(BlobError::Upstream(format!(
        "所有已启用 LLM 端点都未返回可用解释：{}",
        failures.join(" | ")
    ))))
}

