async fn update_admin_alert_suppression(
    State(state): State<AppState>,
    Json(input): Json<AdminAlertSuppressionInput>,
) -> Result<Json<Vec<SuppressedAdminAlertRecord>>, ApiError> {
    let alert_id = normalize_admin_alert_id(&input.alert_id).ok_or_else(|| {
        BlobError::Configuration("alert_id is required for alert close state".to_string())
    })?;
    let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
    control_plane.suppressed_admin_alerts =
        normalize_suppressed_admin_alerts(&control_plane.suppressed_admin_alerts);
    control_plane
        .suppressed_admin_alerts
        .retain(|record| record.id != alert_id);
    if input.suppressed {
        let closed_at_unix_ms = current_unix_ms();
        let title = input
            .title
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(alert_id.as_str())
            .to_string();
        control_plane
            .suppressed_admin_alerts
            .push(SuppressedAdminAlertRecord {
                id: alert_id,
                title,
                closed_at_unix_ms,
                delete_after_unix_ms: closed_at_unix_ms
                    .saturating_add(ADMIN_ALERT_CLOSE_RETENTION_MS),
            });
        control_plane.suppressed_admin_alerts =
            normalize_suppressed_admin_alerts(&control_plane.suppressed_admin_alerts);
    }
    persist_control_plane_state(&state.config.control_plane_file, &control_plane)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    Ok(Json(control_plane.suppressed_admin_alerts.clone()))
}

async fn probe_browser_cdp_endpoint(
    State(state): State<AppState>,
    Json(input): Json<BrowserCdpProbeInput>,
) -> Result<Json<BrowserCdpProbePayload>, ApiError> {
    let endpoint_url = normalize_secret_field(input.endpoint_url).ok_or_else(|| {
        BlobError::Configuration("endpoint_url is required for CDP probe".to_string())
    })?;
    let target_selector = normalize_secret_field(input.target_selector);
    let target_timeout_ms = input.target_timeout_ms.filter(|value| *value > 0);
    let target_id = normalize_secret_field(input.id).unwrap_or_else(|| "browser-probe".to_string());
    let endpoint = AuthCaptureBrowserEndpoint {
        id: target_id.clone(),
        label: None,
        endpoint_url,
        enabled: true,
        target_selector,
        target_timeout_ms,
        detected_browser: None,
        detected_protocol_version: None,
        detected_user_agent: None,
        detected_at_unix_ms: None,
    };
    let payload = probe_browser_cdp_endpoint_payload(&endpoint).await;
    let target_id = endpoint.id.clone();
    {
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        if let Some(entry) = control_plane
            .auth_capture_policy
            .browser_endpoints
            .iter_mut()
            .find(|entry| entry.id == target_id)
        {
            apply_browser_probe_metadata_to_endpoint(entry, &payload);
            persist_control_plane_state(&state.config.control_plane_file, &control_plane)
                .map_err(|error| BlobError::Configuration(error.to_string()))?;
        }
    }
    Ok(Json(payload))
}

async fn open_browser_cdp_endpoint_info(
    Json(input): Json<BrowserCdpProbeInput>,
) -> Result<Json<BrowserCdpOpenInfoPayload>, ApiError> {
    let endpoint_url = normalize_secret_field(input.endpoint_url).ok_or_else(|| {
        BlobError::Configuration("endpoint_url is required for CDP endpoint info page".to_string())
    })?;
    let target_selector = normalize_secret_field(input.target_selector);
    let target_timeout_ms = input.target_timeout_ms.filter(|value| *value > 0);
    let target_id =
        normalize_secret_field(input.id).unwrap_or_else(|| "browser-endpoint".to_string());
    let endpoint = AuthCaptureBrowserEndpoint {
        id: target_id.clone(),
        label: None,
        endpoint_url: endpoint_url.clone(),
        enabled: true,
        target_selector: target_selector.clone(),
        target_timeout_ms,
        detected_browser: None,
        detected_protocol_version: None,
        detected_user_agent: None,
        detected_at_unix_ms: None,
    };
    let selector_display = target_selector
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("(default target)")
        .to_string();
    let timeout_display = target_timeout_ms
        .map(|value| value.to_string())
        .unwrap_or_else(|| "default".to_string());
    let timestamp = current_unix_ms().to_string();
    let html = format!(
        "<!doctype html><html><head><meta charset=\"utf-8\"><title>Carrier Gateway CDP Endpoint</title><style>body{{font-family:ui-monospace,Consolas,Menlo,monospace;background:#0b1220;color:#dbeafe;margin:0;padding:24px}}h1{{margin:0 0 16px;font-size:20px}}.card{{background:#111827;border:1px solid #334155;border-radius:8px;padding:16px}}.line{{margin:8px 0;word-break:break-all}}.k{{color:#93c5fd}}.v{{color:#e2e8f0}}</style></head><body><h1>Carrier Gateway CDP Endpoint Identity</h1><div class=\"card\"><div class=\"line\"><span class=\"k\">endpoint_id:</span> <span class=\"v\">{}</span></div><div class=\"line\"><span class=\"k\">endpoint_url:</span> <span class=\"v\">{}</span></div><div class=\"line\"><span class=\"k\">target_selector:</span> <span class=\"v\">{}</span></div><div class=\"line\"><span class=\"k\">target_timeout_ms:</span> <span class=\"v\">{}</span></div><div class=\"line\"><span class=\"k\">opened_at:</span> <span class=\"v\">{}</span></div></div></body></html>",
        target_id, endpoint_url, selector_display, timeout_display, timestamp
    );
    let data_url = format!(
        "data:text/html;charset=utf-8,{}",
        utf8_percent_encode(&html, NON_ALPHANUMERIC)
    );
    let session =
        CdpBrowserFlowSession::connect(&cdp_connection_config_from_browser_endpoint(&endpoint))
            .await
            .map_err(|error| {
                BlobError::Upstream(format!(
                    "failed to connect CDP endpoint for info page: {error}"
                ))
            })?;
    session.navigate(&data_url).await.map_err(|error| {
        BlobError::Upstream(format!(
            "failed to open endpoint info page in CDP browser: {error}"
        ))
    })?;

    Ok(Json(BrowserCdpOpenInfoPayload {
        ok: true,
        target_id,
        endpoint_url,
        target_selector: selector_display,
        target_timeout_ms,
        navigated_url: data_url,
        summary: "opened endpoint info page in the selected CDP browser target".to_string(),
    }))
}

async fn list_auth_capture_prompts(
    State(state): State<AppState>,
) -> Result<Json<Vec<AuthCapturePrompt>>, ApiError> {
    let mut prompts = state
        .auth
        .capture_prompts
        .lock()
        .expect("auth capture prompt store poisoned");
    expire_pending_prompts(&mut prompts);
    let mut prompts = prompts
        .values()
        .cloned()
        .map(|prompt| prompt.sanitized())
        .collect::<Vec<_>>();
    prompts.sort_by_key(|prompt| prompt.created_at_unix_ms);
    prompts.reverse();
    Ok(Json(prompts))
}

