fn build_all_backends(
    config: &AppConfig,
    auth_capture_policy: Option<&AuthCapturePolicy>,
    browser_flow_catalogs: Arc<BrowserFlowCatalogCollection>,
    spool_usage: Arc<SpoolUsageState>,
    provider_resource_stats: Arc<ProviderResourceStatsState>,
) -> Result<Vec<ConfiguredBackend>, BlobError> {
    [
        ProviderId::Stub,
        ProviderId::Unicom,
        ProviderId::Telecom,
        ProviderId::Mobile,
        ProviderId::Onedrive,
    ]
    .into_iter()
    .map(|provider| {
        Ok(ConfiguredBackend {
            provider,
            backend: build_backend(
                config,
                auth_capture_policy,
                Some(browser_flow_catalogs.clone()),
                Some(spool_usage.clone()),
                Some(provider_resource_stats.clone()),
                provider,
            )?,
        })
    })
    .collect()
}

fn backend_for_provider_from(
    backends: &[ConfiguredBackend],
    provider: ProviderId,
) -> Option<DynBackend> {
    backends
        .iter()
        .find(|backend| backend.provider == provider)
        .map(|backend| backend.backend.clone())
}

fn backends_snapshot(state: &AppState) -> Vec<ConfiguredBackend> {
    state
        .backends
        .lock()
        .expect("backend registry poisoned")
        .clone()
}

fn replace_backend_in_registry(
    backends: &mut Vec<ConfiguredBackend>,
    provider: ProviderId,
    backend: DynBackend,
) {
    if let Some(configured) = backends.iter_mut().find(|item| item.provider == provider) {
        configured.backend = backend;
        return;
    }

    backends.push(ConfiguredBackend { provider, backend });
}

fn set_backend_in_registry(state: &AppState, provider: ProviderId, backend: DynBackend) {
    let mut backends = state.backends.lock().expect("backend registry poisoned");
    replace_backend_in_registry(&mut backends, provider, backend);
}

fn rebuild_backend_for_provider(state: &AppState, provider: ProviderId) -> Result<(), BlobError> {
    if provider == ProviderId::Stub {
        return Err(BlobError::Configuration(
            "stub provider does not support credential storage".to_string(),
        ));
    }

    let auth_capture_policy = {
        let control_plane = state.control_plane.lock().expect("control plane poisoned");
        control_plane.auth_capture_policy.clone()
    };
    let backend = build_backend(
        &state.config,
        Some(&auth_capture_policy),
        Some(state.browser_flow_catalogs.clone()),
        Some(state.spool_usage.clone()),
        Some(state.provider_resource_stats.clone()),
        provider,
    )?;
    set_backend_in_registry(state, provider, backend);
    Ok(())
}

fn runtime_topology(state: &AppState) -> TopologyPolicy {
    control_plane_snapshot(state).topology
}

fn backend_for_provider(state: &AppState, provider: ProviderId) -> Result<DynBackend, BlobError> {
    let backends = backends_snapshot(state);
    backend_for_provider_from(&backends, provider).ok_or_else(|| {
        BlobError::Configuration(format!(
            "backend is not configured for provider {}",
            provider.as_str()
        ))
    })
}

fn backend_for_provider_name(state: &AppState, provider: &str) -> Result<DynBackend, String> {
    let provider = ProviderId::parse(provider)
        .map_err(|error| format!("invalid provider name {provider}: {error}"))?;
    backend_for_provider(state, provider).map_err(|error| error.to_string())
}

fn placed_home_provider(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<Option<ProviderId>, BlobError> {
    let placement = state
        .metadata_store
        .object_placement(bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    placement
        .map(|record| {
            ProviderId::parse(&record.provider)
                .map_err(|error| BlobError::Configuration(error.to_string()))
        })
        .transpose()
}

fn placed_home_provider_record(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<Option<(ProviderId, u64)>, BlobError> {
    let placement = state
        .metadata_store
        .object_placement(bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    placement
        .map(|record| {
            Ok((
                ProviderId::parse(&record.provider)
                    .map_err(|error| BlobError::Configuration(error.to_string()))?,
                record.updated_at_unix_ms,
            ))
        })
        .transpose()
}

fn persisted_or_primary_home_provider(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<ProviderId, BlobError> {
    Ok(placed_home_provider(state, bucket, key)?
        .unwrap_or_else(|| runtime_topology(state).primary_provider))
}

async fn eligible_write_candidates_for_object(
    state: &AppState,
    bucket: &str,
    key: &str,
    size: u64,
) -> Result<(Vec<(ProviderId, DynBackend)>, Option<BlobError>), BlobError> {
    let topology = runtime_topology(state);
    let high_speed = current_high_speed_providers(state);
    let write_targets = current_write_targets(state);
    let placement_mode = current_object_placement_mode(state);
    let mut ordered = Vec::new();
    let mut first_quota_error = None;

    match placement_mode {
        ObjectPlacementMode::PreferPrimary => {
            ordered.push(topology.primary_provider);
            for provider in &write_targets {
                if !ordered.contains(provider) {
                    ordered.push(*provider);
                }
            }
        }
        ObjectPlacementMode::PreferHighSpeed | ObjectPlacementMode::BalanceHighSpeed => {
            let mut preferred = write_targets
                .iter()
                .copied()
                .filter(|provider| high_speed.contains(provider))
                .collect::<Vec<_>>();
            for provider in &write_targets {
                if !preferred.contains(provider) {
                    preferred.push(*provider);
                }
            }
            for provider in &preferred {
                if !ordered.contains(provider) {
                    ordered.push(*provider);
                }
            }
            if !ordered.contains(&topology.primary_provider) {
                ordered.push(topology.primary_provider);
            }
        }
    }

    if is_primary_stale(state) {
        if let Some(pos) = ordered.iter().position(|p| *p == topology.primary_provider) {
            ordered.remove(pos);
        }
        if ordered.is_empty() {
            ordered.push(topology.primary_provider);
        }
    }

    let balanced_targets = write_targets
        .iter()
        .copied()
        .filter(|provider| high_speed.contains(provider))
        .collect::<Vec<_>>();
    if matches!(placement_mode, ObjectPlacementMode::BalanceHighSpeed) && balanced_targets.len() > 1
    {
        let mut balanced = Vec::with_capacity(ordered.len());
        let mut high_speed_candidates = balanced_targets;
        if !high_speed_candidates.is_empty() {
            let pivot = stable_object_placement_index(bucket, key, high_speed_candidates.len());
            high_speed_candidates.rotate_left(pivot);
            for provider in high_speed_candidates {
                if !balanced.contains(&provider) {
                    balanced.push(provider);
                }
            }
            for provider in ordered {
                if !balanced.contains(&provider) {
                    balanced.push(provider);
                }
            }
            ordered = balanced;
        }
    }

    let mut candidates = Vec::new();
    for provider in ordered {
        let backend = match backend_for_provider(state, provider) {
            Ok(backend) => backend,
            Err(_) => continue,
        };
        let capabilities = backend.capabilities();
        if !capabilities.write {
            continue;
        }
        if !provider_allowed_for_replication(
            state,
            provider,
            ReplicationOperation::Put,
            bucket,
            key,
        )? {
            continue;
        }
        match ensure_provider_write_allowed_by_quota(
            state,
            provider,
            &backend,
            bucket,
            size,
            "object PUT",
        )
        .await
        {
            Ok(()) => {}
            Err(error) => {
                if first_quota_error.is_none() {
                    first_quota_error = Some(error);
                }
                continue;
            }
        }
        candidates.push((provider, backend));
    }

    Ok((candidates, first_quota_error))
}

fn stable_object_placement_index(bucket: &str, key: &str, len: usize) -> usize {
    if len <= 1 {
        return 0;
    }

    let mut hasher = Sha256::new();
    hasher.update(bucket.as_bytes());
    hasher.update([0]);
    hasher.update(key.as_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0u8; 8];
    bytes.copy_from_slice(&digest[..8]);
    (u64::from_be_bytes(bytes) as usize) % len
}

async fn select_home_write_provider(
    state: &AppState,
    bucket: &str,
    key: &str,
    application: Option<&S3ApplicationIdentity>,
    content_type: Option<&str>,
    size: u64,
) -> Result<(ProviderId, DynBackend), BlobError> {
    if let Some(provider) = placed_home_provider(state, bucket, key)? {
        let backend = backend_for_provider(state, provider)?;
        if backend.capabilities().write {
            ensure_provider_write_allowed_by_quota(
                state,
                provider,
                &backend,
                bucket,
                size,
                "object PUT",
            )
            .await?;
            return Ok((provider, backend));
        }
    }

    let (candidates, first_quota_error) =
        eligible_write_candidates_for_object(state, bucket, key, size).await?;
    let mut candidates = candidates.into_iter().collect::<Vec<_>>();
    if let Some(preferred_provider) = preferred_affiliation_provider_for_application_write(
        state,
        application,
        bucket,
        key,
        content_type,
    ) {
        if let Some(index) = candidates
            .iter()
            .position(|(provider, _)| *provider == preferred_provider)
        {
            candidates.rotate_left(index);
        }
    }
    candidates.into_iter().next().ok_or_else(|| {
        first_quota_error.unwrap_or_else(|| {
            BlobError::Configuration(format!(
                "no writable provider is currently eligible for {bucket}/{key}"
            ))
        })
    })
}

fn persist_object_home_provider(
    state: &AppState,
    provider: ProviderId,
    bucket: &str,
    key: &str,
) -> Result<(), BlobError> {
    state
        .metadata_store
        .upsert_object_placement(provider.as_str(), bucket, key, current_unix_ms())
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to persist object placement for {} {}/{}: {}",
                provider.as_str(),
                bucket,
                key,
                error
            ))
        })
}

fn delete_persisted_object_home_provider(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<(), BlobError> {
    state
        .metadata_store
        .delete_object_placement(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to delete object placement for {bucket}/{key}: {error}"
            ))
        })
}

fn delete_object_metadata_records(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<(), BlobError> {
    #[cfg(test)]
    {
        if let Some(gate) = DELETE_OBJECT_METADATA_FAILURES_REMAINING.get() {
            let mut gate = gate
                .lock()
                .expect("delete-object metadata failure gate lock should not be poisoned");
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(BlobError::Upstream(format!(
                    "failed to delete object metadata for {bucket}/{key}: injected delete metadata failure"
                )));
            }
        }
    }
    state
        .metadata_store
        .delete_object_metadata(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to delete object metadata for {bucket}/{key}: {error}"
            ))
        })
}

fn should_treat_delete_not_found_as_success(error: &BlobError) -> bool {
    matches!(error, BlobError::NotFound(_))
}

fn restore_previous_object_write_state(
    state: &AppState,
    bucket: &str,
    key: &str,
    previous_placement: Option<(ProviderId, u64)>,
    previous_logical: Option<LogicalObjectRecord>,
) {
    match previous_placement {
        Some((provider, updated_at_unix_ms)) => {
            let _ = state.metadata_store.upsert_object_placement(
                provider.as_str(),
                bucket,
                key,
                updated_at_unix_ms,
            );
        }
        None => {
            let _ = delete_persisted_object_home_provider(state, bucket, key);
        }
    }
    restore_logical_object_record(state, previous_logical, bucket, key);
}

fn restore_previous_object_metadata_state(
    state: &AppState,
    bucket: &str,
    key: &str,
    previous_placement: Option<ObjectPlacementRecord>,
    previous_logical_record: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<ObjectProtectionPlanRecord>,
) -> Result<(), BlobError> {
    match previous_placement {
        Some(record) => state
            .metadata_store
            .upsert_object_placement(
                record.provider.as_str(),
                record.bucket.as_str(),
                record.key.as_str(),
                record.updated_at_unix_ms,
            )
            .map_err(|error| {
                BlobError::Upstream(format!(
                    "failed to restore object placement for {bucket}/{key}: {error}"
                ))
            })?,
        None => delete_persisted_object_home_provider(state, bucket, key)?,
    }

    match previous_logical_record {
        Some(record) => persist_logical_object_record(state, &record)?,
        None => delete_logical_object_record(state, bucket, key)?,
    }

    match previous_protection_plan {
        Some(record) => state
            .metadata_store
            .upsert_object_protection_plan(&record)
            .map_err(|error| {
                BlobError::Upstream(format!(
                    "failed to restore object protection plan for {bucket}/{key}: {error}"
                ))
            })?,
        None => delete_object_protection_plan(state, bucket, key)?,
    }

    Ok(())
}

fn ensure_previous_object_metadata_state(
    state: &AppState,
    bucket: &str,
    key: &str,
    previous_placement: Option<ObjectPlacementRecord>,
    previous_logical_record: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<ObjectProtectionPlanRecord>,
) -> Result<(), BlobError> {
    restore_previous_object_metadata_state(
        state,
        bucket,
        key,
        previous_placement.clone(),
        previous_logical_record.clone(),
        previous_protection_plan.clone(),
    )?;

    let restored_placement = state
        .metadata_store
        .object_placement(bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let restored_logical = load_logical_object_record(state, bucket, key)?;
    let restored_plan = state
        .metadata_store
        .object_protection_plan(bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;

    if restored_placement != previous_placement
        || restored_logical != previous_logical_record
        || restored_plan != previous_protection_plan
    {
        restore_previous_object_metadata_state(
            state,
            bucket,
            key,
            previous_placement.clone(),
            previous_logical_record.clone(),
            previous_protection_plan.clone(),
        )?;

        let retry_placement = state
            .metadata_store
            .object_placement(bucket, key)
            .map_err(|error| BlobError::Upstream(error.to_string()))?;
        let retry_logical = load_logical_object_record(state, bucket, key)?;
        let retry_plan = state
            .metadata_store
            .object_protection_plan(bucket, key)
            .map_err(|error| BlobError::Upstream(error.to_string()))?;

        if retry_placement != previous_placement
            || retry_logical != previous_logical_record
            || retry_plan != previous_protection_plan
        {
            return Err(BlobError::Upstream(format!(
                "metadata rollback verification failed for {bucket}/{key}"
            )));
        }
    }

    Ok(())
}

fn provider_has_persisted_objects(
    state: &AppState,
    provider: ProviderId,
    bucket: &str,
) -> Result<bool, BlobError> {
    let placements = state
        .metadata_store
        .object_placements_for_bucket(bucket)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    Ok(placements
        .into_iter()
        .any(|placement| placement.provider == provider.as_str()))
}

fn persisted_home_providers_for_bucket(
    state: &AppState,
    bucket: &str,
) -> Result<Vec<ProviderId>, BlobError> {
    let placements = state
        .metadata_store
        .object_placements_for_bucket(bucket)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let mut providers = Vec::new();
    for placement in placements {
        let provider = match ProviderId::parse(&placement.provider) {
            Ok(provider) => provider,
            Err(_) => continue,
        };
        if !providers.contains(&provider) {
            providers.push(provider);
        }
    }
    Ok(providers)
}

fn current_primary_backend(state: &AppState) -> Result<(ProviderId, DynBackend), BlobError> {
    let topology = runtime_topology(state);
    let provider = topology.primary_provider;
    Ok((provider, backend_for_provider(state, provider)?))
}

fn sync_backends_for_topology(
    state: &AppState,
    topology: &TopologyPolicy,
) -> Vec<ConfiguredBackend> {
    let backends = backends_snapshot(state);
    topology
        .sync_targets
        .iter()
        .filter_map(|provider| {
            backend_for_provider_from(&backends, *provider).map(|backend| ConfiguredBackend {
                provider: *provider,
                backend,
            })
        })
        .collect()
}

fn ordered_fallback_backends(state: &AppState) -> Vec<ConfiguredBackend> {
    let topology = runtime_topology(state);
    let sync_backends = sync_backends_for_topology(state, &topology);
    topology
        .fallback_read_order
        .iter()
        .filter_map(|provider| {
            sync_backends
                .iter()
                .find(|backend| backend.provider == *provider)
                .cloned()
        })
        .collect()
}

fn remember_read_error(first_non_not_found: &mut Option<BlobError>, error: BlobError) {
    if first_non_not_found.is_none() && !matches!(error, BlobError::NotFound(_)) {
        *first_non_not_found = Some(error);
    }
}

fn fallback_not_found(bucket: &str, key: Option<&str>) -> BlobError {
    match key {
        Some(key) => BlobError::NotFound(format!("object not found: {bucket}/{key}")),
        None => BlobError::NotFound(format!("container not found: {bucket}")),
    }
}

fn apply_read_source_headers(headers: &mut HeaderMap, source: ReadSource) {
    headers.insert(
        SOURCE_PROVIDER_HEADER,
        HeaderValue::from_static(source.provider.as_str()),
    );

    if let Some(fallback_from) = source.fallback_from {
        headers.insert(
            FALLBACK_FROM_HEADER,
            HeaderValue::from_static(fallback_from.as_str()),
        );
    }
}

fn merge_object_lists_by_key(
    mut existing: Vec<blob_core::ObjectInfo>,
    additional: Vec<blob_core::ObjectInfo>,
) -> Vec<blob_core::ObjectInfo> {
    let mut seen = existing
        .iter()
        .map(|object| object.key.clone())
        .collect::<HashSet<_>>();
    for object in additional {
        if seen.insert(object.key.clone()) {
            existing.push(object);
        }
    }
    existing.sort_by(|left, right| left.key.cmp(&right.key));
    existing
}

async fn list_objects_from_home_providers(
    state: &AppState,
    bucket: &str,
    prefix: Option<&str>,
) -> Result<Vec<blob_core::ObjectInfo>, BlobError> {
    let placements = state
        .metadata_store
        .object_placements_for_bucket(bucket)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;

    let mut objects = Vec::new();
    let mut seen = HashSet::new();
    for placement in placements {
        if let Some(prefix) = prefix {
            if !placement.key.starts_with(prefix) {
                continue;
            }
        }
        if !seen.insert((placement.provider.clone(), placement.key.clone())) {
            continue;
        }
        let provider = match ProviderId::parse(&placement.provider) {
            Ok(provider) => provider,
            Err(_) => continue,
        };
        let backend = match backend_for_provider(state, provider) {
            Ok(backend) => backend,
            Err(_) => continue,
        };
        match backend.head_object(bucket, &placement.key).await {
            Ok(info) => objects.push(info),
            Err(BlobError::NotFound(_)) => {}
            Err(error) => return Err(error),
        }
    }
    objects.sort_by(|left, right| left.key.cmp(&right.key));
    Ok(objects)
}

async fn list_delimited_objects_from_home_providers(
    state: &AppState,
    bucket: &str,
    prefix: Option<&str>,
    delimiter: &str,
) -> Result<Vec<blob_core::ObjectInfo>, BlobError> {
    let placements = state
        .metadata_store
        .object_placements_for_bucket(bucket)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let prefix = prefix.unwrap_or("");
    let logical_records = logical_object_records_for_bucket(state, bucket)?;

    let mut objects = Vec::new();
    let mut seen = HashSet::new();
    for placement in placements {
        if !placement.key.starts_with(prefix) {
            continue;
        }
        let remainder = &placement.key[prefix.len()..];
        if remainder.is_empty() {
            continue;
        }
        if remainder.contains(delimiter) {
            if seen.insert((placement.provider.clone(), placement.key.clone())) {
                objects.push(blob_core::ObjectInfo {
                    key: placement.key,
                    size: 0,
                    etag: None,
                    content_type: None,
                    last_modified: None,
                });
            }
            continue;
        }
        if !seen.insert((placement.provider.clone(), placement.key.clone())) {
            continue;
        }
        let logical = logical_records.get(placement.key.as_str());
        let size = logical
            .map(|record| record.plaintext_size)
            .unwrap_or_default();
        let updated_at_unix_ms = logical
            .map(|record| record.updated_at_unix_ms)
            .unwrap_or(placement.updated_at_unix_ms);
        objects.push(blob_core::ObjectInfo {
            key: placement.key,
            size,
            etag: None,
            content_type: logical.and_then(|record| record.logical_content_type.clone()),
            last_modified: unix_ms_to_s3_timestamp(updated_at_unix_ms),
        });
    }
    objects.sort_by(|left, right| left.key.cmp(&right.key));
    Ok(objects)
}

fn request_body_limit_bytes(_config: &AppConfig) -> usize {
    // Route-level body caps must not block large streaming uploads before per-handler
    // auth, size, and backend-path checks run.
    usize::MAX
}

fn ensure_object_within_in_memory_limit(config: &AppConfig, size: u64) -> Result<(), S3Error> {
    if size <= config.max_in_memory_object_bytes as u64 {
        Ok(())
    } else {
        Err(S3Error::entity_too_large(format!(
            "Object size {size} exceeds the configured in-memory limit of {} bytes. The current data path is non-streaming; lower object size or raise CCBG_MAX_IN_MEMORY_OBJECT_BYTES.",
            config.max_in_memory_object_bytes
        )))
    }
}

fn ensure_object_within_spool_limit(config: &AppConfig, size: u64) -> Result<(), S3Error> {
    if config.max_spooled_object_bytes == 0 {
        return Err(S3Error::entity_too_large(format!(
            "Object size {size} exceeds the configured in-memory limit of {} bytes, and request-body spooling is disabled. Set CCBG_MAX_SPOOLED_OBJECT_BYTES and use a streaming backend for larger signed uploads.",
            config.max_in_memory_object_bytes
        )));
    }
    if size <= config.max_spooled_object_bytes {
        Ok(())
    } else {
        Err(S3Error::entity_too_large(format!(
            "Object size {size} exceeds the configured spooled request-body limit of {} bytes. Raise CCBG_MAX_SPOOLED_OBJECT_BYTES or lower object size.",
            config.max_spooled_object_bytes
        )))
    }
}

struct SpooledRequestBody {
    file: TokioFile,
    size: u64,
    sha256_hex: String,
    usage: ActiveSpoolLease,
    provider_usage: Option<ActiveProviderSpoolLease>,
}

struct ExistingCopyDestinationRemoteSnapshot {
    body: ExistingCopyDestinationRemoteSnapshotBody,
    size: u64,
    content_type: Option<String>,
}

enum ExistingCopyDestinationRemoteSnapshotBody {
    Bytes(Bytes),
    Spooled(SpooledRequestBody),
}

impl SpooledRequestBody {
    fn attach_provider_tracking(
        &mut self,
        state: &Arc<ProviderResourceStatsState>,
        provider: &str,
    ) {
        if self.provider_usage.is_some() {
            return;
        }
        let mut usage = state.start_spool_tracking(provider);
        usage.update_tracked_bytes(self.size);
        self.provider_usage = Some(usage);
    }

    fn into_object_body(self, chunk_bytes: usize) -> ObjectBody {
        let chunk_bytes = chunk_bytes.max(1);
        ObjectBody::from_stream(futures_util::stream::try_unfold(
            (
                self.file,
                self.usage,
                self.provider_usage,
                vec![0u8; chunk_bytes],
            ),
            move |(mut file, usage, provider_usage, mut buffer)| async move {
                let read = file
                    .read(&mut buffer)
                    .await
                    .map_err(|error| BlobError::BodyStream(error.to_string()))?;
                if read == 0 {
                    return Ok(None);
                }
                let chunk = Bytes::copy_from_slice(&buffer[..read]);
                Ok(Some((chunk, (file, usage, provider_usage, buffer))))
            },
        ))
    }
}

#[derive(Clone, Debug)]
struct StreamingPayloadHashValidation {
    expected_sha256_hex: String,
    observed_sha256_hex: Arc<Mutex<Option<String>>>,
}

impl StreamingPayloadHashValidation {
    fn new(expected_sha256_hex: impl Into<String>) -> Self {
        Self {
            expected_sha256_hex: expected_sha256_hex.into(),
            observed_sha256_hex: Arc::new(Mutex::new(None)),
        }
    }

    fn finish(&self, observed_sha256_hex: String) {
        *self
            .observed_sha256_hex
            .lock()
            .expect("streaming payload hash validation state poisoned") = Some(observed_sha256_hex);
    }

    fn ensure_matched(&self) -> Result<(), S3Error> {
        let observed_sha256_hex = self
            .observed_sha256_hex
            .lock()
            .expect("streaming payload hash validation state poisoned")
            .clone()
            .ok_or_else(|| {
                S3Error::internal_error(
                    "streaming signed upload finished before request-body hash validation completed",
                )
            })?;
        if observed_sha256_hex == self.expected_sha256_hex {
            Ok(())
        } else {
            Err(S3Error::signature_mismatch(
                "x-amz-content-sha256 does not match the request body.",
            ))
        }
    }
}

enum PreparedPutRequestBody {
    Plain {
        body: ObjectBody,
        validation: Option<StreamingPayloadHashValidation>,
        etag_override_source: Option<Arc<dyn PreparedPutRequestEtagOverrideSource>>,
    },
    Spooled(SpooledRequestBody),
}

trait PreparedPutRequestEtagOverrideSource: Send + Sync {
    fn resolved_etag(&self) -> Result<String, S3Error>;
}

impl PreparedPutRequestBody {
    fn plain(body: ObjectBody) -> Self {
        Self::Plain {
            body,
            validation: None,
            etag_override_source: None,
        }
    }

    fn validated(body: ObjectBody, validation: StreamingPayloadHashValidation) -> Self {
        Self::Plain {
            body,
            validation: Some(validation),
            etag_override_source: None,
        }
    }

    fn plain_with_etag_override(
        body: ObjectBody,
        etag_override_source: Arc<dyn PreparedPutRequestEtagOverrideSource>,
    ) -> Self {
        Self::Plain {
            body,
            validation: None,
            etag_override_source: Some(etag_override_source),
        }
    }

    fn into_parts(
        self,
        state: &AppState,
        provider: &str,
    ) -> (
        ObjectBody,
        Option<StreamingPayloadHashValidation>,
        Option<Arc<dyn PreparedPutRequestEtagOverrideSource>>,
    ) {
        match self {
            Self::Plain {
                body,
                validation,
                etag_override_source,
            } => (body, validation, etag_override_source),
            Self::Spooled(mut body) => {
                body.attach_provider_tracking(&state.provider_resource_stats, provider);
                (
                    body.into_object_body(state.config.spooled_body_chunk_bytes),
                    None,
                    None,
                )
            }
        }
    }
}

fn streaming_verified_request_body(
    state: &AppState,
    body: Body,
    expected_sha256_hex: &str,
) -> (ObjectBody, StreamingPayloadHashValidation) {
    let validation = StreamingPayloadHashValidation::new(expected_sha256_hex.to_string());
    let stream_validation = validation.clone();
    let data_plane_stats = state.data_plane_stats.clone();
    let stream = stream::try_unfold(
        (
            body.into_data_stream(),
            Sha256::new(),
            stream_validation,
            data_plane_stats,
        ),
        |(mut body_stream, mut hasher, validation, data_plane_stats)| async move {
            match body_stream.next().await {
                Some(chunk) => {
                    let chunk = chunk.map_err(|error| BlobError::BodyStream(error.to_string()))?;
                    hasher.update(&chunk);
                    data_plane_stats.record_bytes_in(chunk.len() as u64);
                    Ok(Some((
                        chunk,
                        (body_stream, hasher, validation, data_plane_stats),
                    )))
                }
                None => {
                    validation.finish(hex::encode(hasher.finalize()));
                    Ok(None)
                }
            }
        },
    );
    (
        ObjectBody::from_stream(stream)
            .with_known_content_sha256_hex(expected_sha256_hex.to_string()),
        validation,
    )
}

struct PutEncryptionPlan {
    request: CryptoEncryptRequest,
    key_encryption_key: [u8; 32],
    logical_record: LogicalObjectRecord,
}

#[derive(Debug, Clone)]
struct PersistedObjectProtectionPlan {
    sync_targets: Vec<ProviderId>,
    fallback_read_order: Vec<ProviderId>,
    updated_at_unix_ms: u64,
}

impl PutEncryptionPlan {
    fn policy_content_type(&self) -> Option<String> {
        self.logical_record.logical_content_type.clone()
    }

    fn stored_content_type(&self) -> Option<String> {
        Some(STORED_ENCRYPTED_CONTENT_TYPE.to_string())
    }
}

fn build_plaintext_logical_record(
    bucket: &str,
    key: &str,
    plaintext_size: u64,
    content_type: Option<String>,
    application: &S3ApplicationIdentity,
) -> LogicalObjectRecord {
    LogicalObjectRecord {
        bucket: bucket.to_string(),
        key: key.to_string(),
        etag: None,
        application_id: Some(application.application_id.clone()),
        encrypted: false,
        encryption_profile_id: None,
        algorithm: None,
        key_id: None,
        key_source_kind: None,
        key_source_ref: None,
        chunk_plaintext_bytes: None,
        plaintext_size,
        stored_size: plaintext_size,
        logical_content_type: content_type,
        updated_at_unix_ms: current_unix_ms(),
    }
}

fn create_spooled_request_body_file(config: &AppConfig) -> Result<TokioFile, S3Error> {
    let file = match config.body_spool_dir.as_deref() {
        Some(path) => {
            fs::create_dir_all(path).map_err(|error| {
                S3Error::internal_error(format!(
                    "failed to create request-body spool directory {path}: {error}"
                ))
            })?;
            tempfile::tempfile_in(path).map_err(|error| {
                S3Error::internal_error(format!(
                    "failed to create request-body spool file in {path}: {error}"
                ))
            })?
        }
        None => tempfile::tempfile().map_err(|error| {
            S3Error::internal_error(format!(
                "failed to create request-body spool file in system temp directory: {error}"
            ))
        })?,
    };
    Ok(TokioFile::from_std(file))
}

async fn spool_signed_request_body(
    state: &AppState,
    body: Body,
    content_length: Option<u64>,
) -> Result<SpooledRequestBody, S3Error> {
    if let Some(length) = content_length {
        ensure_object_within_spool_limit(&state.config, length)?;
    }

    let mut file = create_spooled_request_body_file(&state.config)?;
    let mut usage = state.spool_usage.start_tracking();
    let mut stream = body.into_data_stream();
    let mut hasher = Sha256::new();
    let mut size = 0u64;

    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|error| {
            S3Error::internal_error(format!("failed to read request body stream: {error}"))
        })?;
        size = size.saturating_add(chunk.len() as u64);
        ensure_object_within_spool_limit(&state.config, size)?;
        file.write_all(&chunk).await.map_err(|error| {
            S3Error::internal_error(format!("failed to write request-body spool file: {error}"))
        })?;
        usage.update_tracked_bytes(size);
        hasher.update(&chunk);
        state.data_plane_stats.record_bytes_in(chunk.len() as u64);
    }

    file.flush().await.map_err(|error| {
        S3Error::internal_error(format!("failed to flush request-body spool file: {error}"))
    })?;
    file.seek(SeekFrom::Start(0)).await.map_err(|error| {
        S3Error::internal_error(format!("failed to rewind request-body spool file: {error}"))
    })?;

    Ok(SpooledRequestBody {
        file,
        size,
        sha256_hex: hex::encode(hasher.finalize()),
        usage,
        provider_usage: None,
    })
}

fn ensure_replication_object_within_in_memory_limit(
    config: &AppConfig,
    job: &ReplicationJob,
) -> Result<(), String> {
    match job.object.size {
        Some(size) if size > config.max_in_memory_object_bytes as u64 => Err(format!(
            "object size {size} exceeds in-memory limit {} for non-streaming replication",
            config.max_in_memory_object_bytes
        )),
        _ => Ok(()),
    }
}

fn storage_scope_for_quota<'a>(
    health: &'a ServiceHealth,
    bucket: &str,
) -> Option<&'a StorageScopeHealth> {
    health
        .scopes
        .iter()
        .find(|scope| scope.writable && scope.container.as_deref() == Some(bucket))
        .or_else(|| {
            let writable_scopes = health
                .scopes
                .iter()
                .filter(|scope| scope.writable)
                .collect::<Vec<_>>();
            if writable_scopes.len() == 1 {
                writable_scopes.into_iter().next()
            } else {
                None
            }
        })
        .or_else(|| {
            if health.scopes.len() == 1 {
                health.scopes.first()
            } else {
                None
            }
        })
}

fn capacity_used_bytes(capacity: &StorageCapacity) -> Option<u64> {
    capacity
        .used_bytes
        .or_else(|| match (capacity.total_bytes, capacity.free_bytes) {
            (Some(total), Some(free)) if total >= free => Some(total - free),
            _ => None,
        })
}

fn capacity_free_bytes(capacity: &StorageCapacity) -> Option<u64> {
    capacity
        .free_bytes
        .or_else(|| match (capacity.total_bytes, capacity.used_bytes) {
            (Some(total), Some(used)) if total >= used => Some(total - used),
            _ => None,
        })
}

async fn ensure_provider_write_allowed_by_quota(
    state: &AppState,
    provider: ProviderId,
    backend: &DynBackend,
    bucket: &str,
    added_bytes: u64,
    action: &str,
) -> Result<(), BlobError> {
    let Some(policy) = provider_quota_policy_for_state(state, provider, bucket)? else {
        return Ok(());
    };

    let health = backend.health().await.map_err(|error| {
        BlobError::Configuration(format!(
            "quota policy blocked {action} to {} bucket '{bucket}' because live capacity could not be refreshed: {error}",
            provider_label(provider),
        ))
    })?;
    let scope = storage_scope_for_quota(&health, bucket).ok_or_else(|| {
        BlobError::Configuration(format!(
            "quota policy blocked {action} to {} bucket '{bucket}' because provider health did not report a matching writable storage scope",
            provider_label(provider),
        ))
    })?;
    if !scope.writable {
        return Err(BlobError::Configuration(format!(
            "quota policy blocked {action} to {} bucket '{bucket}' because scope '{}' is not writable",
            provider_label(provider),
            scope.label,
        )));
    }

    let capacity = scope.capacity.as_ref().ok_or_else(|| {
        BlobError::Configuration(format!(
            "quota policy blocked {action} to {} bucket '{bucket}' because live capacity is unavailable for scope '{}'",
            provider_label(provider),
            scope.label,
        ))
    })?;

    let mut violations = Vec::new();
    if let Some(min_free_bytes) = policy.min_free_bytes {
        let free_before = capacity_free_bytes(capacity).ok_or_else(|| {
            BlobError::Configuration(format!(
                "quota policy blocked {action} to {} bucket '{bucket}' because free capacity is unavailable for scope '{}'",
                provider_label(provider),
                scope.label,
            ))
        })?;
        let projected_free = free_before.saturating_sub(added_bytes);
        if free_before < added_bytes || projected_free < min_free_bytes {
            violations.push(format!(
                "projected free {} B would fall below min_free {} (current free={} B, write={} B)",
                projected_free,
                policy
                    .min_free_raw
                    .as_deref()
                    .unwrap_or("configured threshold"),
                free_before,
                added_bytes,
            ));
        }
    }
    if let Some(max_used_bytes) = policy.max_used_bytes {
        let used_before = capacity_used_bytes(capacity).ok_or_else(|| {
            BlobError::Configuration(format!(
                "quota policy blocked {action} to {} bucket '{bucket}' because used capacity is unavailable for scope '{}'",
                provider_label(provider),
                scope.label,
            ))
        })?;
        let projected_used = used_before.saturating_add(added_bytes);
        if projected_used > max_used_bytes {
            violations.push(format!(
                "projected used {} B would exceed max_used {} (current used={} B, write={} B)",
                projected_used,
                policy
                    .max_used_raw
                    .as_deref()
                    .unwrap_or("configured threshold"),
                used_before,
                added_bytes,
            ));
        }
    }
    if violations.is_empty() {
        return Ok(());
    }

    Err(BlobError::Configuration(format!(
        "quota policy blocked {action} to {} bucket '{bucket}' on scope '{}': {}",
        provider_label(provider),
        scope.label,
        violations.join("; "),
    )))
}

fn provider_allowed_for_replication(
    state: &AppState,
    provider: ProviderId,
    operation: ReplicationOperation,
    bucket: &str,
    key: &str,
) -> Result<bool, BlobError> {
    if provider != ProviderId::Onedrive {
        return Ok(true);
    }

    let policy = current_onedrive_policy(state);
    if matches!(operation, ReplicationOperation::Put) {
        return Ok(policy.replication_enabled && policy.matches_object(bucket, key));
    }

    if policy.replication_enabled && policy.matches_object(bucket, key) {
        return Ok(true);
    }

    let existing = state
        .metadata_store
        .latest_job_for_object(provider.as_str(), bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    Ok(existing.is_some())
}

fn provider_allowed_for_fallback_bucket(
    state: &AppState,
    provider: ProviderId,
    bucket: &str,
) -> bool {
    if provider != ProviderId::Onedrive {
        return true;
    }

    let policy = current_onedrive_policy(state);
    policy.matches_bucket(bucket)
}

fn provider_allowed_for_fallback_object(
    state: &AppState,
    provider: ProviderId,
    bucket: &str,
    key: &str,
) -> bool {
    if provider != ProviderId::Onedrive {
        return true;
    }

    let policy = current_onedrive_policy(state);
    policy.matches_object(bucket, key)
}

fn effective_topology_for_replication(
    state: &AppState,
    operation: ReplicationOperation,
    bucket: &str,
    key: &str,
) -> Result<TopologyPolicy, BlobError> {
    let mut topology = runtime_topology(state);
    let mut effective_targets = Vec::with_capacity(topology.sync_targets.len());
    for provider in &topology.sync_targets {
        if provider_allowed_for_replication(state, *provider, operation.clone(), bucket, key)? {
            effective_targets.push(*provider);
        }
    }
    topology.sync_targets = effective_targets;
    topology.fallback_read_order = topology
        .fallback_read_order
        .into_iter()
        .filter(|provider| topology.sync_targets.contains(provider))
        .collect();
    Ok(topology)
}

fn csv_from_provider_ids(providers: &[ProviderId]) -> String {
    providers
        .iter()
        .map(|provider| provider.as_str())
        .collect::<Vec<_>>()
        .join(",")
}

fn parse_provider_csv(csv: &str) -> Result<Vec<ProviderId>, BlobError> {
    parse_provider_list(csv).map_err(|error| BlobError::Configuration(error.to_string()))
}

fn sanitize_fallback_order_for_sync_targets(
    sync_targets: &[ProviderId],
    fallback_read_order: &[ProviderId],
) -> Vec<ProviderId> {
    fallback_read_order
        .iter()
        .copied()
        .filter(|provider| sync_targets.contains(provider))
        .collect()
}

fn load_object_protection_plan(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<Option<PersistedObjectProtectionPlan>, BlobError> {
    let Some(record) = state
        .metadata_store
        .object_protection_plan(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to load object protection plan for {bucket}/{key}: {error}"
            ))
        })?
    else {
        return Ok(None);
    };

    let sync_targets = parse_provider_csv(&record.sync_targets_csv)?;
    let fallback_read_order = sanitize_fallback_order_for_sync_targets(
        &sync_targets,
        &parse_provider_csv(&record.fallback_read_order_csv)?,
    );
    Ok(Some(PersistedObjectProtectionPlan {
        sync_targets,
        fallback_read_order,
        updated_at_unix_ms: record.updated_at_unix_ms,
    }))
}

fn persist_object_protection_plan(
    state: &AppState,
    bucket: &str,
    key: &str,
    sync_targets: &[ProviderId],
    fallback_read_order: &[ProviderId],
    updated_at_unix_ms: u64,
) -> Result<(), BlobError> {
    let sanitized_fallback =
        sanitize_fallback_order_for_sync_targets(sync_targets, fallback_read_order);
    #[cfg(test)]
    {
        if let Some(gate) = OBJECT_PROTECTION_PLAN_PERSIST_FAILURES_REMAINING.get() {
            let mut gate = gate
                .lock()
                .expect("object protection plan persist failure gate lock should not be poisoned");
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(BlobError::Upstream(format!(
                    "failed to persist object protection plan for {bucket}/{key}: injected object protection plan persist failure"
                )));
            }
        }
    }
    state
        .metadata_store
        .upsert_object_protection_plan(&ObjectProtectionPlanRecord {
            bucket: bucket.to_string(),
            key: key.to_string(),
            sync_targets_csv: csv_from_provider_ids(sync_targets),
            fallback_read_order_csv: csv_from_provider_ids(&sanitized_fallback),
            updated_at_unix_ms,
        })
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to persist object protection plan for {bucket}/{key}: {error}"
            ))
        })
}

fn delete_object_protection_plan(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<(), BlobError> {
    state
        .metadata_store
        .delete_object_protection_plan(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to delete object protection plan for {bucket}/{key}: {error}"
            ))
        })
}

async fn spool_existing_copy_destination_remote_snapshot(
    state: &AppState,
    backend: &DynBackend,
    bucket: &str,
    key: &str,
) -> Result<Option<ExistingCopyDestinationRemoteSnapshot>, BlobError> {
    let payload = match backend.get_object(bucket, key).await {
        Ok(payload) => payload,
        Err(BlobError::NotFound(_)) => return Ok(None),
        Err(error) => return Err(error),
    };
    if payload.info.size <= state.config.max_in_memory_object_bytes as u64 {
        let body = payload.body.collect().await?;
        return Ok(Some(ExistingCopyDestinationRemoteSnapshot {
            body: ExistingCopyDestinationRemoteSnapshotBody::Bytes(body),
            size: payload.info.size,
            content_type: payload.info.content_type,
        }));
    }

    ensure_object_within_spool_limit(&state.config, payload.info.size)
        .map_err(|error| BlobError::Upstream(error.message))?;

    let mut file = create_spooled_request_body_file(&state.config)
        .map_err(|error| BlobError::Upstream(error.message))?;
    let mut usage = state.spool_usage.start_tracking();
    let mut stream = payload.body.into_stream();
    let mut size = 0u64;
    let mut hasher = Sha256::new();

    while let Some(chunk) = stream.next().await {
        let chunk = chunk?;
        size = size.saturating_add(chunk.len() as u64);
        ensure_object_within_spool_limit(&state.config, size)
            .map_err(|error| BlobError::Upstream(error.message))?;
        file.write_all(&chunk)
            .await
            .map_err(|error| BlobError::Upstream(error.to_string()))?;
        usage.update_tracked_bytes(size);
        hasher.update(&chunk);
        state.data_plane_stats.record_bytes_in(chunk.len() as u64);
    }

    file.flush()
        .await
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    file.seek(SeekFrom::Start(0))
        .await
        .map_err(|error| BlobError::Upstream(error.to_string()))?;

    Ok(Some(ExistingCopyDestinationRemoteSnapshot {
        body: ExistingCopyDestinationRemoteSnapshotBody::Spooled(SpooledRequestBody {
            file,
            size,
            sha256_hex: hex::encode(hasher.finalize()),
            usage,
            provider_usage: None,
        }),
        size,
        content_type: payload.info.content_type,
    }))
}

fn gateway_write_ahead_log_matches_application(
    policy: &GatewayWriteAheadLogPolicy,
    application_id: &str,
) -> bool {
    if !policy.enabled || policy.application_ids.is_empty() {
        return false;
    }
    policy
        .application_ids
        .iter()
        .any(|value| value.trim() == application_id)
}

async fn read_small_object_body_bytes(
    body: ObjectBody,
    max_bytes: usize,
) -> Result<Vec<u8>, BlobError> {
    let mut stream = body.into_stream();
    let mut bytes = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk?;
        if bytes.len().saturating_add(chunk.len()) > max_bytes {
            return Err(BlobError::BodyStream(format!(
                "object body exceeded limit of {max_bytes} bytes while reading small payload"
            )));
        }
        bytes.extend_from_slice(&chunk);
    }
    Ok(bytes)
}

async fn persist_gateway_write_ahead_log_record(
    state: &AppState,
    remote_provider: ProviderId,
    record: &GatewayWriteAheadLogRecord,
) -> Result<(), BlobError> {
    let backend = backend_for_provider(state, remote_provider)?;
    if !backend.capabilities().write {
        return Err(BlobError::Configuration(format!(
            "{} cannot accept gateway write-ahead log records because write is disabled",
            provider_label(remote_provider)
        )));
    }
    let body = serde_json::to_vec(record).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to encode gateway write-ahead log record: {error}"
        ))
    })?;
    let body_len = body.len() as u64;
    backend
        .put_object(PutObjectRequest {
            container: GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string(),
            key: record.remote_key.clone(),
            body: ObjectBody::from_bytes(body.into()),
            size: Some(body_len),
            content_type: Some("application/json".to_string()),
            preferred_upload_part_size_bytes: None,
        })
        .await?;
    Ok(())
}

async fn maybe_prepare_gateway_write_ahead_log(
    state: &AppState,
    application: &S3ApplicationIdentity,
    operation: GatewayWriteAheadLogOperation,
    bucket: &str,
    key: &str,
    home_provider: ProviderId,
    logical_record: Option<&LogicalObjectRecord>,
    sync_targets: &[ProviderId],
    fallback_read_order: &[ProviderId],
    previous_placement: Option<ObjectPlacementRecord>,
    previous_logical_record: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<ObjectProtectionPlanRecord>,
) -> Result<Option<GatewayWriteAheadLogContext>, BlobError> {
    let policy = control_plane_snapshot(state).gateway_write_ahead_log_policy;
    if !gateway_write_ahead_log_matches_application(&policy, &application.application_id) {
        return Ok(None);
    }
    let Some(remote_provider) = policy.remote_provider else {
        return Ok(None);
    };

    let prepared_at_unix_ms = current_unix_ms();
    let lsn = state
        .metadata_store
        .allocate_gateway_write_ahead_log_lsn(prepared_at_unix_ms)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let tx_id = format!("gwtx-{lsn}-{prepared_at_unix_ms}");
    let record = GatewayWriteAheadLogRecord {
        schema_version: GATEWAY_WRITE_AHEAD_LOG_FORMAT_VERSION,
        lsn,
        tx_id: tx_id.clone(),
        phase: GatewayWriteAheadLogPhase::Prepare,
        operation,
        application_id: application.application_id.clone(),
        remote_bucket: GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string(),
        remote_key: gateway_write_ahead_log_record_key(
            &state.config,
            &application.application_id,
            lsn,
            &tx_id,
        ),
        bucket: bucket.to_string(),
        key: key.to_string(),
        home_provider,
        logical_record: logical_record.cloned(),
        sync_targets: sync_targets.to_vec(),
        fallback_read_order: fallback_read_order.to_vec(),
        previous_placement,
        previous_logical_record,
        previous_protection_plan,
        prepared_at_unix_ms,
        committed_at_unix_ms: None,
    };
    persist_gateway_write_ahead_log_record(state, remote_provider, &record).await?;
    Ok(Some(GatewayWriteAheadLogContext {
        record,
        remote_provider,
    }))
}

async fn maybe_prepare_gateway_write_ahead_log_record(
    state: &AppState,
    application_id: &str,
    operation: GatewayWriteAheadLogOperation,
    bucket: &str,
    key: &str,
    home_provider: ProviderId,
    logical_record: Option<&LogicalObjectRecord>,
    sync_targets: &[ProviderId],
    fallback_read_order: &[ProviderId],
    previous_placement: Option<ObjectPlacementRecord>,
    previous_logical_record: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<ObjectProtectionPlanRecord>,
) -> Result<Option<GatewayWriteAheadLogContext>, BlobError> {
    let policy = control_plane_snapshot(state).gateway_write_ahead_log_policy;
    if !policy.enabled {
        return Ok(None);
    }
    let Some(remote_provider) = policy.remote_provider else {
        return Ok(None);
    };

    let application_id = application_id.trim();
    let prepared_at_unix_ms = current_unix_ms();
    let lsn = state
        .metadata_store
        .allocate_gateway_write_ahead_log_lsn(prepared_at_unix_ms)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let tx_id = format!("gwtx-{lsn}-{prepared_at_unix_ms}");
    let record = GatewayWriteAheadLogRecord {
        schema_version: GATEWAY_WRITE_AHEAD_LOG_FORMAT_VERSION,
        lsn,
        tx_id: tx_id.clone(),
        phase: GatewayWriteAheadLogPhase::Prepare,
        operation,
        application_id: application_id.to_string(),
        remote_bucket: GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string(),
        remote_key: gateway_write_ahead_log_record_key(&state.config, application_id, lsn, &tx_id),
        bucket: bucket.to_string(),
        key: key.to_string(),
        home_provider,
        logical_record: logical_record.cloned(),
        sync_targets: sync_targets.to_vec(),
        fallback_read_order: fallback_read_order.to_vec(),
        previous_placement,
        previous_logical_record,
        previous_protection_plan,
        prepared_at_unix_ms,
        committed_at_unix_ms: None,
    };
    persist_gateway_write_ahead_log_record(state, remote_provider, &record).await?;
    Ok(Some(GatewayWriteAheadLogContext {
        record,
        remote_provider,
    }))
}

async fn maybe_prepare_gateway_write_ahead_log_metadata_record(
    state: &AppState,
    application_id: &str,
    operation: GatewayWriteAheadLogOperation,
    bucket: &str,
    key: &str,
    home_provider: ProviderId,
    logical_record: Option<&LogicalObjectRecord>,
    protection_plan: Option<&PersistedObjectProtectionPlan>,
    previous_placement: Option<ObjectPlacementRecord>,
    previous_logical_record: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<ObjectProtectionPlanRecord>,
) -> Result<Option<GatewayWriteAheadLogContext>, BlobError> {
    let sync_targets = protection_plan
        .map(|plan| plan.sync_targets.clone())
        .unwrap_or_default();
    let fallback_read_order = protection_plan
        .map(|plan| plan.fallback_read_order.clone())
        .unwrap_or_default();
    maybe_prepare_gateway_write_ahead_log_record(
        state,
        application_id,
        operation,
        bucket,
        key,
        home_provider,
        logical_record,
        &sync_targets,
        &fallback_read_order,
        previous_placement,
        previous_logical_record,
        previous_protection_plan,
    )
    .await
}

async fn mark_gateway_write_ahead_log_committed_or_warn(
    state: &AppState,
    context: Option<&GatewayWriteAheadLogContext>,
    bucket: &str,
    key: &str,
    action: &str,
) {
    if let Some(context) = context {
        if let Err(error) = mark_gateway_write_ahead_log_committed(state, context).await {
            let error_str = error.to_string();
            warn!(
                bucket = %bucket,
                key = %key,
                action = %action,
                remote_provider = context.remote_provider.as_str(),
                error = %error_str,
                "failed to mark gateway write-ahead log as committed"
            );
            let mut runtime = state
                .gateway_write_ahead_log_runtime
                .lock()
                .expect("gateway write-ahead log runtime poisoned");
            runtime.last_commit_failed_at_unix_ms = Some(current_unix_ms());
            runtime.last_commit_error = Some(error_str);
            runtime.last_commit_bucket = Some(bucket.to_string());
            runtime.last_commit_key = Some(key.to_string());
        } else {
            let mut runtime = state
                .gateway_write_ahead_log_runtime
                .lock()
                .expect("gateway write-ahead log runtime poisoned");
            runtime.last_commit_failed_at_unix_ms = None;
            runtime.last_commit_error = None;
            runtime.last_commit_bucket = None;
            runtime.last_commit_key = None;
        }
    }
}

fn latest_replication_job_is_terminal_or_pending(
    state: &AppState,
    target: ProviderId,
    bucket: &str,
    key: &str,
) -> Result<bool, BlobError> {
    let latest = state
        .metadata_store
        .latest_job_for_object(target.as_str(), bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    Ok(matches!(
        latest.map(|job| job.status),
        Some(ReplicationStatus::Pending)
            | Some(ReplicationStatus::RetryScheduled)
            | Some(ReplicationStatus::Completed)
    ))
}

fn replay_should_enqueue_delete_for_target(
    state: &AppState,
    target: ProviderId,
    bucket: &str,
    key: &str,
) -> Result<bool, BlobError> {
    Ok(!latest_replication_job_is_terminal_or_pending(
        state, target, bucket, key,
    )?)
}

async fn mark_gateway_write_ahead_log_committed(
    state: &AppState,
    context: &GatewayWriteAheadLogContext,
) -> Result<(), BlobError> {
    let mut record = context.record.clone();
    record.phase = GatewayWriteAheadLogPhase::Committed;
    record.committed_at_unix_ms = Some(current_unix_ms());
    persist_gateway_write_ahead_log_record(state, context.remote_provider, &record).await
}

async fn load_gateway_write_ahead_log_records_from_remote(
    state: &AppState,
) -> Result<Vec<GatewayWriteAheadLogRecord>, BlobError> {
    let policy = control_plane_snapshot(state).gateway_write_ahead_log_policy;
    if !policy.enabled {
        return Ok(Vec::new());
    }
    let Some(remote_provider) = policy.remote_provider else {
        return Ok(Vec::new());
    };
    let backend = backend_for_provider(state, remote_provider)?;
    let objects = backend
        .list_objects(ListObjectsRequest {
            container: Some(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string()),
            prefix: Some(format!(
                "{}/",
                gateway_write_ahead_log_remote_prefix(&state.config)
            )),
            limit: None,
        })
        .await?;
    let replay_floor_lsn = state
        .metadata_store
        .gateway_write_ahead_log_replay_floor_lsn()
        .map_err(|error| BlobError::Upstream(error.to_string()))?
        .unwrap_or(0);
    let mut records = Vec::new();
    for object in objects {
        let payload = backend
            .get_object(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET, &object.key)
            .await?;
        let bytes = read_small_object_body_bytes(payload.body, 256 * 1024).await?;
        let record =
            serde_json::from_slice::<GatewayWriteAheadLogRecord>(&bytes).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to decode gateway write-ahead log record {}: {error}",
                    object.key
                ))
            })?;
        if record.schema_version != GATEWAY_WRITE_AHEAD_LOG_FORMAT_VERSION {
            continue;
        }
        if record.lsn <= replay_floor_lsn {
            continue;
        }
        records.push(record);
    }
    records.sort_by(|left, right| left.lsn.cmp(&right.lsn).then(left.tx_id.cmp(&right.tx_id)));
    Ok(records)
}

fn increment_wal_operation_count(
    counts: &mut GatewayWriteAheadLogOperationCountPayload,
    operation: &GatewayWriteAheadLogOperation,
) {
    match operation {
        GatewayWriteAheadLogOperation::Put => {
            counts.put = counts.put.saturating_add(1);
        }
        GatewayWriteAheadLogOperation::Delete => {
            counts.delete = counts.delete.saturating_add(1);
        }
        GatewayWriteAheadLogOperation::MetadataSync => {
            counts.metadata_sync = counts.metadata_sync.saturating_add(1);
        }
    }
}

async fn inspect_gateway_write_ahead_log_remote_status(
    state: &AppState,
) -> Result<GatewayWriteAheadLogStatusPayload, BlobError> {
    let control_plane = control_plane_snapshot(state);
    let policy = control_plane.gateway_write_ahead_log_policy;
    let wal_state = state
        .metadata_store
        .gateway_write_ahead_log_state()
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let mut status = GatewayWriteAheadLogStatusPayload {
        policy: gateway_write_ahead_log_policy_payload(state.config.as_ref(), &policy),
        state: gateway_write_ahead_log_state_payload(wal_state.clone()),
        remote: GatewayWriteAheadLogRemoteSummaryPayload {
            remote_provider: policy
                .remote_provider
                .map(|provider| provider.as_str().to_string()),
            ..GatewayWriteAheadLogRemoteSummaryPayload::default()
        },
        cleanup_required: false,
        cleanup_supported: false,
        last_refreshed_at_unix_ms: Some(current_unix_ms()),
    };
    let Some(remote_provider) = policy.remote_provider else {
        cache_gateway_write_ahead_log_status(state, status.clone());
        return Ok(status);
    };
    let backend = backend_for_provider(state, remote_provider)?;
    let capabilities = backend.capabilities();
    status.remote.delete_supported = capabilities.delete;
    status.cleanup_supported = capabilities.delete;
    let objects = backend
        .list_objects(ListObjectsRequest {
            container: Some(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string()),
            prefix: Some(format!(
                "{}/",
                gateway_write_ahead_log_remote_prefix(&state.config)
            )),
            limit: None,
        })
        .await?;
    let checkpoint_lsn = wal_state.last_checkpoint_lsn.unwrap_or(0);
    for object in objects {
        let Some(lsn) = parse_gateway_write_ahead_log_lsn_from_key(&object.key) else {
            continue;
        };
        status.remote.total_records = status.remote.total_records.saturating_add(1);
        status.remote.newest_record_lsn =
            Some(status.remote.newest_record_lsn.unwrap_or(0).max(lsn)).filter(|value| *value > 0);
        let payload = backend
            .get_object(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET, &object.key)
            .await?;
        let bytes = read_small_object_body_bytes(payload.body, 256 * 1024).await?;
        let record =
            serde_json::from_slice::<GatewayWriteAheadLogRecord>(&bytes).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to decode gateway write-ahead log record {}: {error}",
                    object.key
                ))
            })?;
        if record.schema_version != GATEWAY_WRITE_AHEAD_LOG_FORMAT_VERSION {
            continue;
        }
        match record.phase {
            GatewayWriteAheadLogPhase::Committed => {
                increment_wal_operation_count(&mut status.remote.by_operation, &record.operation);
                increment_wal_operation_count(
                    &mut status.remote.by_phase_operation.committed,
                    &record.operation,
                );
                status.remote.committed_records = status.remote.committed_records.saturating_add(1);
                if checkpoint_lsn > 0 && record.lsn <= checkpoint_lsn {
                    status.remote.cleanup_ready_records =
                        status.remote.cleanup_ready_records.saturating_add(1);
                } else {
                    status.remote.cleanup_blocked_records =
                        status.remote.cleanup_blocked_records.saturating_add(1);
                }
            }
            GatewayWriteAheadLogPhase::Prepare => {
                increment_wal_operation_count(&mut status.remote.by_operation, &record.operation);
                increment_wal_operation_count(
                    &mut status.remote.by_phase_operation.prepare,
                    &record.operation,
                );
                status.remote.prepare_records = status.remote.prepare_records.saturating_add(1);
                status.remote.cleanup_blocked_records =
                    status.remote.cleanup_blocked_records.saturating_add(1);
                status.remote.oldest_pending_commit_lsn = Some(
                    status
                        .remote
                        .oldest_pending_commit_lsn
                        .map(|current| current.min(record.lsn))
                        .unwrap_or(record.lsn),
                );
            }
        }
    }
    status.cleanup_required =
        status.remote.cleanup_ready_records > 0 || status.remote.cleanup_blocked_records > 0;
    cache_gateway_write_ahead_log_status(state, status.clone());
    Ok(status)
}

async fn cleanup_gateway_write_ahead_log_remote(
    state: &AppState,
) -> Result<GatewayWriteAheadLogStatusPayload, BlobError> {
    let control_plane = control_plane_snapshot(state);
    let policy = control_plane.gateway_write_ahead_log_policy;
    let Some(remote_provider) = policy.remote_provider else {
        let status = inspect_gateway_write_ahead_log_remote_status(state).await?;
        return Ok(status);
    };
    let backend = backend_for_provider(state, remote_provider)?;
    if !backend.capabilities().delete {
        let mut status = inspect_gateway_write_ahead_log_remote_status(state).await?;
        status.remote.latest_error = Some(format!(
            "{} 不支持删除，已 checkpoint 的远端写前日志不能自动清理",
            provider_label(remote_provider)
        ));
        cache_gateway_write_ahead_log_status(state, status.clone());
        return Ok(status);
    }
    let checkpoint_lsn = state
        .metadata_store
        .gateway_write_ahead_log_state()
        .map_err(|error| BlobError::Upstream(error.to_string()))?
        .last_checkpoint_lsn
        .unwrap_or(0);
    if checkpoint_lsn == 0 {
        let status = inspect_gateway_write_ahead_log_remote_status(state).await?;
        return Ok(status);
    }
    let objects = backend
        .list_objects(ListObjectsRequest {
            container: Some(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string()),
            prefix: Some(format!(
                "{}/",
                gateway_write_ahead_log_remote_prefix(&state.config)
            )),
            limit: None,
        })
        .await?;
    for object in objects {
        let Some(lsn) = parse_gateway_write_ahead_log_lsn_from_key(&object.key) else {
            continue;
        };
        if lsn > checkpoint_lsn {
            continue;
        }
        let payload = backend
            .get_object(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET, &object.key)
            .await?;
        let bytes = read_small_object_body_bytes(payload.body, 256 * 1024).await?;
        let record =
            serde_json::from_slice::<GatewayWriteAheadLogRecord>(&bytes).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to decode gateway write-ahead log record {}: {error}",
                    object.key
                ))
            })?;
        if record.schema_version != GATEWAY_WRITE_AHEAD_LOG_FORMAT_VERSION
            || record.phase != GatewayWriteAheadLogPhase::Committed
        {
            continue;
        }
        backend
            .delete_object(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET, &object.key)
            .await?;
    }
    inspect_gateway_write_ahead_log_remote_status(state).await
}

fn replay_should_enqueue_replication_for_target(
    state: &AppState,
    target: ProviderId,
    bucket: &str,
    key: &str,
) -> Result<bool, BlobError> {
    let latest = state
        .metadata_store
        .latest_job_for_object(target.as_str(), bucket, key)
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    Ok(match latest.map(|job| job.status) {
        Some(ReplicationStatus::Pending)
        | Some(ReplicationStatus::RetryScheduled)
        | Some(ReplicationStatus::Completed) => false,
        Some(ReplicationStatus::Failed) | None => true,
    })
}

async fn replay_gateway_write_ahead_log_from_remote(state: &AppState) -> Result<(), BlobError> {
    let records = load_gateway_write_ahead_log_records_from_remote(state).await?;
    let mut last_replayed_lsn = None::<u64>;
    for record in records {
        match record.operation {
            GatewayWriteAheadLogOperation::Put | GatewayWriteAheadLogOperation::MetadataSync => {
                let home_backend = backend_for_provider(state, record.home_provider)?;
                let home_exists = home_backend
                    .get_object(&record.bucket, &record.key)
                    .await
                    .is_ok();
                if !home_exists {
                    if record.operation == GatewayWriteAheadLogOperation::Put {
                        restore_previous_object_metadata_state(
                            state,
                            &record.bucket,
                            &record.key,
                            record.previous_placement.clone(),
                            record.previous_logical_record.clone(),
                            record.previous_protection_plan.clone(),
                        )?;
                    }
                    last_replayed_lsn = Some(last_replayed_lsn.unwrap_or(0).max(record.lsn));
                    continue;
                }

                persist_object_home_provider(
                    state,
                    record.home_provider,
                    &record.bucket,
                    &record.key,
                )?;
                if let Some(logical_record) = record.logical_record.as_ref() {
                    persist_logical_object_record(state, logical_record)?;
                } else {
                    delete_logical_object_record(state, &record.bucket, &record.key)?;
                }
                persist_object_protection_plan(
                    state,
                    &record.bucket,
                    &record.key,
                    &record.sync_targets,
                    &record.fallback_read_order,
                    record
                        .committed_at_unix_ms
                        .unwrap_or(record.prepared_at_unix_ms),
                )?;

                let mut missing_targets = Vec::new();
                for target in &record.sync_targets {
                    if replay_should_enqueue_replication_for_target(
                        state,
                        *target,
                        &record.bucket,
                        &record.key,
                    )? {
                        missing_targets.push(*target);
                    }
                }
                if missing_targets.is_empty() {
                    last_replayed_lsn = Some(last_replayed_lsn.unwrap_or(0).max(record.lsn));
                    continue;
                }
                let recovery_topology = TopologyPolicy {
                    primary_provider: record.home_provider,
                    sync_targets: missing_targets.clone(),
                    fallback_read_order: sanitize_fallback_order_for_sync_targets(
                        &missing_targets,
                        &record.fallback_read_order,
                    ),
                    onedrive_enabled: missing_targets.contains(&ProviderId::Onedrive),
                    replication_mode: ReplicationMode::AsyncBackup,
                };
                let jobs = state.replication.enqueue_put(
                    &recovery_topology,
                    Some(record.home_provider.as_str().to_string()),
                    record.bucket.clone(),
                    record.key.clone(),
                    None,
                    record
                        .logical_record
                        .as_ref()
                        .map(|value| value.stored_size)
                        .unwrap_or(0),
                    record
                        .logical_record
                        .as_ref()
                        .and_then(|value| value.logical_content_type.clone()),
                );
                state
                    .metadata_store
                    .enqueue_jobs(&jobs)
                    .map_err(|error| BlobError::Upstream(error.to_string()))?;
                last_replayed_lsn = Some(last_replayed_lsn.unwrap_or(0).max(record.lsn));
            }
            GatewayWriteAheadLogOperation::Delete => {
                let home_backend = backend_for_provider(state, record.home_provider)?;
                let home_exists = home_backend
                    .get_object(&record.bucket, &record.key)
                    .await
                    .is_ok();
                if record.phase == GatewayWriteAheadLogPhase::Prepare && home_exists {
                    last_replayed_lsn = Some(last_replayed_lsn.unwrap_or(0).max(record.lsn));
                    continue;
                }
                delete_persisted_object_home_provider(state, &record.bucket, &record.key)?;
                delete_object_protection_plan(state, &record.bucket, &record.key)?;
                delete_logical_object_record(state, &record.bucket, &record.key)?;
                let mut missing_targets = Vec::new();
                for target in &record.sync_targets {
                    if replay_should_enqueue_delete_for_target(
                        state,
                        *target,
                        &record.bucket,
                        &record.key,
                    )? {
                        missing_targets.push(*target);
                    }
                }
                if !missing_targets.is_empty() {
                    let delete_topology = TopologyPolicy {
                        primary_provider: record.home_provider,
                        sync_targets: missing_targets,
                        fallback_read_order: Vec::new(),
                        onedrive_enabled: false,
                        replication_mode: ReplicationMode::AsyncBackup,
                    };
                    let jobs = state.replication.enqueue_delete(
                        &delete_topology,
                        Some(record.home_provider.as_str().to_string()),
                        record.bucket.clone(),
                        record.key.clone(),
                    );
                    state
                        .metadata_store
                        .enqueue_jobs(&jobs)
                        .map_err(|error| BlobError::Upstream(error.to_string()))?;
                }
                last_replayed_lsn = Some(last_replayed_lsn.unwrap_or(0).max(record.lsn));
            }
        }
    }
    if let Some(lsn) = last_replayed_lsn {
        state
            .metadata_store
            .update_gateway_write_ahead_log_replayed_lsn(lsn, current_unix_ms())
            .map_err(|error| BlobError::Upstream(error.to_string()))?;
    }
    Ok(())
}

fn apply_content_policy_to_topology(
    state: &AppState,
    mut topology: TopologyPolicy,
    application: Option<&S3ApplicationIdentity>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> Result<TopologyPolicy, BlobError> {
    let Some(policy) = matching_content_policy(
        state,
        application.map(|value| value.application_id.as_str()),
        bucket,
        key,
        content_type,
    ) else {
        return Ok(topology);
    };

    if !policy.sync_targets.is_empty() {
        topology.sync_targets = policy.sync_targets;
    }
    if !policy.fallback_read_order.is_empty() {
        topology.fallback_read_order = policy.fallback_read_order;
    }

    TopologyPolicy::from_input(TopologyInput {
        primary_provider: topology.primary_provider,
        sync_targets: topology.sync_targets,
        fallback_read_order: topology.fallback_read_order,
        onedrive_enabled: topology.onedrive_enabled,
        replication_mode: topology.replication_mode,
    })
    .map_err(|error| {
        BlobError::Configuration(format!(
            "content policy {} produced invalid topology for {bucket}/{key}: {error}",
            policy.id
        ))
    })
}

async fn effective_topology_for_replication_put(
    state: &AppState,
    application: Option<&S3ApplicationIdentity>,
    bucket: &str,
    key: &str,
    home_provider: Option<ProviderId>,
    size: u64,
    content_type: Option<&str>,
) -> Result<TopologyPolicy, BlobError> {
    let topology = runtime_topology(state);
    let mut topology =
        apply_content_policy_to_topology(state, topology, application, bucket, key, content_type)?;
    let mut effective_targets = Vec::with_capacity(topology.sync_targets.len());
    for provider in &topology.sync_targets {
        if provider_allowed_for_replication(
            state,
            *provider,
            ReplicationOperation::Put,
            bucket,
            key,
        )? {
            effective_targets.push(*provider);
        }
    }
    topology.sync_targets = effective_targets;
    topology.fallback_read_order = topology
        .fallback_read_order
        .into_iter()
        .filter(|provider| topology.sync_targets.contains(provider))
        .collect();

    let mut allowed_targets = Vec::with_capacity(topology.sync_targets.len());
    for provider in &topology.sync_targets {
        let backend = backend_for_provider(state, *provider)?;
        match ensure_provider_write_allowed_by_quota(
            state,
            *provider,
            &backend,
            bucket,
            size,
            "replication target write",
        )
        .await
        {
            Ok(()) => allowed_targets.push(*provider),
            Err(error) => {
                warn!(
                    provider = provider.as_str(),
                    bucket = %bucket,
                    key = %key,
                    size,
                    error = %error,
                    "skipping replication target because quota policy rejected the write"
                );
            }
        }
    }
    topology.sync_targets = allowed_targets;
    if let Some(home_provider) = home_provider {
        topology
            .sync_targets
            .retain(|provider| *provider != home_provider);
    }
    topology.fallback_read_order = topology
        .fallback_read_order
        .into_iter()
        .filter(|provider| topology.sync_targets.contains(provider))
        .collect();
    Ok(topology)
}

fn topology_policy_from_persisted_protection_plan(
    state: &AppState,
    plan: &PersistedObjectProtectionPlan,
) -> TopologyPolicy {
    let runtime = runtime_topology(state);
    TopologyPolicy {
        primary_provider: runtime.primary_provider,
        sync_targets: plan.sync_targets.clone(),
        fallback_read_order: sanitize_fallback_order_for_sync_targets(
            &plan.sync_targets,
            &plan.fallback_read_order,
        ),
        onedrive_enabled: runtime.onedrive_enabled
            || plan.sync_targets.contains(&ProviderId::Onedrive),
        replication_mode: runtime.replication_mode,
    }
}

fn removed_sync_targets_for_desired_topology(
    previous_plan: Option<&PersistedObjectProtectionPlan>,
    desired_topology: &TopologyPolicy,
) -> Vec<ProviderId> {
    let Some(previous_plan) = previous_plan else {
        return Vec::new();
    };

    previous_plan
        .sync_targets
        .iter()
        .copied()
        .filter(|provider| !desired_topology.sync_targets.contains(provider))
        .collect()
}

async fn enqueue_replication_put_for_object(
    state: &AppState,
    source_provider: ProviderId,
    bucket: &str,
    key: &str,
    object: &blob_core::ObjectInfo,
    protection_plan: Option<&PersistedObjectProtectionPlan>,
) -> Result<Vec<ReplicationJob>, BlobError> {
    #[cfg(test)]
    {
        if let Some(gate) = ADMIN_OBJECT_ACTION_REPLICATION_PLAN_FAILURES_REMAINING.get() {
            let mut gate = gate.lock().expect(
                "admin object-action replication plan failure gate lock should not be poisoned",
            );
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(BlobError::Upstream(
                    "injected admin object-action replication plan failure".to_string(),
                ));
            }
        }
    }
    let effective_topology = match protection_plan {
        Some(plan) => topology_policy_from_persisted_protection_plan(state, plan),
        None => {
            if let Some(persisted) = load_object_protection_plan(state, bucket, key)? {
                topology_policy_from_persisted_protection_plan(state, &persisted)
            } else {
                effective_topology_for_replication_put(
                    state,
                    None,
                    bucket,
                    key,
                    Some(source_provider),
                    object.size,
                    object.content_type.as_deref(),
                )
                .await?
            }
        }
    };
    Ok(state.replication.enqueue_put(
        &effective_topology,
        Some(source_provider.as_str().to_string()),
        bucket.to_string(),
        key.to_string(),
        object.etag.clone(),
        object.size,
        object.content_type.clone(),
    ))
}

async fn enqueue_copy_object_replication_plan(
    state: &AppState,
    source_provider: ProviderId,
    bucket: &str,
    key: &str,
    object: &blob_core::ObjectInfo,
    protection_plan: Option<&PersistedObjectProtectionPlan>,
) -> Result<Vec<ReplicationJob>, BlobError> {
    #[cfg(test)]
    {
        if let Some(gate) = COPY_OBJECT_REPLICATION_PLAN_FAILURES_REMAINING.get() {
            let mut gate = gate
                .lock()
                .expect("copy-object replication plan failure gate lock should not be poisoned");
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(BlobError::Upstream(
                    "injected copy-object replication plan failure".to_string(),
                ));
            }
        }
    }
    enqueue_replication_put_for_object(state, source_provider, bucket, key, object, protection_plan)
        .await
}

fn enqueue_copy_object_replication_jobs(
    state: &AppState,
    bucket: &str,
    key: &str,
    jobs: &[ReplicationJob],
) -> Result<(), metadata_store::MetadataError> {
    #[cfg(test)]
    {
        if let Some(gate) = COPY_OBJECT_REPLICATION_ENQUEUE_FAILURES_REMAINING.get() {
            let mut gate = gate
                .lock()
                .expect("copy-object replication enqueue failure gate lock should not be poisoned");
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(metadata_store::MetadataError::Io {
                    path: PathBuf::from("injected-copy-object-replication-enqueue-failure"),
                    source: std::io::Error::other(
                        "injected copy-object replication enqueue failure",
                    ),
                });
            }
        }
    }
    state.metadata_store.enqueue_jobs(jobs)
}

fn enqueue_delete_object_replication_jobs(
    state: &AppState,
    bucket: &str,
    key: &str,
    jobs: &[ReplicationJob],
) -> Result<(), metadata_store::MetadataError> {
    #[cfg(test)]
    {
        if let Some(gate) = DELETE_OBJECT_REPLICATION_ENQUEUE_FAILURES_REMAINING.get() {
            let mut gate = gate.lock().expect(
                "delete-object replication enqueue failure gate lock should not be poisoned",
            );
            let scope = copy_object_failure_scope_key(bucket, key);
            if let Some(remaining) = gate.get_mut(scope.as_str()) {
                if *remaining > 0 {
                    *remaining -= 1;
                }
                if *remaining == 0 {
                    gate.remove(scope.as_str());
                }
                return Err(metadata_store::MetadataError::Io {
                    path: PathBuf::from("injected-delete-object-replication-enqueue-failure"),
                    source: std::io::Error::other(
                        "injected delete-object replication enqueue failure",
                    ),
                });
            }
        }
    }
    state.metadata_store.enqueue_jobs(jobs)
}

