fn all_gateway_backup_providers() -> [ProviderId; 4] {
    [
        ProviderId::Unicom,
        ProviderId::Telecom,
        ProviderId::Mobile,
        ProviderId::Onedrive,
    ]
}

fn gateway_backup_filename(instance_id: &str, exported_at_unix_ms: u64) -> String {
    let normalized = instance_id
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string();
    let stem = if normalized.is_empty() {
        "gateway".to_string()
    } else {
        normalized
    };
    format!("ccbg-backup-{stem}-{exported_at_unix_ms}.ccbgbak")
}

fn normalize_backup_password(value: &str) -> Result<String, BlobError> {
    let password = value.trim().to_string();
    if password.len() < 8 {
        return Err(BlobError::Configuration(
            "备份密码至少需要 8 个字符".to_string(),
        ));
    }
    Ok(password)
}

fn gateway_backup_password_secret_path(config: &AppConfig) -> PathBuf {
    FsPath::new(&config.credentials_dir).join("gateway-backup-password.txt")
}

fn load_gateway_backup_password(config: &AppConfig) -> Result<Option<String>, BlobError> {
    let path = gateway_backup_password_secret_path(config);
    match fs::read_to_string(&path) {
        Ok(raw) => Ok(normalize_secret_field(Some(raw))),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(BlobError::Configuration(format!(
            "failed to read gateway backup password file {}: {error}",
            path.display()
        ))),
    }
}

fn persist_gateway_backup_password(config: &AppConfig, password: &str) -> Result<(), BlobError> {
    let password = normalize_backup_password(password)?;
    let path = gateway_backup_password_secret_path(config);
    let parent = path.parent().ok_or_else(|| {
        BlobError::Configuration(format!(
            "gateway backup password path has no parent: {}",
            path.display()
        ))
    })?;
    fs::create_dir_all(parent).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to create gateway backup password dir {}: {error}",
            parent.display()
        ))
    })?;
    atomic_write_text_file(&path, &password, 0o600, "gateway backup password").map_err(
        |error| {
            BlobError::Configuration(format!(
                "failed to write gateway backup password file {}: {error}",
                path.display()
            ))
        },
    )?;
    Ok(())
}

fn remove_gateway_backup_password(config: &AppConfig) -> Result<(), BlobError> {
    let path = gateway_backup_password_secret_path(config);
    match fs::remove_file(&path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(BlobError::Configuration(format!(
            "failed to remove gateway backup password file {}: {error}",
            path.display()
        ))),
    }
}

fn normalize_gateway_backup_local_directory(
    value: impl Into<String>,
    default_value: &str,
) -> String {
    let candidate = value.into();
    let normalized = candidate.trim();
    if normalized.is_empty() {
        return default_value.to_string();
    }
    FsPath::new(normalized).display().to_string()
}

fn normalize_gateway_backup_policy(
    mut policy: GatewayBackupPolicy,
    default_policy: &GatewayBackupPolicy,
    onedrive_enabled: bool,
) -> Result<GatewayBackupPolicy, BlobError> {
    policy.interval_minutes = policy.interval_minutes.clamp(10, 7 * 24 * 60);
    policy.local_directory = normalize_gateway_backup_local_directory(
        policy.local_directory,
        &default_policy.local_directory,
    );
    policy.local_retention_count = policy.local_retention_count.clamp(1, 365);
    policy.remote_retention_count = policy.remote_retention_count.clamp(1, 365);
    if matches!(policy.remote_provider, Some(ProviderId::Stub)) {
        return Err(BlobError::Configuration(
            "自动备份不能写入 stub 提供方".to_string(),
        ));
    }
    if matches!(policy.remote_provider, Some(ProviderId::Onedrive)) && !onedrive_enabled {
        return Err(BlobError::Configuration(
            "当前网关没有启用 OneDrive，不能把它选为自动备份目标".to_string(),
        ));
    }
    if policy.enabled && !policy.local_enabled && !policy.remote_enabled {
        return Err(BlobError::Configuration(
            "启用自动备份前，至少要打开一个备份落点（本地或云端）".to_string(),
        ));
    }
    if policy.remote_enabled && policy.remote_provider.is_none() {
        return Err(BlobError::Configuration(
            "启用云端自动备份前，必须先选择一个目标云盘".to_string(),
        ));
    }
    Ok(policy)
}

fn normalize_gateway_write_ahead_log_policy(
    mut policy: GatewayWriteAheadLogPolicy,
    onedrive_enabled: bool,
    applications: &[DataPlaneApplication],
) -> Result<GatewayWriteAheadLogPolicy, BlobError> {
    policy.application_ids = normalize_string_list(&policy.application_ids);
    if matches!(policy.remote_provider, Some(ProviderId::Stub)) {
        return Err(BlobError::Configuration(
            "远端写前日志不能写入 stub 提供方".to_string(),
        ));
    }
    if matches!(policy.remote_provider, Some(ProviderId::Onedrive)) && !onedrive_enabled {
        return Err(BlobError::Configuration(
            "当前网关没有启用 OneDrive，不能把它选为远端写前日志目标".to_string(),
        ));
    }
    if policy.enabled && policy.remote_provider.is_none() {
        return Err(BlobError::Configuration(
            "启用远端写前日志前，必须先选择一个日志云盘".to_string(),
        ));
    }
    if policy.enabled && policy.application_ids.is_empty() {
        return Err(BlobError::Configuration(
            "启用远端写前日志前，至少要选择一个关键应用 ID".to_string(),
        ));
    }
    let application_ids = applications
        .iter()
        .map(|app| app.id.as_str())
        .collect::<HashSet<_>>();
    for application_id in &policy.application_ids {
        if !application_ids.contains(application_id.as_str()) {
            return Err(BlobError::Configuration(format!(
                "远端写前日志引用了不存在的应用 ID: {application_id}"
            )));
        }
    }
    Ok(policy)
}

fn normalize_gateway_backup_history(mut history: GatewayBackupHistory) -> GatewayBackupHistory {
    history.last_trigger = normalize_secret_field(history.last_trigger);
    history.last_result = normalize_secret_field(history.last_result);
    history.last_local_filename = normalize_secret_field(history.last_local_filename);
    history.last_local_path = normalize_secret_field(history.last_local_path);
    history.last_remote_bucket = normalize_secret_field(history.last_remote_bucket);
    history.last_remote_key = normalize_secret_field(history.last_remote_key);
    history.last_error = normalize_secret_field(history.last_error);
    history
}

fn parse_gateway_write_ahead_log_lsn_from_key(key: &str) -> Option<u64> {
    key.rsplit('/')
        .next()
        .and_then(|name| name.split_once('-').map(|(prefix, _)| prefix))
        .and_then(|prefix| prefix.parse::<u64>().ok())
}

fn gateway_backup_remote_prefix(config: &AppConfig) -> String {
    format!(
        "{}/{}",
        effective_managed_root_prefix_from_parts(
            None,
            config.managed_root_base.as_str(),
            config.managed_root_suffix.as_str(),
        ),
        GATEWAY_BACKUP_REMOTE_SUBDIR
    )
}

fn gateway_write_ahead_log_remote_prefix(config: &AppConfig) -> String {
    format!(
        "{}/{}",
        effective_managed_root_prefix_from_parts(
            None,
            config.managed_root_base.as_str(),
            config.managed_root_suffix.as_str(),
        ),
        GATEWAY_WRITE_AHEAD_LOG_REMOTE_SUBDIR
    )
}

fn sanitize_gateway_write_ahead_log_path_component(value: &str) -> String {
    let normalized = value
        .trim()
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
                ch
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string();
    if normalized.is_empty() {
        "unknown".to_string()
    } else {
        normalized
    }
}

fn gateway_write_ahead_log_record_key(
    config: &AppConfig,
    application_id: &str,
    lsn: u64,
    tx_id: &str,
) -> String {
    format!(
        "{}/{}/{:020}-{}.json",
        gateway_write_ahead_log_remote_prefix(config),
        sanitize_gateway_write_ahead_log_path_component(application_id),
        lsn,
        sanitize_gateway_write_ahead_log_path_component(tx_id),
    )
}

fn gateway_backup_password_present(config: &AppConfig) -> bool {
    load_gateway_backup_password(config)
        .map(|value| value.is_some())
        .unwrap_or(false)
}

fn gateway_backup_next_run_at_unix_ms(
    policy: &GatewayBackupPolicy,
    history: &GatewayBackupHistory,
    now_unix_ms: u64,
) -> Option<u64> {
    if !policy.enabled || (!policy.local_enabled && !policy.remote_enabled) {
        return None;
    }
    let interval_ms = policy.interval_minutes.saturating_mul(60_000);
    match history
        .last_completed_at_unix_ms
        .or(history.last_started_at_unix_ms)
    {
        Some(last_run_at) => Some(last_run_at.saturating_add(interval_ms)),
        None => Some(now_unix_ms),
    }
}

fn refresh_gateway_backup_runtime_schedule(state: &AppState) {
    let control_plane = control_plane_snapshot(state);
    let next_run_at_unix_ms = gateway_backup_next_run_at_unix_ms(
        &control_plane.gateway_backup_policy,
        &control_plane.gateway_backup_history,
        current_unix_ms(),
    );
    let mut runtime = state
        .gateway_backup_runtime
        .lock()
        .expect("gateway backup runtime poisoned");
    runtime.next_run_at_unix_ms = next_run_at_unix_ms;
}

fn gateway_backup_status_payload(state: &AppState) -> GatewayBackupStatusPayload {
    let control_plane = control_plane_snapshot(state);
    let runtime = state
        .gateway_backup_runtime
        .lock()
        .expect("gateway backup runtime poisoned")
        .clone();
    GatewayBackupStatusPayload {
        policy: GatewayBackupPolicyPayload {
            enabled: control_plane.gateway_backup_policy.enabled,
            local_enabled: control_plane.gateway_backup_policy.local_enabled,
            remote_enabled: control_plane.gateway_backup_policy.remote_enabled,
            interval_minutes: control_plane.gateway_backup_policy.interval_minutes,
            local_directory: control_plane.gateway_backup_policy.local_directory.clone(),
            local_retention_count: control_plane.gateway_backup_policy.local_retention_count,
            remote_provider: control_plane
                .gateway_backup_policy
                .remote_provider
                .map(|provider| provider.as_str().to_string()),
            remote_retention_count: control_plane.gateway_backup_policy.remote_retention_count,
            password_present: gateway_backup_password_present(&state.config),
            remote_bucket: GATEWAY_BACKUP_REMOTE_BUCKET.to_string(),
            remote_prefix: gateway_backup_remote_prefix(&state.config),
        },
        history: GatewayBackupHistoryPayload {
            last_trigger: control_plane.gateway_backup_history.last_trigger.clone(),
            last_started_at_unix_ms: control_plane.gateway_backup_history.last_started_at_unix_ms,
            last_completed_at_unix_ms: control_plane
                .gateway_backup_history
                .last_completed_at_unix_ms,
            last_success_at_unix_ms: control_plane.gateway_backup_history.last_success_at_unix_ms,
            last_result: control_plane.gateway_backup_history.last_result.clone(),
            last_archive_size_bytes: control_plane.gateway_backup_history.last_archive_size_bytes,
            last_local_filename: control_plane
                .gateway_backup_history
                .last_local_filename
                .clone(),
            last_local_path: control_plane.gateway_backup_history.last_local_path.clone(),
            last_remote_provider: control_plane
                .gateway_backup_history
                .last_remote_provider
                .map(|provider| provider.as_str().to_string()),
            last_remote_bucket: control_plane
                .gateway_backup_history
                .last_remote_bucket
                .clone(),
            last_remote_key: control_plane.gateway_backup_history.last_remote_key.clone(),
            last_error: control_plane.gateway_backup_history.last_error.clone(),
        },
        runtime: GatewayBackupRuntimePayload {
            running: runtime.running,
            next_run_at_unix_ms: runtime.next_run_at_unix_ms,
        },
    }
}

fn gateway_write_ahead_log_policy_payload(
    config: &AppConfig,
    policy: &GatewayWriteAheadLogPolicy,
) -> GatewayWriteAheadLogPolicyPayload {
    GatewayWriteAheadLogPolicyPayload {
        enabled: policy.enabled,
        remote_provider: policy
            .remote_provider
            .map(|provider| provider.as_str().to_string()),
        application_ids: policy.application_ids.clone(),
        remote_bucket: GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string(),
        remote_prefix: gateway_write_ahead_log_remote_prefix(config),
    }
}

fn gateway_write_ahead_log_state_payload(
    state: GatewayWriteAheadLogStateRecord,
) -> GatewayWriteAheadLogStatePayload {
    GatewayWriteAheadLogStatePayload {
        next_lsn: state.next_lsn,
        checkpoint_lsn: state.last_checkpoint_lsn,
        replayed_lsn: state.last_replayed_lsn,
        replay_floor_lsn: state.last_replayed_lsn.or(state.last_checkpoint_lsn),
        updated_at_unix_ms: state.updated_at_unix_ms,
    }
}

fn cache_gateway_write_ahead_log_status(
    state: &AppState,
    status: GatewayWriteAheadLogStatusPayload,
) {
    let mut runtime = state
        .gateway_write_ahead_log_runtime
        .lock()
        .expect("gateway write-ahead log runtime poisoned");
    runtime.loaded = true;
    runtime.last_refreshed_at_unix_ms = status.last_refreshed_at_unix_ms;
    runtime.status = status;
}

fn gateway_write_ahead_log_status_payload(
    state: &AppState,
) -> Result<GatewayWriteAheadLogStatusPayload, BlobError> {
    let control_plane = control_plane_snapshot(state);
    let state_record = state
        .metadata_store
        .gateway_write_ahead_log_state()
        .map_err(|error| BlobError::Upstream(error.to_string()))?;
    let runtime = state
        .gateway_write_ahead_log_runtime
        .lock()
        .expect("gateway write-ahead log runtime poisoned")
        .clone();
    let mut payload = runtime.status;
    payload.policy = gateway_write_ahead_log_policy_payload(
        state.config.as_ref(),
        &control_plane.gateway_write_ahead_log_policy,
    );
    payload.state = gateway_write_ahead_log_state_payload(state_record);
    payload.cleanup_supported = payload.remote.delete_supported;
    payload.cleanup_required =
        payload.remote.cleanup_ready_records > 0 || payload.remote.cleanup_blocked_records > 0;
    payload.last_refreshed_at_unix_ms = runtime.last_refreshed_at_unix_ms;
    Ok(payload)
}

fn current_gateway_backup_bundle(
    state: &AppState,
) -> Result<GatewayBackupBundlePayload, BlobError> {
    let instance_id = resolve_gateway_instance_id(
        &state.config.instance_id_file,
        &state.config.control_plane_file,
    )
    .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let mut provider_credentials = BTreeMap::new();
    let mut provider_credential_leases = BTreeMap::new();
    for provider in all_gateway_backup_providers() {
        let name = provider.as_str().to_string();
        provider_credentials.insert(
            name.clone(),
            load_provider_credential_record(&state.config, provider)?,
        );
        let lease = load_provider_credential_lease_record(&state.config, provider)?;
        if lease != ProviderCredentialLeaseRecord::default() {
            provider_credential_leases.insert(name, lease);
        }
    }

    Ok(GatewayBackupBundlePayload {
        backup_format_version: GATEWAY_BACKUP_FORMAT_VERSION,
        exported_at_unix_ms: current_unix_ms(),
        gateway_version: env!("CARGO_PKG_VERSION").to_string(),
        provenance: release_provenance_payload(),
        instance_id,
        control_plane: control_plane_snapshot(state),
        provider_credentials,
        provider_credential_leases,
        managed_encryption_keys: load_all_managed_encryption_key_records(&state.config)?,
        metadata: GatewayBackupMetadataPayload {
            object_placements: state
                .metadata_store
                .all_object_placements()
                .map_err(|error| BlobError::Upstream(error.to_string()))?,
            logical_objects: state
                .metadata_store
                .all_logical_objects()
                .map_err(|error| BlobError::Upstream(error.to_string()))?,
            object_protection_plans: state
                .metadata_store
                .all_object_protection_plans()
                .map_err(|error| BlobError::Upstream(error.to_string()))?,
            pending_replication_jobs: state
                .metadata_store
                .load_pending_jobs(None)
                .map_err(|error| BlobError::Upstream(error.to_string()))?,
            gateway_write_ahead_log_state: state
                .metadata_store
                .gateway_write_ahead_log_state()
                .map_err(|error| BlobError::Upstream(error.to_string()))?,
        },
    })
}

fn build_gateway_backup_archive_header(
    bundle: &GatewayBackupBundlePayload,
    filename: &str,
) -> EncryptedBackupArchiveHeader {
    let mut salt = [0u8; GATEWAY_BACKUP_SALT_LEN];
    OsRng.fill_bytes(&mut salt);
    let mut nonce_prefix = [0u8; GATEWAY_BACKUP_NONCE_PREFIX_LEN];
    OsRng.fill_bytes(&mut nonce_prefix);
    EncryptedBackupArchiveHeader {
        backup_format_version: GATEWAY_BACKUP_FORMAT_VERSION,
        exported_at_unix_ms: bundle.exported_at_unix_ms,
        gateway_version: bundle.gateway_version.clone(),
        provenance: bundle.provenance.clone(),
        instance_id: bundle.instance_id.clone(),
        filename: filename.to_string(),
        compression: "gzip".to_string(),
        encryption: "chacha20_poly1305".to_string(),
        argon2_memory_kib: GATEWAY_BACKUP_KDF_MEMORY_KIB,
        argon2_iterations: GATEWAY_BACKUP_KDF_ITERATIONS,
        argon2_parallelism: GATEWAY_BACKUP_KDF_PARALLELISM,
        chunk_plaintext_bytes: GATEWAY_BACKUP_CHUNK_PLAINTEXT_BYTES,
        salt_base64: BASE64_STANDARD.encode(salt),
        nonce_prefix_base64: BASE64_STANDARD.encode(nonce_prefix),
    }
}

fn backup_temp_dir() -> Result<tempfile::TempDir, BlobError> {
    tempfile::Builder::new()
        .prefix("ccbg-backup-")
        .tempdir()
        .map_err(|error| {
            BlobError::Configuration(format!("failed to create backup temp dir: {error}"))
        })
}

fn write_backup_bundle_gzip(
    bundle: &GatewayBackupBundlePayload,
    path: &FsPath,
) -> Result<(), BlobError> {
    let file = fs::File::create(path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to create compressed backup payload {}: {error}",
            path.display()
        ))
    })?;
    let writer = BufWriter::new(file);
    let mut encoder = GzEncoder::new(writer, Compression::default());
    serde_json::to_writer(&mut encoder, bundle).map_err(|error| {
        BlobError::Configuration(format!("failed to encode backup bundle JSON: {error}"))
    })?;
    encoder.finish().map_err(|error| {
        BlobError::Configuration(format!(
            "failed to finalize compressed backup payload {}: {error}",
            path.display()
        ))
    })?;
    Ok(())
}

fn decode_backup_archive_salt(header: &EncryptedBackupArchiveHeader) -> Result<Vec<u8>, BlobError> {
    let salt = BASE64_STANDARD
        .decode(header.salt_base64.as_bytes())
        .map_err(|error| {
            BlobError::Configuration(format!("invalid backup archive salt encoding: {error}"))
        })?;
    if salt.len() != GATEWAY_BACKUP_SALT_LEN {
        return Err(BlobError::Configuration(format!(
            "invalid backup archive salt length: expected {}, got {}",
            GATEWAY_BACKUP_SALT_LEN,
            salt.len()
        )));
    }
    Ok(salt)
}

fn decode_backup_archive_nonce_prefix(
    header: &EncryptedBackupArchiveHeader,
) -> Result<Vec<u8>, BlobError> {
    let prefix = BASE64_STANDARD
        .decode(header.nonce_prefix_base64.as_bytes())
        .map_err(|error| {
            BlobError::Configuration(format!(
                "invalid backup archive nonce prefix encoding: {error}"
            ))
        })?;
    if prefix.len() != GATEWAY_BACKUP_NONCE_PREFIX_LEN {
        return Err(BlobError::Configuration(format!(
            "invalid backup archive nonce prefix length: expected {}, got {}",
            GATEWAY_BACKUP_NONCE_PREFIX_LEN,
            prefix.len()
        )));
    }
    Ok(prefix)
}

fn derive_backup_archive_key(
    password: &str,
    header: &EncryptedBackupArchiveHeader,
) -> Result<[u8; 32], BlobError> {
    let salt = decode_backup_archive_salt(header)?;
    let params = argon2::Params::new(
        header.argon2_memory_kib,
        header.argon2_iterations,
        header.argon2_parallelism,
        Some(32),
    )
    .map_err(|error| BlobError::Configuration(format!("invalid backup KDF params: {error}")))?;
    let argon = Argon2::new(argon2::Algorithm::Argon2id, argon2::Version::V0x13, params);
    let mut key = [0u8; 32];
    argon
        .hash_password_into(password.as_bytes(), &salt, &mut key)
        .map_err(|error| {
            BlobError::Configuration(format!("failed to derive backup archive key: {error}"))
        })?;
    Ok(key)
}

fn backup_archive_nonce(prefix: &[u8], chunk_index: u64) -> [u8; GATEWAY_BACKUP_NONCE_LEN] {
    let mut nonce = [0u8; GATEWAY_BACKUP_NONCE_LEN];
    nonce[..GATEWAY_BACKUP_NONCE_PREFIX_LEN].copy_from_slice(prefix);
    nonce[GATEWAY_BACKUP_NONCE_PREFIX_LEN..].copy_from_slice(&chunk_index.to_be_bytes());
    nonce
}

fn write_encrypted_backup_archive(
    gzip_payload_path: &FsPath,
    archive_path: &FsPath,
    header: &EncryptedBackupArchiveHeader,
    password: &str,
) -> Result<(), BlobError> {
    let key = derive_backup_archive_key(password, header)?;
    let cipher =
        <ChaCha20Poly1305 as chacha20poly1305::KeyInit>::new_from_slice(&key).map_err(|error| {
            BlobError::Configuration(format!("failed to initialize backup cipher: {error}"))
        })?;
    let header_bytes = serde_json::to_vec(header).map_err(|error| {
        BlobError::Configuration(format!("failed to encode backup archive header: {error}"))
    })?;
    let header_len = u32::try_from(header_bytes.len())
        .map_err(|_| BlobError::Configuration("backup archive header is too large".to_string()))?;
    let nonce_prefix = decode_backup_archive_nonce_prefix(header)?;

    let reader = fs::File::open(gzip_payload_path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to open compressed backup payload {}: {error}",
            gzip_payload_path.display()
        ))
    })?;
    let writer = fs::File::create(archive_path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to create backup archive {}: {error}",
            archive_path.display()
        ))
    })?;
    let mut reader = BufReader::new(reader);
    let mut writer = BufWriter::new(writer);
    writer
        .write_all(GATEWAY_BACKUP_ARCHIVE_MAGIC)
        .and_then(|_| writer.write_all(&header_len.to_be_bytes()))
        .and_then(|_| writer.write_all(&header_bytes))
        .map_err(|error| {
            BlobError::Configuration(format!(
                "failed to write backup archive header {}: {error}",
                archive_path.display()
            ))
        })?;

    let mut plaintext = vec![0u8; header.chunk_plaintext_bytes.max(1)];
    let mut chunk_index = 0u64;
    loop {
        let read = reader.read(&mut plaintext).map_err(|error| {
            BlobError::Configuration(format!(
                "failed to read compressed backup payload {}: {error}",
                gzip_payload_path.display()
            ))
        })?;
        if read == 0 {
            break;
        }
        let mut chunk = plaintext[..read].to_vec();
        let nonce = backup_archive_nonce(&nonce_prefix, chunk_index);
        cipher
            .encrypt_in_place(GenericArray::from_slice(&nonce), &header_bytes, &mut chunk)
            .map_err(|_| {
                BlobError::Configuration("failed to encrypt backup archive chunk".to_string())
            })?;
        let encrypted_len = u32::try_from(chunk.len()).map_err(|_| {
            BlobError::Configuration("backup archive chunk exceeds u32 length".to_string())
        })?;
        writer
            .write_all(&encrypted_len.to_be_bytes())
            .and_then(|_| writer.write_all(&chunk))
            .map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to write backup archive chunk {}: {error}",
                    archive_path.display()
                ))
            })?;
        chunk_index = chunk_index.saturating_add(1);
    }
    writer.flush().map_err(|error| {
        BlobError::Configuration(format!(
            "failed to flush backup archive {}: {error}",
            archive_path.display()
        ))
    })?;
    Ok(())
}

fn read_backup_archive_header(
    archive_path: &FsPath,
) -> Result<(EncryptedBackupArchiveHeader, Vec<u8>, BufReader<fs::File>), BlobError> {
    let file = fs::File::open(archive_path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to open backup archive {}: {error}",
            archive_path.display()
        ))
    })?;
    let mut reader = BufReader::new(file);
    let mut magic = [0u8; 8];
    reader.read_exact(&mut magic).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to read backup archive header {}: {error}",
            archive_path.display()
        ))
    })?;
    if &magic != GATEWAY_BACKUP_ARCHIVE_MAGIC {
        return Err(BlobError::Configuration("不是 CCBG 备份归档".to_string()));
    }
    let mut header_len = [0u8; 4];
    reader.read_exact(&mut header_len).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to read backup archive header length {}: {error}",
            archive_path.display()
        ))
    })?;
    let header_len = u32::from_be_bytes(header_len) as usize;
    let mut header_bytes = vec![0u8; header_len];
    reader.read_exact(&mut header_bytes).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to read backup archive header body {}: {error}",
            archive_path.display()
        ))
    })?;
    let header =
        serde_json::from_slice::<EncryptedBackupArchiveHeader>(&header_bytes).map_err(|error| {
            BlobError::Configuration(format!("invalid backup archive header JSON: {error}"))
        })?;
    if header.backup_format_version != GATEWAY_BACKUP_FORMAT_VERSION {
        return Err(BlobError::Configuration(format!(
            "unsupported backup archive version {}",
            header.backup_format_version
        )));
    }
    if header.compression != "gzip" {
        return Err(BlobError::Configuration(format!(
            "unsupported backup archive compression {}",
            header.compression
        )));
    }
    if header.encryption != "chacha20_poly1305" {
        return Err(BlobError::Configuration(format!(
            "unsupported backup archive encryption {}",
            header.encryption
        )));
    }
    Ok((header, header_bytes, reader))
}

fn decrypt_backup_archive_to_gzip(
    archive_path: &FsPath,
    gzip_output_path: &FsPath,
    password: &str,
) -> Result<EncryptedBackupArchiveHeader, BlobError> {
    let (header, header_bytes, mut reader) = read_backup_archive_header(archive_path)?;
    let key = derive_backup_archive_key(password, &header)?;
    let cipher =
        <ChaCha20Poly1305 as chacha20poly1305::KeyInit>::new_from_slice(&key).map_err(|error| {
            BlobError::Configuration(format!("failed to initialize backup cipher: {error}"))
        })?;
    let nonce_prefix = decode_backup_archive_nonce_prefix(&header)?;
    let writer = fs::File::create(gzip_output_path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to create decrypted gzip payload {}: {error}",
            gzip_output_path.display()
        ))
    })?;
    let mut writer = BufWriter::new(writer);
    let mut chunk_index = 0u64;
    loop {
        let mut chunk_len_bytes = [0u8; 4];
        match reader.read_exact(&mut chunk_len_bytes) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::UnexpectedEof => break,
            Err(error) => {
                return Err(BlobError::Configuration(format!(
                    "failed to read encrypted backup chunk length {}: {error}",
                    archive_path.display()
                )));
            }
        }
        let chunk_len = u32::from_be_bytes(chunk_len_bytes) as usize;
        if chunk_len < GATEWAY_BACKUP_AEAD_TAG_LEN {
            return Err(BlobError::Configuration(
                "invalid encrypted backup chunk length".to_string(),
            ));
        }
        let mut chunk = vec![0u8; chunk_len];
        reader.read_exact(&mut chunk).map_err(|error| {
            BlobError::Configuration(format!(
                "failed to read encrypted backup chunk {}: {error}",
                archive_path.display()
            ))
        })?;
        let nonce = backup_archive_nonce(&nonce_prefix, chunk_index);
        cipher
            .decrypt_in_place(GenericArray::from_slice(&nonce), &header_bytes, &mut chunk)
            .map_err(|_| BlobError::Configuration("备份密码错误，或备份文件已损坏".to_string()))?;
        writer.write_all(&chunk).map_err(|error| {
            BlobError::Configuration(format!(
                "failed to write decrypted gzip payload {}: {error}",
                gzip_output_path.display()
            ))
        })?;
        chunk_index = chunk_index.saturating_add(1);
    }
    writer.flush().map_err(|error| {
        BlobError::Configuration(format!(
            "failed to flush decrypted gzip payload {}: {error}",
            gzip_output_path.display()
        ))
    })?;
    Ok(header)
}

fn read_gateway_backup_bundle_from_archive(
    archive_path: &FsPath,
    password: &str,
) -> Result<(GatewayBackupBundlePayload, EncryptedBackupArchiveHeader), BlobError> {
    let temp_dir = backup_temp_dir()?;
    let gzip_payload_path = temp_dir.path().join("bundle.json.gz");
    let header = decrypt_backup_archive_to_gzip(archive_path, &gzip_payload_path, password)?;
    let gzip_file = fs::File::open(&gzip_payload_path).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to open decrypted gzip payload {}: {error}",
            gzip_payload_path.display()
        ))
    })?;
    let decoder = GzDecoder::new(BufReader::new(gzip_file));
    let bundle =
        serde_json::from_reader::<_, GatewayBackupBundlePayload>(decoder).map_err(|error| {
            BlobError::Configuration(format!("failed to decode backup bundle JSON: {error}"))
        })?;
    Ok((bundle, header))
}

fn gateway_backup_checkpoint_lsn(bundle: &GatewayBackupBundlePayload) -> u64 {
    bundle
        .metadata
        .gateway_write_ahead_log_state
        .next_lsn
        .saturating_sub(1)
}

struct GatewayBackupArchiveBuildResult {
    header: EncryptedBackupArchiveHeader,
    checkpoint_lsn: u64,
}

fn build_gateway_backup_archive_file(
    state: &AppState,
    archive_path: &FsPath,
    password: &str,
) -> Result<GatewayBackupArchiveBuildResult, BlobError> {
    let bundle = current_gateway_backup_bundle(state)?;
    let checkpoint_lsn = gateway_backup_checkpoint_lsn(&bundle);
    if let Some(parent) = archive_path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to create backup archive dir {}: {error}",
                    parent.display()
                ))
            })?;
        }
    }
    let filename = archive_path
        .file_name()
        .and_then(|value| value.to_str())
        .map(ToString::to_string)
        .unwrap_or_else(|| {
            gateway_backup_filename(&bundle.instance_id, bundle.exported_at_unix_ms)
        });
    let header = build_gateway_backup_archive_header(&bundle, &filename);
    let temp_dir = backup_temp_dir()?;
    let gzip_payload_path = temp_dir.path().join("bundle.json.gz");
    write_backup_bundle_gzip(&bundle, &gzip_payload_path)?;
    write_encrypted_backup_archive(&gzip_payload_path, archive_path, &header, password)?;
    Ok(GatewayBackupArchiveBuildResult {
        header,
        checkpoint_lsn,
    })
}

fn gateway_backup_archive_summary(
    bundle: &GatewayBackupBundlePayload,
    filename: &str,
) -> GatewayBackupArchiveSummaryPayload {
    GatewayBackupArchiveSummaryPayload {
        filename: filename.to_string(),
        exported_at_unix_ms: bundle.exported_at_unix_ms,
        instance_id: bundle.instance_id.clone(),
        provenance: bundle.provenance.clone(),
        provider_credential_count: bundle.provider_credentials.len(),
        managed_encryption_key_count: bundle.managed_encryption_keys.len(),
        object_placement_count: bundle.metadata.object_placements.len(),
        pending_replication_job_count: bundle.metadata.pending_replication_jobs.len(),
    }
}

fn validate_gateway_backup_metadata_payload(
    metadata: &GatewayBackupMetadataPayload,
) -> Result<(), BlobError> {
    let placement_keys = metadata
        .object_placements
        .iter()
        .map(|record| (record.bucket.clone(), record.key.clone()))
        .collect::<HashSet<_>>();

    let logical_keys = metadata
        .logical_objects
        .iter()
        .map(|record| (record.bucket.clone(), record.key.clone()))
        .collect::<HashSet<_>>();
    if logical_keys.len() != metadata.logical_objects.len() {
        return Err(BlobError::Configuration(
            "backup bundle contains duplicate logical object records".to_string(),
        ));
    }
    for record in &metadata.logical_objects {
        if !placement_keys.contains(&(record.bucket.clone(), record.key.clone())) {
            return Err(BlobError::Configuration(format!(
                "logical object {}/{} has no matching object placement record",
                record.bucket, record.key
            )));
        }
    }

    let protection_keys = metadata
        .object_protection_plans
        .iter()
        .map(|record| (record.bucket.clone(), record.key.clone()))
        .collect::<HashSet<_>>();
    if protection_keys.len() != metadata.object_protection_plans.len() {
        return Err(BlobError::Configuration(
            "backup bundle contains duplicate object protection plan records".to_string(),
        ));
    }
    for record in &metadata.object_protection_plans {
        if !placement_keys.contains(&(record.bucket.clone(), record.key.clone())) {
            return Err(BlobError::Configuration(format!(
                "object protection plan {}/{} has no matching object placement record",
                record.bucket, record.key
            )));
        }
    }

    if placement_keys.len() != metadata.object_placements.len() {
        return Err(BlobError::Configuration(
            "backup bundle contains duplicate object placement records".to_string(),
        ));
    }

    let mut pending_job_ids = HashSet::new();
    for job in &metadata.pending_replication_jobs {
        if job.job_id == 0 {
            return Err(BlobError::Configuration(
                "replication jobs must have a non-zero job_id".to_string(),
            ));
        }
        if !pending_job_ids.insert(job.job_id) {
            return Err(BlobError::Configuration(format!(
                "backup bundle contains duplicate replication job id {}",
                job.job_id
            )));
        }
        if job.target.trim().is_empty() {
            return Err(BlobError::Configuration(format!(
                "replication job {} has an empty target",
                job.job_id
            )));
        }
        if job.object.bucket.trim().is_empty() || job.object.key.trim().is_empty() {
            return Err(BlobError::Configuration(format!(
                "replication job {} references an empty bucket or key",
                job.job_id
            )));
        }
        if !matches!(
            job.status,
            ReplicationStatus::Pending | ReplicationStatus::RetryScheduled
        ) {
            return Err(BlobError::Configuration(format!(
                "replication job {} has unsupported status {} in pending_replication_jobs",
                job.job_id,
                job.status.as_str()
            )));
        }
        if matches!(job.operation, ReplicationOperation::Put) && job.object.size.is_none() {
            return Err(BlobError::Configuration(format!(
                "replication job {} is a put without object size",
                job.job_id
            )));
        }
    }

    let wal = &metadata.gateway_write_ahead_log_state;
    if wal.next_lsn == 0 {
        return Err(BlobError::Configuration(
            "gateway write-ahead log next_lsn must be greater than zero".to_string(),
        ));
    }
    if wal
        .last_checkpoint_lsn
        .is_some_and(|value| value >= wal.next_lsn)
    {
        return Err(BlobError::Configuration(
            "gateway write-ahead log last_checkpoint_lsn must be less than next_lsn".to_string(),
        ));
    }
    if wal
        .last_replayed_lsn
        .is_some_and(|value| value >= wal.next_lsn)
    {
        return Err(BlobError::Configuration(
            "gateway write-ahead log last_replayed_lsn must be less than next_lsn".to_string(),
        ));
    }

    Ok(())
}

fn validate_gateway_backup_bundle_for_import(
    state: &AppState,
    bundle: GatewayBackupBundlePayload,
) -> Result<GatewayBackupBundlePayload, BlobError> {
    if bundle.backup_format_version != GATEWAY_BACKUP_FORMAT_VERSION {
        return Err(BlobError::Configuration(format!(
            "unsupported backup bundle version {}",
            bundle.backup_format_version
        )));
    }

    let mut provider_credentials = BTreeMap::new();
    for provider in all_gateway_backup_providers() {
        let key = provider.as_str().to_string();
        let record = bundle
            .provider_credentials
            .get(&key)
            .cloned()
            .unwrap_or_default()
            .normalize();
        validate_provider_credential_record(&record)?;
        provider_credentials.insert(key, record);
    }

    let managed_encryption_keys = bundle
        .managed_encryption_keys
        .into_iter()
        .map(normalize_managed_encryption_key_record)
        .collect::<Result<Vec<_>, _>>()?;
    validate_gateway_backup_metadata_payload(&bundle.metadata)?;

    let temp_dir = backup_temp_dir()?;
    let temp_credentials_dir = temp_dir.path().join("provider-credentials");
    fs::create_dir_all(&temp_credentials_dir).map_err(|error| {
        BlobError::Configuration(format!(
            "failed to create temp credential dir {}: {error}",
            temp_credentials_dir.display()
        ))
    })?;
    for record in &managed_encryption_keys {
        persist_managed_encryption_key_record_to_credentials_dir(
            &temp_credentials_dir.to_string_lossy(),
            record,
        )?;
    }
    let temp_control_plane_path = temp_dir.path().join("control-plane.json");
    persist_control_plane_state(
        &temp_control_plane_path.to_string_lossy(),
        &bundle.control_plane,
    )
    .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let normalized_control_plane = load_control_plane_state(
        &temp_control_plane_path.to_string_lossy(),
        &temp_credentials_dir.to_string_lossy(),
        default_control_plane_state(&state.config),
        state.config.onedrive.enabled,
    )
    .map_err(|error| BlobError::Configuration(error.to_string()))?;

    Ok(GatewayBackupBundlePayload {
        backup_format_version: bundle.backup_format_version,
        exported_at_unix_ms: bundle.exported_at_unix_ms,
        gateway_version: bundle.gateway_version,
        provenance: bundle.provenance,
        instance_id: bundle.instance_id,
        control_plane: normalized_control_plane,
        provider_credentials,
        provider_credential_leases: bundle.provider_credential_leases,
        managed_encryption_keys,
        metadata: bundle.metadata,
    })
}

fn apply_gateway_backup_bundle(
    state: &AppState,
    bundle: GatewayBackupBundlePayload,
) -> Result<(), BlobError> {
    for provider in all_gateway_backup_providers() {
        let key = provider.as_str().to_string();
        let credentials = bundle
            .provider_credentials
            .get(&key)
            .cloned()
            .unwrap_or_default();
        persist_provider_credential_record(&state.config, provider, &credentials)?;
        match bundle.provider_credential_leases.get(&key) {
            Some(lease) if *lease != ProviderCredentialLeaseRecord::default() => {
                persist_provider_credential_lease_record(&state.config, provider, lease)?;
            }
            _ => {
                remove_provider_credential_lease_record(&state.config, provider)?;
            }
        }
    }

    let imported_key_ids = bundle
        .managed_encryption_keys
        .iter()
        .map(|record| record.id.clone())
        .collect::<HashSet<_>>();
    for existing in load_all_managed_encryption_key_records(&state.config)? {
        if !imported_key_ids.contains(existing.id.as_str()) {
            let _ = remove_managed_encryption_key_record(&state.config, &existing.id);
        }
    }
    for record in &bundle.managed_encryption_keys {
        persist_managed_encryption_key_record(&state.config, record)?;
    }

    state
        .metadata_store
        .replace_backup_state(
            &bundle.metadata.object_placements,
            &bundle.metadata.logical_objects,
            &bundle.metadata.object_protection_plans,
            &bundle.metadata.pending_replication_jobs,
            &bundle.metadata.gateway_write_ahead_log_state,
        )
        .map_err(|error| BlobError::Upstream(error.to_string()))?;

    persist_control_plane_state(&state.config.control_plane_file, &bundle.control_plane)
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    {
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        *control_plane = bundle.control_plane.clone();
    }

    state
        .replication
        .replace_pending(bundle.metadata.pending_replication_jobs.clone());
    for provider in all_gateway_backup_providers() {
        let _ = rebuild_backend_for_provider(state, provider);
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct GatewayBackupRunReport {
    result: String,
    archive_size_bytes: u64,
    local_filename: Option<String>,
    local_path: Option<String>,
    remote_provider: Option<ProviderId>,
    remote_bucket: Option<String>,
    remote_key: Option<String>,
    error: Option<String>,
}

fn save_gateway_backup_policy(
    state: &AppState,
    input: GatewayBackupPolicyInput,
) -> Result<(), BlobError> {
    if input.clear_password {
        remove_gateway_backup_password(&state.config)?;
    }
    if let Some(password) = input
        .password
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        persist_gateway_backup_password(&state.config, password)?;
    }

    let default_policy = default_control_plane_state(&state.config).gateway_backup_policy;
    let remote_provider = input
        .remote_provider
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ProviderId::parse)
        .transpose()
        .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let policy = normalize_gateway_backup_policy(
        GatewayBackupPolicy {
            enabled: input.enabled,
            local_enabled: input.local_enabled,
            remote_enabled: input.remote_enabled,
            interval_minutes: input.interval_minutes,
            local_directory: input.local_directory.unwrap_or_default(),
            local_retention_count: input
                .local_retention_count
                .unwrap_or_else(default_gateway_backup_local_retention_count),
            remote_provider,
            remote_retention_count: input
                .remote_retention_count
                .unwrap_or_else(default_gateway_backup_remote_retention_count),
        },
        &default_policy,
        state.config.onedrive.enabled,
    )?;

    if policy.remote_enabled {
        let provider = policy.remote_provider.ok_or_else(|| {
            BlobError::Configuration("启用云端自动备份前，必须先选择一个目标云盘".to_string())
        })?;
        let backend = backend_for_provider(state, provider)?;
        if !backend.capabilities().write {
            return Err(BlobError::Configuration(format!(
                "{} 当前不支持写入，不能作为自动备份目标",
                provider_label(provider)
            )));
        }
    }

    if policy.enabled && !gateway_backup_password_present(&state.config) {
        return Err(BlobError::Configuration(
            "启用自动备份前，必须先保存一个备份密码".to_string(),
        ));
    }

    {
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        control_plane.gateway_backup_policy = policy;
        persist_control_plane_state(&state.config.control_plane_file, &control_plane)
            .map_err(|error| BlobError::Configuration(error.to_string()))?;
    }
    refresh_gateway_backup_runtime_schedule(state);
    Ok(())
}

async fn gateway_backup_loop(state: AppState) {
    loop {
        if let Err(error) = process_gateway_backup_tick(&state).await {
            warn!(error = %error, "gateway backup tick failed");
        }
        sleep(Duration::from_secs(GATEWAY_BACKUP_SCHEDULER_TICK_SECS)).await;
    }
}

async fn process_gateway_backup_tick(state: &AppState) -> Result<(), BlobError> {
    let should_run = {
        let control_plane = control_plane_snapshot(state);
        let mut runtime = state
            .gateway_backup_runtime
            .lock()
            .expect("gateway backup runtime poisoned");
        runtime.next_run_at_unix_ms = gateway_backup_next_run_at_unix_ms(
            &control_plane.gateway_backup_policy,
            &control_plane.gateway_backup_history,
            current_unix_ms(),
        );
        control_plane.gateway_backup_policy.enabled
            && !runtime.running
            && runtime
                .next_run_at_unix_ms
                .is_some_and(|deadline| current_unix_ms() >= deadline)
    };
    if should_run {
        execute_gateway_backup_run(state.clone(), "scheduled").await?;
    }
    Ok(())
}

async fn execute_gateway_backup_run(
    state: AppState,
    trigger: impl Into<String>,
) -> Result<(), BlobError> {
    let trigger = trigger.into();
    {
        let mut runtime = state
            .gateway_backup_runtime
            .lock()
            .expect("gateway backup runtime poisoned");
        if runtime.running {
            return Err(BlobError::Configuration(
                "网关备份已经在执行中，请稍后再试".to_string(),
            ));
        }
        runtime.running = true;
        runtime.next_run_at_unix_ms = None;
    }
    {
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        control_plane.gateway_backup_history.last_trigger = Some(trigger.clone());
        control_plane.gateway_backup_history.last_started_at_unix_ms = Some(current_unix_ms());
        control_plane
            .gateway_backup_history
            .last_completed_at_unix_ms = None;
        control_plane.gateway_backup_history.last_result = None;
        control_plane.gateway_backup_history.last_error = None;
        persist_control_plane_state(&state.config.control_plane_file, &control_plane)
            .map_err(|error| BlobError::Configuration(error.to_string()))?;
    }

    let result = execute_gateway_backup_run_inner(&state).await;
    {
        let completed_at_unix_ms = current_unix_ms();
        let mut control_plane = state.control_plane.lock().expect("control plane poisoned");
        let history = &mut control_plane.gateway_backup_history;
        history.last_completed_at_unix_ms = Some(completed_at_unix_ms);
        match &result {
            Ok(report) => {
                history.last_result = Some(report.result.clone());
                history.last_archive_size_bytes = Some(report.archive_size_bytes);
                history.last_local_filename = report.local_filename.clone();
                history.last_local_path = report.local_path.clone();
                history.last_remote_provider = report.remote_provider;
                history.last_remote_bucket = report.remote_bucket.clone();
                history.last_remote_key = report.remote_key.clone();
                history.last_error = report.error.clone();
                if report.result == "success" || report.result == "partial" {
                    history.last_success_at_unix_ms = Some(completed_at_unix_ms);
                }
            }
            Err(error) => {
                history.last_result = Some("failed".to_string());
                history.last_error = Some(error.to_string());
            }
        }
        persist_control_plane_state(&state.config.control_plane_file, &control_plane)
            .map_err(|error| BlobError::Configuration(error.to_string()))?;
    }
    {
        let mut runtime = state
            .gateway_backup_runtime
            .lock()
            .expect("gateway backup runtime poisoned");
        runtime.running = false;
    }
    refresh_gateway_backup_runtime_schedule(&state);
    result.map(|_| ())
}

async fn execute_gateway_backup_run_inner(
    state: &AppState,
) -> Result<GatewayBackupRunReport, BlobError> {
    let control_plane = control_plane_snapshot(state);
    let policy = control_plane.gateway_backup_policy;
    if !policy.local_enabled && !policy.remote_enabled {
        return Err(BlobError::Configuration(
            "当前没有启用任何自动备份落点".to_string(),
        ));
    }
    let password = load_gateway_backup_password(&state.config)?.ok_or_else(|| {
        BlobError::Configuration("还没有保存自动备份密码，无法执行自动备份".to_string())
    })?;
    let instance_id = resolve_gateway_instance_id(
        &state.config.instance_id_file,
        &state.config.control_plane_file,
    )
    .map_err(|error| BlobError::Configuration(error.to_string()))?;
    let filename = gateway_backup_filename(&instance_id, current_unix_ms());
    let temp_dir = backup_temp_dir()?;
    let temp_archive_path = temp_dir.path().join(&filename);
    let state_for_backup = state.clone();
    let password_for_backup = password.clone();
    let archive_path_for_backup = temp_archive_path.clone();
    let backup_build = tokio::task::spawn_blocking(move || {
        build_gateway_backup_archive_file(
            &state_for_backup,
            &archive_path_for_backup,
            &password_for_backup,
        )
    })
    .await
    .map_err(|error| BlobError::Configuration(format!("backup task join failed: {error}")))??;
    let archive_size_bytes = tokio::fs::metadata(&temp_archive_path)
        .await
        .map_err(|error| {
            BlobError::Configuration(format!(
                "failed to stat backup archive {}: {error}",
                temp_archive_path.display()
            ))
        })?
        .len();

    let mut report = GatewayBackupRunReport {
        result: "success".to_string(),
        archive_size_bytes,
        local_filename: None,
        local_path: None,
        remote_provider: None,
        remote_bucket: None,
        remote_key: None,
        error: None,
    };
    let mut upload_path = temp_archive_path.clone();

    if policy.local_enabled {
        let local_path = move_gateway_backup_archive_to_local(
            &temp_archive_path,
            &policy.local_directory,
            &filename,
        )
        .await?;
        report.local_filename = Some(filename.clone());
        report.local_path = Some(local_path.display().to_string());
        upload_path = local_path.clone();
        if let Err(error) = retain_local_gateway_backup_archives(
            &policy.local_directory,
            policy.local_retention_count,
        ) {
            report.result = "partial".to_string();
            report.error = Some(error.to_string());
        }
    }

    if policy.remote_enabled {
        let provider = policy.remote_provider.ok_or_else(|| {
            BlobError::Configuration("启用云端自动备份前，必须先选择一个目标云盘".to_string())
        })?;
        match upload_gateway_backup_archive_to_provider(
            state,
            provider,
            &upload_path,
            archive_size_bytes,
            &filename,
        )
        .await
        {
            Ok(object_key) => {
                report.remote_provider = Some(provider);
                report.remote_bucket = Some(GATEWAY_BACKUP_REMOTE_BUCKET.to_string());
                report.remote_key = Some(object_key.clone());
                if let Err(error) = retain_remote_gateway_backup_archives(
                    state,
                    provider,
                    policy.remote_retention_count,
                )
                .await
                {
                    report.result = "partial".to_string();
                    report.error = Some(error.to_string());
                }
            }
            Err(error) if report.local_path.is_some() => {
                report.result = "partial".to_string();
                report.error = Some(error.to_string());
            }
            Err(error) => return Err(error),
        }
    }

    if !policy.local_enabled {
        let _ = tokio::fs::remove_file(&temp_archive_path).await;
    }

    if report.local_path.is_some() || report.remote_key.is_some() {
        state
            .metadata_store
            .update_gateway_write_ahead_log_checkpoint_lsn(
                backup_build.checkpoint_lsn,
                current_unix_ms(),
            )
            .map_err(|error| BlobError::Upstream(error.to_string()))?;
        if let Err(error) = cleanup_gateway_write_ahead_log_remote(state).await {
            warn!(error = %error, "failed to cleanup checkpointed gateway write-ahead log records");
        }
    }

    Ok(report)
}

async fn move_gateway_backup_archive_to_local(
    temp_archive_path: &FsPath,
    local_directory: &str,
    filename: &str,
) -> Result<PathBuf, BlobError> {
    let local_dir = PathBuf::from(local_directory);
    tokio::fs::create_dir_all(&local_dir)
        .await
        .map_err(|error| {
            BlobError::Configuration(format!(
                "failed to create backup directory {}: {error}",
                local_dir.display()
            ))
        })?;
    let local_path = local_dir.join(filename);
    match tokio::fs::rename(temp_archive_path, &local_path).await {
        Ok(()) => {
            #[cfg(unix)]
            fs::set_permissions(&local_path, fs::Permissions::from_mode(0o600)).map_err(
                |error| {
                    BlobError::Configuration(format!(
                        "failed to protect local backup file {}: {error}",
                        local_path.display()
                    ))
                },
            )?;
            Ok(local_path)
        }
        Err(_) => {
            tokio::fs::copy(temp_archive_path, &local_path)
                .await
                .map_err(|error| {
                    BlobError::Configuration(format!(
                        "failed to copy backup archive into {}: {error}",
                        local_path.display()
                    ))
                })?;
            let _ = tokio::fs::remove_file(temp_archive_path).await;
            #[cfg(unix)]
            fs::set_permissions(&local_path, fs::Permissions::from_mode(0o600)).map_err(
                |error| {
                    BlobError::Configuration(format!(
                        "failed to protect local backup file {}: {error}",
                        local_path.display()
                    ))
                },
            )?;
            Ok(local_path)
        }
    }
}

fn retain_local_gateway_backup_archives(
    local_directory: &str,
    keep_count: usize,
) -> Result<(), BlobError> {
    let dir = PathBuf::from(local_directory);
    let entries = match fs::read_dir(&dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => {
            return Err(BlobError::Configuration(format!(
                "failed to read backup directory {}: {error}",
                dir.display()
            )));
        }
    };
    let mut paths = entries
        .filter_map(|entry| entry.ok().map(|item| item.path()))
        .filter(|path| path.extension().and_then(|value| value.to_str()) == Some("ccbgbak"))
        .collect::<Vec<_>>();
    paths.sort_by(|left, right| right.file_name().cmp(&left.file_name()));
    for path in paths.into_iter().skip(keep_count) {
        fs::remove_file(&path).map_err(|error| {
            BlobError::Configuration(format!(
                "failed to prune old local backup {}: {error}",
                path.display()
            ))
        })?;
    }
    Ok(())
}

async fn upload_gateway_backup_archive_to_provider(
    state: &AppState,
    provider: ProviderId,
    archive_path: &FsPath,
    archive_size_bytes: u64,
    filename: &str,
) -> Result<String, BlobError> {
    let backend = backend_for_provider(state, provider)?;
    if !backend.capabilities().write {
        return Err(BlobError::Configuration(format!(
            "{} 当前不支持写入，无法接收网关备份",
            provider_label(provider)
        )));
    }
    if !backend.capabilities().streaming_put
        && archive_size_bytes > state.config.max_in_memory_object_bytes as u64
    {
        return Err(BlobError::Configuration(format!(
            "{} 不支持流式上传，而备份归档 {} B 超过当前内存上限 {} B",
            provider_label(provider),
            archive_size_bytes,
            state.config.max_in_memory_object_bytes
        )));
    }
    let key = format!(
        "{}/{}",
        gateway_backup_remote_prefix(&state.config),
        filename
    );
    let body = stream_gateway_backup_archive_file(
        archive_path,
        state.config.spooled_body_chunk_bytes.max(64 * 1024),
    )
    .await?;
    let write_path = if backend.capabilities().streaming_put {
        ProviderWritePathKind::Streaming
    } else {
        ProviderWritePathKind::InMemory
    };
    state
        .provider_resource_stats
        .record_write_path(provider.as_str(), write_path);
    let _write_operation = state
        .provider_resource_stats
        .start_operation(provider.as_str(), ProviderResourceOperationKind::Write);
    let write_started_at = current_unix_ms();
    let result = backend
        .put_object(PutObjectRequest {
            container: GATEWAY_BACKUP_REMOTE_BUCKET.to_string(),
            key: key.clone(),
            body,
            size: Some(archive_size_bytes),
            content_type: Some("application/vnd.ccbg.backup+octet-stream".to_string()),
            preferred_upload_part_size_bytes: None,
        })
        .await;
    match result {
        Ok(result) => {
            state.provider_io_stats.record_success_with_response(
                provider.as_str(),
                ProviderIoOperationKind::Write,
                current_unix_ms().saturating_sub(write_started_at),
                result.first_response_latency_ms,
                Some(archive_size_bytes),
            );
            Ok(key)
        }
        Err(error) => {
            state.provider_io_stats.record_failure(
                provider.as_str(),
                ProviderIoOperationKind::Write,
                &error.to_string(),
            );
            Err(error)
        }
    }
}

async fn stream_gateway_backup_archive_file(
    archive_path: &FsPath,
    chunk_bytes: usize,
) -> Result<ObjectBody, BlobError> {
    let file = TokioFile::open(archive_path).await.map_err(|error| {
        BlobError::Configuration(format!(
            "failed to open backup archive {}: {error}",
            archive_path.display()
        ))
    })?;
    Ok(ObjectBody::from_stream(futures_util::stream::try_unfold(
        (file, vec![0u8; chunk_bytes.max(1)]),
        |(mut file, mut buffer)| async move {
            let read = file
                .read(&mut buffer)
                .await
                .map_err(|error| BlobError::BodyStream(error.to_string()))?;
            if read == 0 {
                return Ok(None);
            }
            let chunk = Bytes::copy_from_slice(&buffer[..read]);
            Ok(Some((chunk, (file, buffer))))
        },
    )))
}

async fn retain_remote_gateway_backup_archives(
    state: &AppState,
    provider: ProviderId,
    keep_count: usize,
) -> Result<(), BlobError> {
    let backend = backend_for_provider(state, provider)?;
    let prefix = format!("{}/", gateway_backup_remote_prefix(&state.config));
    let mut objects = backend
        .list_objects(ListObjectsRequest {
            container: Some(GATEWAY_BACKUP_REMOTE_BUCKET.to_string()),
            prefix: Some(prefix),
            limit: Some(512),
        })
        .await?;
    objects.sort_by(|left, right| right.key.cmp(&left.key));
    if objects.len() <= keep_count {
        return Ok(());
    }
    if !backend.capabilities().delete {
        return Err(BlobError::Configuration(format!(
            "{} 不支持删除，无法自动清理旧的云端备份副本",
            provider_label(provider)
        )));
    }
    for object in objects.into_iter().skip(keep_count) {
        backend
            .delete_object(GATEWAY_BACKUP_REMOTE_BUCKET, &object.key)
            .await?;
    }
    Ok(())
}

fn effective_unicom_request_header_client_id(credentials: &ProviderCredentialRecord) -> String {
    credentials
        .client_id
        .clone()
        .unwrap_or_else(|| env_or("CCBG_UNICOM_HEADER_CLIENT_ID", "1001000021"))
}

fn effective_unicom_dispatcher_client_id(credentials: &ProviderCredentialRecord) -> String {
    credentials
        .client_id
        .clone()
        .unwrap_or_else(|| env_or("CCBG_UNICOM_DISPATCHER_CLIENT_ID", "1001000021"))
}

fn effective_onedrive_config_from_app(config: &AppConfig) -> OneDriveConfig {
    let credentials = load_provider_credential_record_or_default(config, ProviderId::Onedrive);
    let mut resolved = config.onedrive.clone();
    if let Some(client_id) = credentials.client_id {
        resolved.client_id = Some(client_id);
    }
    if let Some(tenant) = credentials.tenant {
        resolved.tenant = tenant;
    }
    if let Some(drive_id) = credentials.drive_id {
        resolved.drive_id = Some(drive_id);
    }
    if let Some(redirect_url) = credentials.redirect_url {
        resolved.redirect_url = Some(redirect_url);
    }
    if let Some(token) = credentials.token {
        resolved.token_source = TokenSource::Static { bearer: token };
        // Manual token injection should take precedence over any stale OAuth session file.
        resolved.session_file = None;
    }
    resolved
}

