const MIN_ENCRYPTION_CHUNK_PLAINTEXT_BYTES: u64 = 64 * 1024;
const MAX_ENCRYPTION_CHUNK_PLAINTEXT_BYTES: u64 = 16 * 1024 * 1024;

fn normalize_encryption_profiles(
    profiles: Vec<EncryptionProfileInput>,
) -> Result<Vec<EncryptionProfile>, BlobError> {
    let mut normalized = Vec::with_capacity(profiles.len());
    let mut ids = HashSet::new();

    for profile in profiles {
        let id = profile.id.trim().to_string();
        if id.is_empty() {
            return Err(BlobError::Configuration(
                "encryption profile id must not be empty".to_string(),
            ));
        }
        if !ids.insert(id.clone()) {
            return Err(BlobError::Configuration(format!(
                "duplicate encryption profile id: {id}"
            )));
        }

        let key_id = profile.key_id.trim().to_string();
        if key_id.is_empty() {
            return Err(BlobError::Configuration(format!(
                "encryption profile {id} key_id must not be empty"
            )));
        }

        let key_source_ref = profile.key_source_ref.trim().to_string();
        if key_source_ref.is_empty() {
            return Err(BlobError::Configuration(format!(
                "encryption profile {id} key_source_ref must not be empty"
            )));
        }

        if !(MIN_ENCRYPTION_CHUNK_PLAINTEXT_BYTES..=MAX_ENCRYPTION_CHUNK_PLAINTEXT_BYTES)
            .contains(&profile.chunk_plaintext_bytes)
        {
            return Err(BlobError::Configuration(format!(
                "encryption profile {id} chunk_plaintext_bytes must be between {} and {} bytes",
                MIN_ENCRYPTION_CHUNK_PLAINTEXT_BYTES, MAX_ENCRYPTION_CHUNK_PLAINTEXT_BYTES
            )));
        }

        normalized.push(EncryptionProfile {
            id,
            label: normalize_secret_field(profile.label),
            enabled: profile.enabled,
            algorithm_preference: profile.algorithm_preference,
            chunk_plaintext_bytes: profile.chunk_plaintext_bytes,
            key_id,
            key_source_kind: profile.key_source_kind,
            key_source_ref,
            notes: normalize_secret_field(profile.notes),
        });
    }

    Ok(normalized)
}

fn current_encryption_profiles(state: &AppState) -> Vec<EncryptionProfile> {
    state
        .control_plane
        .lock()
        .expect("control plane state poisoned")
        .encryption_profiles
        .clone()
}

fn encryption_profile_referencing_managed_key(
    profiles: &[EncryptionProfile],
    key_id: &str,
) -> Vec<String> {
    profiles
        .iter()
        .filter(|profile| {
            profile.key_source_kind == EncryptionKeySourceKind::GatewayManaged
                && profile.key_source_ref == key_id
        })
        .map(|profile| profile.id.clone())
        .collect()
}

fn encryption_profile_payload(profile: &EncryptionProfile) -> EncryptionProfilePayload {
    EncryptionProfilePayload {
        id: profile.id.clone(),
        label: profile.label.clone(),
        enabled: profile.enabled,
        algorithm_preference: profile.algorithm_preference,
        chunk_plaintext_bytes: profile.chunk_plaintext_bytes,
        key_id: profile.key_id.clone(),
        key_source_kind: profile.key_source_kind,
        key_source_ref: profile.key_source_ref.clone(),
        notes: profile.notes.clone(),
    }
}

fn current_encryption_profile_payloads(state: &AppState) -> Vec<EncryptionProfilePayload> {
    current_encryption_profiles(state)
        .iter()
        .map(encryption_profile_payload)
        .collect()
}

trait ExternalKmsProvider {
    fn kind(&self) -> &'static str;
    fn fetch_key_material(&self, profile: &EncryptionProfile) -> Result<Vec<u8>, BlobError>;
}

struct MockEnvExternalKmsProvider {
    env_name: String,
}

impl ExternalKmsProvider for MockEnvExternalKmsProvider {
    fn kind(&self) -> &'static str {
        "mock_env"
    }

    fn fetch_key_material(&self, profile: &EncryptionProfile) -> Result<Vec<u8>, BlobError> {
        if self.env_name.trim().is_empty() {
            return Err(BlobError::Configuration(format!(
                "external KMS profile {} mock-env locator is empty",
                profile.id
            )));
        }
        let raw = env::var(&self.env_name).map_err(|_| {
            BlobError::Configuration(format!(
                "external KMS profile {} could not resolve mock-env key material",
                profile.id
            ))
        })?;
        Ok(raw.into_bytes())
    }
}

struct MockFileExternalKmsProvider {
    path: String,
}

impl ExternalKmsProvider for MockFileExternalKmsProvider {
    fn kind(&self) -> &'static str {
        "mock_file"
    }

    fn fetch_key_material(&self, profile: &EncryptionProfile) -> Result<Vec<u8>, BlobError> {
        if self.path.trim().is_empty() {
            return Err(BlobError::Configuration(format!(
                "external KMS profile {} mock-file locator is empty",
                profile.id
            )));
        }
        fs::read(&self.path).map_err(|error| {
            BlobError::Configuration(format!(
                "external KMS profile {} failed to read mock-file key material: {error}",
                profile.id
            ))
        })
    }
}

fn external_kms_provider_for_ref(
    key_source_ref: &str,
) -> Result<Box<dyn ExternalKmsProvider>, BlobError> {
    let trimmed = key_source_ref.trim();
    if let Some(env_name) = trimmed.strip_prefix("mock-env://") {
        return Ok(Box::new(MockEnvExternalKmsProvider {
            env_name: env_name.trim().to_string(),
        }));
    }
    if let Some(path) = trimmed.strip_prefix("mock-file://") {
        return Ok(Box::new(MockFileExternalKmsProvider {
            path: path.trim().to_string(),
        }));
    }
    Err(BlobError::Configuration(format!(
        "unsupported external KMS locator scheme; supported schemes are mock-env:// and mock-file://"
    )))
}

fn external_kms_cache_key(profile: &EncryptionProfile) -> String {
    format!(
        "{}\n{}\n{}",
        profile.id,
        profile.key_id,
        profile.key_source_ref.trim()
    )
}

fn external_kms_redacted_source_ref(key_source_ref: &str) -> String {
    let trimmed = key_source_ref.trim();
    if let Some(_) = trimmed.strip_prefix("mock-env://") {
        return "mock-env://<redacted>".to_string();
    }
    if let Some(_) = trimmed.strip_prefix("mock-file://") {
        return "mock-file://<redacted>".to_string();
    }
    if let Some((scheme, _)) = trimmed.split_once("://") {
        return format!("{scheme}://<redacted>");
    }
    "<redacted>".to_string()
}

fn external_kms_redacted_error(profile_id: &str) -> String {
    format!("external KMS key material refresh failed for encryption profile {profile_id}")
}

fn external_kms_cache_expiry(now_unix_ms: u64, ttl_ms: u64) -> Option<u64> {
    if ttl_ms == 0 {
        None
    } else {
        Some(now_unix_ms.saturating_add(ttl_ms))
    }
}

fn external_kms_cache_entry_is_fresh(entry: &ExternalKmsCacheEntry, now_unix_ms: u64) -> bool {
    match entry.expires_at_unix_ms {
        Some(expires_at_unix_ms) => expires_at_unix_ms > now_unix_ms,
        None => false,
    }
}

fn load_external_kms_key_material(
    state: &AppState,
    profile: &EncryptionProfile,
) -> Result<[u8; 32], BlobError> {
    let cache_key = external_kms_cache_key(profile);
    let now_unix_ms = current_unix_ms();
    {
        let runtime = state
            .external_kms_runtime
            .lock()
            .expect("external KMS runtime poisoned");
        if let Some(entry) = runtime.cache.get(&cache_key) {
            if external_kms_cache_entry_is_fresh(entry, now_unix_ms) {
                return Ok(entry.key_material);
            }
        }
    }

    let configured_provider = state.config.external_kms_provider.trim();
    if configured_provider != "local_mock" {
        return Err(BlobError::Configuration(format!(
            "unsupported external KMS provider: {configured_provider}; supported provider is local_mock"
        )));
    }
    let provider = external_kms_provider_for_ref(&profile.key_source_ref)?;
    let provider_kind = provider.kind();
    let fetched = provider.fetch_key_material(profile);
    match fetched {
        Ok(bytes) => {
            let key_material = parse_file_key_material(
                &bytes,
                format!("external KMS {} profile {}", provider_kind, profile.id).as_str(),
            )?;
            let entry = ExternalKmsCacheEntry {
                key_material,
                fingerprint_sha256: hash_hex(&key_material),
                fetched_at_unix_ms: now_unix_ms,
                expires_at_unix_ms: external_kms_cache_expiry(
                    now_unix_ms,
                    state.config.external_kms_cache_ttl_ms,
                ),
                provider_kind,
            };
            let mut runtime = state
                .external_kms_runtime
                .lock()
                .expect("external KMS runtime poisoned");
            runtime.cache.insert(cache_key.clone(), entry);
            runtime.latest_errors.remove(&cache_key);
            Ok(key_material)
        }
        Err(error) => {
            let message = external_kms_redacted_error(&profile.id);
            let mut runtime = state
                .external_kms_runtime
                .lock()
                .expect("external KMS runtime poisoned");
            runtime
                .latest_errors
                .insert(cache_key.clone(), message.clone());
            if let Some(entry) = runtime.cache.get(&cache_key) {
                return Ok(entry.key_material);
            }
            Err(BlobError::Configuration(format!(
                "{message}: {}",
                external_kms_error_kind(&error)
            )))
        }
    }
}

fn external_kms_error_kind(error: &BlobError) -> &'static str {
    match error {
        BlobError::Configuration(_) => "configuration_error",
        BlobError::Upstream(_) => "upstream_error",
        BlobError::InteractiveInputRequired(_) => "interactive_input_required",
        BlobError::NotImplemented(_) => "not_implemented",
        BlobError::NotFound(_) => "not_found",
        BlobError::BodyStream(_) => "body_stream_error",
    }
}

fn external_kms_status_payload(state: &AppState) -> Vec<ExternalKmsStatusEntryPayload> {
    let profiles = current_encryption_profiles(state)
        .into_iter()
        .filter(|profile| profile.key_source_kind == EncryptionKeySourceKind::ExternalKms)
        .collect::<Vec<_>>();
    let runtime = state
        .external_kms_runtime
        .lock()
        .expect("external KMS runtime poisoned");
    let mut seen = HashSet::new();
    let mut payloads = profiles
        .into_iter()
        .map(|profile| {
            let cache_key = external_kms_cache_key(&profile);
            seen.insert(cache_key.clone());
            let cache = runtime.cache.get(&cache_key);
            ExternalKmsStatusEntryPayload {
                profile_id: profile.id,
                key_id: profile.key_id,
                key_source_ref: external_kms_redacted_source_ref(&profile.key_source_ref),
                provider_kind: cache.map(|entry| entry.provider_kind),
                cached: cache.is_some(),
                fetched_at_unix_ms: cache.map(|entry| entry.fetched_at_unix_ms),
                expires_at_unix_ms: cache.and_then(|entry| entry.expires_at_unix_ms),
                fingerprint_sha256: cache.map(|entry| entry.fingerprint_sha256.clone()),
                last_error: runtime.latest_errors.get(&cache_key).cloned(),
            }
        })
        .collect::<Vec<_>>();
    for cache_key in runtime.cache.keys().chain(runtime.latest_errors.keys()) {
        if !seen.insert(cache_key.clone()) {
            continue;
        }
        let mut parts = cache_key.splitn(3, '\n');
        let profile_id = parts.next().unwrap_or("unknown").to_string();
        let key_id = parts.next().unwrap_or("unknown").to_string();
        let key_source_ref = external_kms_redacted_source_ref(parts.next().unwrap_or(""));
        let cache = runtime.cache.get(cache_key);
        payloads.push(ExternalKmsStatusEntryPayload {
            profile_id,
            key_id,
            key_source_ref,
            provider_kind: cache.map(|entry| entry.provider_kind),
            cached: cache.is_some(),
            fetched_at_unix_ms: cache.map(|entry| entry.fetched_at_unix_ms),
            expires_at_unix_ms: cache.and_then(|entry| entry.expires_at_unix_ms),
            fingerprint_sha256: cache.map(|entry| entry.fingerprint_sha256.clone()),
            last_error: runtime.latest_errors.get(cache_key).cloned(),
        });
    }
    payloads
}

fn resolve_enabled_encryption_profile_by_id(
    state: &AppState,
    profile_id: &str,
    reason: &str,
) -> Result<EncryptionProfile, S3Error> {
    let profile = current_encryption_profiles(state)
        .into_iter()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| {
            S3Error::internal_error(format!(
                "{reason} references missing encryption profile {profile_id}"
            ))
        })?;
    if !profile.enabled {
        return Err(S3Error::internal_error(format!(
            "{reason} references disabled encryption profile {profile_id}"
        )));
    }
    Ok(profile)
}

fn effective_encryption_profile_for_write(
    state: &AppState,
    application: &S3ApplicationIdentity,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> Result<Option<EncryptionProfile>, S3Error> {
    if let Some(policy) = matching_content_policy(
        state,
        Some(application.application_id.as_str()),
        bucket,
        key,
        content_type,
    ) {
        if let Some(profile_id) = policy.encryption_profile_id.as_deref() {
            return resolve_enabled_encryption_profile_by_id(
                state,
                profile_id,
                format!("content policy {}", policy.id).as_str(),
            )
            .map(Some);
        }
    }
    Ok(None)
}

fn load_profile_encryption_key_material(
    state: &AppState,
    profile: &EncryptionProfile,
) -> Result<[u8; 32], BlobError> {
    match profile.key_source_kind {
        EncryptionKeySourceKind::GatewayManaged => {
            let record =
                load_managed_encryption_key_record(state.config.as_ref(), &profile.key_source_ref)?;
            let decoded = BASE64_STANDARD
                .decode(record.key_material_base64.as_bytes())
                .map_err(|error| {
                    BlobError::Configuration(format!(
                        "managed encryption key {} contains invalid base64 key material: {error}",
                        record.id
                    ))
                })?;
            key_material_from_bytes(
                decoded,
                format!("managed encryption key {}", record.id).as_str(),
            )
        }
        EncryptionKeySourceKind::EnvVar => {
            let env_name = profile.key_source_ref.trim();
            if env_name.is_empty() {
                return Err(BlobError::Configuration(format!(
                    "encryption profile {} env_var key source is empty",
                    profile.id
                )));
            }
            let raw = env::var(env_name).map_err(|_| {
                BlobError::Configuration(format!(
                    "encryption profile {} requires environment variable {}",
                    profile.id, env_name
                ))
            })?;
            parse_text_key_material(
                raw.as_str(),
                format!("environment variable {env_name}").as_str(),
            )
        }
        EncryptionKeySourceKind::FilePath => {
            let path = profile.key_source_ref.trim();
            if path.is_empty() {
                return Err(BlobError::Configuration(format!(
                    "encryption profile {} file_path key source is empty",
                    profile.id
                )));
            }
            let bytes = fs::read(path).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to read encryption key file {}: {error}",
                    path
                ))
            })?;
            parse_file_key_material(&bytes, format!("file {path}").as_str())
        }
        EncryptionKeySourceKind::ExternalKms => load_external_kms_key_material(state, profile),
    }
}

fn parse_file_key_material(bytes: &[u8], source: &str) -> Result<[u8; 32], BlobError> {
    if bytes.len() == 32 {
        return key_material_from_bytes(bytes.to_vec(), source);
    }
    let raw = std::str::from_utf8(bytes).map_err(|error| {
        BlobError::Configuration(format!(
            "encryption key material from {source} is neither 32 raw bytes nor valid UTF-8: {error}"
        ))
    })?;
    parse_text_key_material(raw, source)
}

fn parse_text_key_material(raw: &str, source: &str) -> Result<[u8; 32], BlobError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(BlobError::Configuration(format!(
            "encryption key material from {source} is empty"
        )));
    }
    if let Ok(decoded) = BASE64_STANDARD.decode(trimmed.as_bytes()) {
        if decoded.len() == 32 {
            return key_material_from_bytes(decoded, source);
        }
    }
    if let Ok(decoded) = hex::decode(trimmed) {
        if decoded.len() == 32 {
            return key_material_from_bytes(decoded, source);
        }
    }
    if trimmed.as_bytes().len() == 32 {
        return key_material_from_bytes(trimmed.as_bytes().to_vec(), source);
    }
    Err(BlobError::Configuration(format!(
        "encryption key material from {source} must be 32 raw bytes, 64 hex chars, or base64 for 32 bytes"
    )))
}

fn key_material_from_bytes(bytes: Vec<u8>, source: &str) -> Result<[u8; 32], BlobError> {
    if bytes.len() != 32 {
        return Err(BlobError::Configuration(format!(
            "encryption key material from {source} must be exactly 32 bytes"
        )));
    }
    let mut key = [0u8; 32];
    key.copy_from_slice(&bytes);
    Ok(key)
}

fn load_logical_object_record(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<Option<LogicalObjectRecord>, BlobError> {
    state
        .metadata_store
        .logical_object(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to load logical object metadata for {bucket}/{key}: {error}"
            ))
        })
}

fn persist_logical_object_record(
    state: &AppState,
    record: &LogicalObjectRecord,
) -> Result<(), BlobError> {
    state
        .metadata_store
        .upsert_logical_object(record)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to persist logical object metadata for {}/{}: {}",
                record.bucket, record.key, error
            ))
        })
}

fn delete_logical_object_record(
    state: &AppState,
    bucket: &str,
    key: &str,
) -> Result<(), BlobError> {
    state
        .metadata_store
        .delete_logical_object(bucket, key)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to delete logical object metadata for {bucket}/{key}: {error}"
            ))
        })
}

fn restore_logical_object_record(
    state: &AppState,
    previous: Option<LogicalObjectRecord>,
    bucket: &str,
    key: &str,
) {
    match previous {
        Some(record) => {
            let _ = persist_logical_object_record(state, &record);
        }
        None => {
            let _ = delete_logical_object_record(state, bucket, key);
        }
    }
}

fn public_object_info(
    object: blob_core::ObjectInfo,
    logical: Option<&LogicalObjectRecord>,
) -> blob_core::ObjectInfo {
    let Some(logical) = logical else {
        return object;
    };
    let etag = logical.etag.clone().or_else(|| object.etag.clone());
    if !logical.encrypted {
        return blob_core::ObjectInfo { etag, ..object };
    }

    blob_core::ObjectInfo {
        key: object.key,
        size: logical.plaintext_size,
        etag,
        content_type: logical.logical_content_type.clone().or(object.content_type),
        last_modified: object.last_modified,
    }
}

fn logical_object_records_for_bucket(
    state: &AppState,
    bucket: &str,
) -> Result<HashMap<String, LogicalObjectRecord>, BlobError> {
    Ok(state
        .metadata_store
        .logical_objects_for_bucket(bucket)
        .map_err(|error| {
            BlobError::Upstream(format!(
                "failed to list logical object metadata for bucket {bucket}: {error}"
            ))
        })?
        .into_iter()
        .map(|record| (record.key.clone(), record))
        .collect())
}

fn validate_managed_encryption_key_refs(
    config: &AppConfig,
    profiles: &[EncryptionProfile],
) -> Result<(), BlobError> {
    validate_managed_encryption_key_refs_for_dir(&config.credentials_dir, profiles)
}

fn validate_managed_encryption_key_refs_for_dir(
    credentials_dir: &str,
    profiles: &[EncryptionProfile],
) -> Result<(), BlobError> {
    for profile in profiles {
        if profile.key_source_kind != EncryptionKeySourceKind::GatewayManaged {
            continue;
        }
        let key_id = profile.key_source_ref.trim();
        if key_id.is_empty() {
            return Err(BlobError::Configuration(format!(
                "encryption profile {} key_source_ref must not be empty",
                profile.id
            )));
        }
        load_managed_encryption_key_record_from_credentials_dir(credentials_dir, key_id).map_err(
            |error| match error {
                BlobError::NotFound(_) => BlobError::Configuration(format!(
                    "encryption profile {} references unknown managed encryption key {}",
                    profile.id, key_id
                )),
                other => other,
            },
        )?;
    }
    Ok(())
}

fn managed_encryption_key_payload(
    record: &ManagedEncryptionKeyRecord,
    profiles: &[EncryptionProfile],
) -> Result<ManagedEncryptionKeyPayload, BlobError> {
    let key_material = BASE64_STANDARD
        .decode(record.key_material_base64.as_bytes())
        .map_err(|error| {
            BlobError::Configuration(format!(
                "managed encryption key {} contains invalid base64 key material: {error}",
                record.id
            ))
        })?;
    Ok(ManagedEncryptionKeyPayload {
        id: record.id.clone(),
        label: record.label.clone(),
        kind: record.kind,
        key_material_bytes: key_material.len(),
        fingerprint_sha256: hash_hex(&key_material),
        created_at_unix_ms: record.created_at_unix_ms,
        updated_at_unix_ms: record.updated_at_unix_ms,
        notes: record.notes.clone(),
        referencing_profile_ids: encryption_profile_referencing_managed_key(profiles, &record.id),
    })
}

fn current_managed_encryption_key_payloads(
    state: &AppState,
) -> Result<Vec<ManagedEncryptionKeyPayload>, BlobError> {
    let profiles = current_encryption_profiles(state);
    load_all_managed_encryption_key_records(&state.config)?
        .iter()
        .map(|record| managed_encryption_key_payload(record, &profiles))
        .collect()
}

fn normalize_content_policies(
    policies: Vec<ContentPolicyRule>,
) -> Result<Vec<ContentPolicyRule>, BlobError> {
    let mut normalized = Vec::with_capacity(policies.len());
    let mut ids = HashSet::new();

    for mut policy in policies {
        policy.id = policy.id.trim().to_string();
        if policy.id.is_empty() {
            return Err(BlobError::Configuration(
                "content policy id must not be empty".to_string(),
            ));
        }
        if !ids.insert(policy.id.clone()) {
            return Err(BlobError::Configuration(format!(
                "duplicate content policy id: {}",
                policy.id
            )));
        }
        policy.label = normalize_secret_field(policy.label);
        policy.application_ids = normalize_string_list(&policy.application_ids);
        policy.buckets = normalize_bucket_list(&policy.buckets);
        policy.prefixes = normalize_prefix_list(&policy.prefixes);
        policy.content_types = normalize_content_type_list(&policy.content_types);
        policy.encryption_profile_id = normalize_secret_field(policy.encryption_profile_id);
        policy.sync_targets = dedupe_provider_ids(policy.sync_targets);
        policy.fallback_read_order = dedupe_provider_ids(policy.fallback_read_order);
        for provider in &policy.sync_targets {
            if !provider.can_be_sync_target() {
                return Err(BlobError::Configuration(format!(
                    "content policy {} has invalid sync target {}",
                    policy.id,
                    provider.as_str()
                )));
            }
        }
        for provider in &policy.fallback_read_order {
            if !policy.sync_targets.is_empty() && !policy.sync_targets.contains(provider) {
                return Err(BlobError::Configuration(format!(
                    "content policy {} fallback provider {} must also be a sync target",
                    policy.id,
                    provider.as_str()
                )));
            }
        }
        normalized.push(policy);
    }

    Ok(normalized)
}

fn validate_content_policy_encryption_profile_refs(
    policies: &[ContentPolicyRule],
    profiles: &[EncryptionProfile],
) -> Result<(), BlobError> {
    let profile_ids = profiles
        .iter()
        .map(|profile| profile.id.as_str())
        .collect::<HashSet<_>>();
    for policy in policies {
        let Some(profile_id) = policy.encryption_profile_id.as_deref() else {
            continue;
        };
        if !profile_ids.contains(profile_id) {
            return Err(BlobError::Configuration(format!(
                "content policy {} references unknown encryption profile {}",
                policy.id, profile_id
            )));
        }
    }
    Ok(())
}

fn drop_unreferenced_encryption_profiles_with_missing_keys(
    credentials_dir: &str,
    profiles: Vec<EncryptionProfile>,
    policies: &[ContentPolicyRule],
) -> Result<Vec<EncryptionProfile>, BlobError> {
    let referenced_profile_ids = policies
        .iter()
        .filter_map(|policy| policy.encryption_profile_id.as_deref())
        .collect::<HashSet<_>>();
    let mut retained = Vec::with_capacity(profiles.len());

    for profile in profiles {
        if profile.key_source_kind != EncryptionKeySourceKind::GatewayManaged {
            retained.push(profile);
            continue;
        }
        let key_id = profile.key_source_ref.trim();
        if key_id.is_empty() {
            return Err(BlobError::Configuration(format!(
                "encryption profile {} key_source_ref must not be empty",
                profile.id
            )));
        }
        match load_managed_encryption_key_record_from_credentials_dir(credentials_dir, key_id) {
            Ok(_) => retained.push(profile),
            Err(BlobError::NotFound(_))
                if !referenced_profile_ids.contains(profile.id.as_str()) =>
            {
                tracing::warn!(
                    profile_id = profile.id.as_str(),
                    key_id,
                    "dropping unreferenced encryption profile with missing managed key while loading control plane"
                );
            }
            Err(BlobError::NotFound(_)) => {
                return Err(BlobError::Configuration(format!(
                    "encryption profile {} references unknown managed encryption key {}",
                    profile.id, key_id
                )));
            }
            Err(error) => return Err(error),
        }
    }

    Ok(retained)
}

fn normalize_string_list(values: &[String]) -> Vec<String> {
    let mut seen = HashSet::new();
    let mut normalized = Vec::new();
    for value in values {
        let value = value.trim().to_string();
        if !value.is_empty() && seen.insert(value.clone()) {
            normalized.push(value);
        }
    }
    normalized
}

fn normalize_content_type_list(values: &[String]) -> Vec<String> {
    let mut seen = HashSet::new();
    let mut normalized = Vec::new();
    for value in values {
        let value = value.trim().to_ascii_lowercase();
        if !value.is_empty() && seen.insert(value.clone()) {
            normalized.push(value);
        }
    }
    normalized
}

fn current_content_policies(state: &AppState) -> Vec<ContentPolicyRule> {
    state
        .control_plane
        .lock()
        .expect("control plane state poisoned")
        .content_policies
        .clone()
}

fn current_provider_limit_probes(
    state: &AppState,
) -> BTreeMap<ProviderId, ProviderLimitProbePayload> {
    state
        .control_plane
        .lock()
        .expect("control plane state poisoned")
        .provider_limit_probes
        .clone()
}

fn current_provider_limit_profiles(
    state: &AppState,
) -> BTreeMap<ProviderId, ProviderLimitProfilePayload> {
    state
        .control_plane
        .lock()
        .expect("control plane state poisoned")
        .provider_limit_profiles
        .clone()
}

fn content_type_matches(patterns: &[String], content_type: Option<&str>) -> bool {
    if patterns.is_empty() {
        return true;
    }
    let Some(content_type) = content_type else {
        return false;
    };
    let content_type = content_type.trim().to_ascii_lowercase();
    patterns.iter().any(|pattern| {
        if let Some(prefix) = pattern.strip_suffix("/*") {
            content_type.starts_with(&format!("{prefix}/"))
        } else {
            pattern == &content_type
        }
    })
}

fn content_policy_matches(
    policy: &ContentPolicyRule,
    application_id: Option<&str>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> bool {
    if !policy.enabled {
        return false;
    }
    if !policy.application_ids.is_empty() {
        let Some(application_id) = application_id else {
            return false;
        };
        if !policy.application_ids.iter().any(|id| id == application_id) {
            return false;
        }
    }
    if !policy.buckets.is_empty() && !policy.buckets.iter().any(|value| value == bucket) {
        return false;
    }
    if !policy.prefixes.is_empty() && !policy.prefixes.iter().any(|prefix| key.starts_with(prefix))
    {
        return false;
    }
    content_type_matches(&policy.content_types, content_type)
}

fn matching_content_policy(
    state: &AppState,
    application_id: Option<&str>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> Option<ContentPolicyRule> {
    current_content_policies(state)
        .into_iter()
        .find(|policy| content_policy_matches(policy, application_id, bucket, key, content_type))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct S3ApplicationIdentity {
    application_id: String,
    access_key_id: String,
    affiliation: Option<String>,
    permissions: DataPlaneApplicationPermissions,
}

fn resolve_s3_application(
    state: &AppState,
    access_key_id: &str,
) -> Option<(S3ApplicationIdentity, String)> {
    current_data_plane_applications(state)
        .into_iter()
        .find(|application| application.enabled && application.access_key_id == access_key_id)
        .map(|application| {
            (
                S3ApplicationIdentity {
                    application_id: application.id,
                    access_key_id: application.access_key_id,
                    affiliation: application.affiliation,
                    permissions: application.permissions,
                },
                application.secret_access_key,
            )
        })
}

fn preferred_affiliation_provider_for_application_write(
    state: &AppState,
    application: Option<&S3ApplicationIdentity>,
    bucket: &str,
    key: &str,
    content_type: Option<&str>,
) -> Option<ProviderId> {
    let application = application?;
    if matching_content_policy(
        state,
        Some(application.application_id.as_str()),
        bucket,
        key,
        content_type,
    )
    .is_some()
    {
        return None;
    }

    let affiliation = application.affiliation.as_deref()?;
    let provider = ProviderId::parse(affiliation).ok()?;
    if provider.can_be_primary() {
        Some(provider)
    } else {
        None
    }
}

fn normalize_probe_key_prefix(value: Option<&str>) -> String {
    let normalized = value
        .unwrap_or("ccbg-limit-probes")
        .trim()
        .trim_matches('/')
        .to_string();
    if normalized.is_empty() {
        "ccbg-limit-probes".to_string()
    } else {
        normalized
    }
}

#[derive(Debug, Clone, Copy)]
enum S3ActionKind {
    ListBuckets,
    ListObjects,
    ReadObject,
    WriteObject,
    DeleteObject,
}

impl S3ActionKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::ListBuckets => "list_buckets",
            Self::ListObjects => "list_objects",
            Self::ReadObject => "read_object",
            Self::WriteObject => "write_object",
            Self::DeleteObject => "delete_object",
        }
    }
}

fn data_plane_permission_allowed(
    permissions: &DataPlaneApplicationPermissions,
    action: S3ActionKind,
    bucket: Option<&str>,
    key: Option<&str>,
) -> bool {
    let action_allowed = match action {
        S3ActionKind::ListBuckets => permissions.list_buckets,
        S3ActionKind::ListObjects => permissions.list_objects,
        S3ActionKind::ReadObject => permissions.read_object,
        S3ActionKind::WriteObject => permissions.write_object,
        S3ActionKind::DeleteObject => permissions.delete_object,
    };
    if !action_allowed {
        return false;
    }
    if matches!(action, S3ActionKind::ListBuckets) {
        return true;
    }
    if !permissions.allowed_buckets.is_empty() {
        let Some(bucket) = bucket else {
            return false;
        };
        if !permissions
            .allowed_buckets
            .iter()
            .any(|value| value == bucket)
        {
            return false;
        }
    }
    if matches!(action, S3ActionKind::ListObjects) && key.is_none() {
        return true;
    }
    if !permissions.allowed_prefixes.is_empty() {
        let Some(key) = key else {
            return false;
        };
        let prefix_allowed = match action {
            S3ActionKind::ListObjects => permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| list_prefix_overlaps_allowed_prefix(key, prefix)),
            _ => permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| object_key_matches_allowed_prefix(key, prefix)),
        };
        if !prefix_allowed {
            return false;
        }
    }
    true
}

fn object_key_matches_allowed_prefix(key: &str, allowed_prefix: &str) -> bool {
    if allowed_prefix.is_empty() {
        return true;
    }
    key == allowed_prefix
        || key
            .strip_prefix(allowed_prefix)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn list_prefix_overlaps_allowed_prefix(request_prefix: &str, allowed_prefix: &str) -> bool {
    request_prefix.is_empty()
        || object_key_matches_allowed_prefix(request_prefix, allowed_prefix)
        || allowed_prefix.starts_with(request_prefix)
}

fn ensure_s3_application_permission(
    application: &S3ApplicationIdentity,
    action: S3ActionKind,
    bucket: Option<&str>,
    key: Option<&str>,
) -> Result<(), S3Error> {
    if data_plane_permission_allowed(&application.permissions, action, bucket, key) {
        return Ok(());
    }
    let scope = match (bucket, key) {
        (Some(bucket), Some(key)) => format!("{bucket}/{key}"),
        (Some(bucket), None) => bucket.to_string(),
        (None, _) => "gateway".to_string(),
    };
    Err(S3Error::access_denied(format!(
        "Application {} is not allowed to perform {} on {}.",
        application.application_id,
        action.as_str(),
        scope
    )))
}

fn filter_containers_for_application(
    containers: Vec<blob_core::ContainerInfo>,
    application: &S3ApplicationIdentity,
) -> Vec<blob_core::ContainerInfo> {
    if application.permissions.allowed_buckets.is_empty() {
        return containers;
    }
    containers
        .into_iter()
        .filter(|container| {
            application
                .permissions
                .allowed_buckets
                .iter()
                .any(|bucket| bucket == &container.name)
        })
        .collect()
}

fn filter_objects_for_application(
    objects: Vec<blob_core::ObjectInfo>,
    application: &S3ApplicationIdentity,
) -> Vec<blob_core::ObjectInfo> {
    if application.permissions.allowed_prefixes.is_empty() {
        return objects;
    }
    objects
        .into_iter()
        .filter(|object| {
            application
                .permissions
                .allowed_prefixes
                .iter()
                .any(|prefix| object_key_matches_allowed_prefix(&object.key, prefix))
        })
        .collect()
}

fn provider_limit_probe_sizes(input: &ProviderLimitProbeInput) -> Result<Vec<u64>, BlobError> {
    let mut sizes = Vec::new();
    for raw in &input.sizes {
        sizes.push(parse_byte_size_limit(raw).map_err(|error| {
            BlobError::Configuration(format!("invalid limit probe size '{raw}': {error}"))
        })?);
    }
    sizes.extend(input.sizes_bytes.iter().copied());
    sizes.sort_unstable();
    sizes.dedup();
    sizes.retain(|size| *size > 0);
    if sizes.is_empty() {
        return Err(BlobError::Configuration(
            "limit probe requires at least one positive size in sizes or sizes_bytes".to_string(),
        ));
    }
    sizes.sort_unstable_by(|left, right| right.cmp(left));
    Ok(sizes)
}

fn provider_limit_probe_chunk_sizes(
    input: &ProviderLimitProbeInput,
    capabilities: &blob_core::BackendCapabilities,
) -> Result<Vec<u64>, BlobError> {
    let requested_chunk = match (input.chunk_size.as_deref(), input.chunk_size_bytes) {
        (Some(raw), _) if !raw.trim().is_empty() => {
            Some(parse_byte_size_limit(raw).map_err(|error| {
                BlobError::Configuration(format!("invalid limit probe chunk_size '{raw}': {error}"))
            })?)
        }
        (_, Some(value)) if value > 0 => Some(value),
        _ => None,
    };
    let capability_chunk = capabilities
        .upload_part_size_bytes
        .filter(|value| *value > 0);
    let max_chunk = PROVIDER_LIMIT_PROBE_MAX_STREAM_CHUNK_BYTES.max(1);
    let mut current = requested_chunk
        .into_iter()
        .chain(capability_chunk)
        .max()
        .unwrap_or(PROVIDER_LIMIT_PROBE_DEFAULT_CHUNK_SIZE_BYTES)
        .clamp(1, max_chunk);
    let min_chunk = current
        .min(PROVIDER_LIMIT_PROBE_MIN_CHUNK_SIZE_BYTES)
        .max(1);
    let mut sizes = Vec::new();
    loop {
        sizes.push(current);
        if current <= min_chunk {
            break;
        }
        let next = (current / 2).max(min_chunk);
        if next == current {
            break;
        }
        current = next;
    }
    for extra in [requested_chunk, capability_chunk] {
        if let Some(extra) = extra {
            sizes.push(extra.clamp(1, max_chunk));
        }
    }
    sizes.sort_unstable_by(|left, right| right.cmp(left));
    sizes.dedup();
    Ok(sizes)
}

fn zero_probe_body(size: u64, chunk_size: u64) -> ObjectBody {
    let chunk_size = chunk_size.max(1).min(usize::MAX as u64) as usize;
    let template = Bytes::from(vec![0u8; chunk_size]);
    ObjectBody::from_stream(stream::try_unfold(size, move |remaining| {
        let template = template.clone();
        async move {
            if remaining == 0 {
                return Ok(None);
            }
            let next_len = remaining.min(chunk_size as u64) as usize;
            Ok(Some((
                template.slice(0..next_len),
                remaining.saturating_sub(next_len as u64),
            )))
        }
    }))
}

fn provider_limit_probe_read_progress_interval(input: &ProviderLimitProbeInput) -> Duration {
    Duration::from_millis(
        input
            .read_progress_interval_ms
            .unwrap_or(PROVIDER_LIMIT_PROBE_DEFAULT_READ_PROGRESS_INTERVAL_MS)
            .clamp(250, 60_000),
    )
}

fn provider_limit_probe_read_total_timeout(size: u64, input: &ProviderLimitProbeInput) -> Duration {
    let timeout_ms = if let Some(timeout_ms) = input.read_total_timeout_ms {
        timeout_ms.clamp(
            1_000,
            PROVIDER_LIMIT_PROBE_MAX_READ_TOTAL_TIMEOUT_SECS * 1_000,
        )
    } else {
        let size_floor_secs = (size
            .saturating_add(PROVIDER_LIMIT_PROBE_MIN_ASSUMED_READ_BYTES_PER_SEC - 1)
            / PROVIDER_LIMIT_PROBE_MIN_ASSUMED_READ_BYTES_PER_SEC)
            .saturating_add(PROVIDER_LIMIT_PROBE_READ_TIMEOUT_OVERHEAD_SECS);
        PROVIDER_LIMIT_PROBE_DEFAULT_READ_TOTAL_TIMEOUT_SECS
            .max(size_floor_secs)
            .min(PROVIDER_LIMIT_PROBE_MAX_READ_TOTAL_TIMEOUT_SECS)
            .saturating_mul(1_000)
    };
    Duration::from_millis(timeout_ms)
}

fn provider_limit_probe_read_progress_snapshot(
    read_bytes: u64,
    started_at_unix_ms: u64,
    first_progress_latency_ms: &AtomicU64,
) -> ProviderLimitProbeReadProgress {
    let elapsed_ms = current_unix_ms().saturating_sub(started_at_unix_ms).max(1);
    let first_response_latency_ms = match first_progress_latency_ms.load(Ordering::SeqCst) {
        0 => None,
        value => Some(value),
    };
    ProviderLimitProbeReadProgress {
        read_bytes,
        elapsed_ms,
        first_response_latency_ms,
        bytes_per_sec: provider_io_throughput_bytes_per_sec(read_bytes, elapsed_ms),
    }
}

async fn drain_probe_body_with_first_progress<F>(
    body: ObjectBody,
    started_at_unix_ms: u64,
    total_timeout: Duration,
    progress_interval: Duration,
    mut on_progress: F,
) -> Result<(u64, Option<u64>), ProviderLimitProbeReadDrainError>
where
    F: FnMut(ProviderLimitProbeReadProgress),
{
    let first_progress_latency_ms = Arc::new(AtomicU64::new(0));
    let observer = StreamFirstProgressObserver::new({
        let first_progress_latency_ms = Arc::clone(&first_progress_latency_ms);
        move || {
            first_progress_latency_ms.store(
                current_unix_ms().saturating_sub(started_at_unix_ms).max(1),
                Ordering::SeqCst,
            );
        }
    });
    let mut stream = body.observe_first_progress(observer).into_stream();
    let deadline = Instant::now() + total_timeout;
    let mut read_bytes = 0u64;
    let mut last_progress_elapsed_ms = 0u64;
    while let Some(chunk) = timeout_at(deadline, stream.next()).await.map_err(|_| {
        let progress = provider_limit_probe_read_progress_snapshot(
            read_bytes,
            started_at_unix_ms,
            &first_progress_latency_ms,
        );
        ProviderLimitProbeReadDrainError {
            error: BlobError::Upstream(format!(
                "read-back exceeded total timeout of {}s after reading {} bytes",
                total_timeout.as_secs(),
                progress.read_bytes
            )),
            read_bytes: progress.read_bytes,
            elapsed_ms: progress.elapsed_ms,
            first_response_latency_ms: progress.first_response_latency_ms,
            bytes_per_sec: progress.bytes_per_sec,
        }
    })? {
        let chunk = chunk.map_err(|error| {
            let progress = provider_limit_probe_read_progress_snapshot(
                read_bytes,
                started_at_unix_ms,
                &first_progress_latency_ms,
            );
            ProviderLimitProbeReadDrainError {
                error,
                read_bytes: progress.read_bytes,
                elapsed_ms: progress.elapsed_ms,
                first_response_latency_ms: progress.first_response_latency_ms,
                bytes_per_sec: progress.bytes_per_sec,
            }
        })?;
        read_bytes = read_bytes.saturating_add(chunk.len() as u64);
        let progress = provider_limit_probe_read_progress_snapshot(
            read_bytes,
            started_at_unix_ms,
            &first_progress_latency_ms,
        );
        if progress.elapsed_ms.saturating_sub(last_progress_elapsed_ms)
            >= progress_interval.as_millis() as u64
        {
            on_progress(progress);
            last_progress_elapsed_ms = progress.elapsed_ms;
        }
    }
    let first_progress_latency_ms = match first_progress_latency_ms.load(Ordering::SeqCst) {
        0 => None,
        value => Some(value),
    };
    Ok((read_bytes, first_progress_latency_ms))
}

fn env_u64(key: &str, default: u64) -> u64 {
    env::var(key)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(default)
}

fn env_byte_size_limit(key: &str) -> Result<Option<u64>, BlobError> {
    env_opt(key)
        .map(|value| {
            parse_byte_size_limit(&value)
                .map_err(|error| BlobError::Configuration(format!("invalid {key}: {error}")))
        })
        .transpose()
}

fn env_usize(key: &str, default: usize) -> usize {
    env::var(key)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(default)
}

async fn index(State(state): State<AppState>) -> Json<IndexPayload> {
    let snapshot = state.replication.snapshot();
    let topology = runtime_topology(&state);
    let backend_name = backend_for_provider(&state, topology.primary_provider)
        .map(|backend| backend.name())
        .unwrap_or("unknown");

    Json(IndexPayload {
        service: "carrier-cloud-blob-gateway",
        provenance: release_provenance_payload(),
        backend: backend_name,
        primary_provider: topology.primary_provider_name(),
        sync_targets: topology.sync_target_names(),
        fallback_read_order: topology.fallback_read_order_names(),
        replication: ReplicationQueueSummary {
            pending_jobs: snapshot.pending_count,
            recent_jobs: snapshot.recent_count,
        },
        endpoints: vec![
            "/",
            "/{bucket}",
            "/{bucket}/{key}",
            "/healthz",
            "/__ccbg",
            "/__ccbg/providers",
            "/__ccbg/replication",
            "/v1/containers",
            "/v1/objects",
        ],
    })
}

async fn list_provider_health(
    State(state): State<AppState>,
) -> Result<Json<Vec<BackendPayload>>, ApiError> {
    Ok(Json(provider_health_payloads(&state).await?))
}

async fn replication_snapshot(
    State(state): State<AppState>,
) -> Result<Json<ReplicationStatePayload>, ApiError> {
    Ok(Json(replication_state_payload(&state)?))
}

async fn healthz(
    State(state): State<AppState>,
) -> Result<Json<blob_core::ServiceHealth>, ApiError> {
    let (_, backend) = current_primary_backend(&state)?;
    Ok(Json(backend.health().await?))
}

#[derive(Debug, Serialize)]
struct ExtendedHealthPayload {
    status: &'static str,
    ready: bool,
    checked_at_unix_ms: u64,
    runtime: RuntimeStatusPayload,
    monitoring: MonitoringSummaryPayload,
    alerts: Vec<AdminAlertPayload>,
}

async fn metrics_healthz(
    State(state): State<AppState>,
) -> Result<Json<ExtendedHealthPayload>, ApiError> {
    let replication_state = replication_state_payload(&state)?;
    let provider_health = provider_health_payloads(&state).await?;
    let onedrive_auth = read_onedrive_auth_status(&state);
    let alerts = build_admin_alerts(&state, &provider_health, &replication_state, &onedrive_auth);
    let object_action_history = control_plane_snapshot(&state).object_action_history;
    let monitoring = monitoring_summary_payload(
        &provider_health,
        &replication_state,
        &object_action_history,
        &alerts,
    );
    let ready = provider_health.iter().all(|provider| {
        provider.role != "primary"
            || !matches!(provider.health.status, blob_core::HealthStatus::Unavailable)
    });

    Ok(Json(ExtendedHealthPayload {
        status: if ready { "ok" } else { "degraded" },
        ready,
        checked_at_unix_ms: current_unix_ms(),
        runtime: runtime_status_payload(&state),
        monitoring,
        alerts,
    }))
}

async fn metrics_readyz(State(state): State<AppState>) -> Result<StatusCode, ApiError> {
    let provider_health = provider_health_payloads(&state).await?;
    let primary_ready = provider_health.iter().all(|provider| {
        provider.role != "primary"
            || !matches!(provider.health.status, blob_core::HealthStatus::Unavailable)
    });

    Ok(if primary_ready {
        StatusCode::OK
    } else {
        StatusCode::SERVICE_UNAVAILABLE
    })
}

fn prometheus_label_value(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('\n', "\\n")
        .replace('"', "\\\"")
}

async fn metrics_prometheus(State(state): State<AppState>) -> Result<Response, ApiError> {
    let runtime = runtime_status_payload(&state);
    let replication_state = replication_state_payload(&state)?;
    let provider_health = provider_health_payloads(&state).await?;
    let onedrive_auth = read_onedrive_auth_status(&state);
    let alerts = build_admin_alerts(&state, &provider_health, &replication_state, &onedrive_auth);
    let object_action_history = control_plane_snapshot(&state).object_action_history;
    let monitoring = monitoring_summary_payload(
        &provider_health,
        &replication_state,
        &object_action_history,
        &alerts,
    );
    let data_plane_transfer = snapshot_data_plane_transfer(&state);
    let now_unix_ms = current_unix_ms();
    let oldest_pending_job_age_ms = oldest_job_age_ms(
        now_unix_ms,
        replication_state.in_memory.pending_jobs.iter(),
        |job| matches!(job.status, ReplicationStatus::Pending),
    )
    .unwrap_or(0);
    let oldest_retry_scheduled_job_age_ms = oldest_job_age_ms(
        now_unix_ms,
        replication_state.in_memory.pending_jobs.iter(),
        |job| matches!(job.status, ReplicationStatus::RetryScheduled),
    )
    .unwrap_or(0);
    let oldest_latest_failed_object_age_ms = oldest_job_age_ms(
        now_unix_ms,
        replication_state.latest_failed_jobs.iter(),
        |_| true,
    )
    .unwrap_or(0);
    let open_dead_letter_target_counts = state
        .metadata_store
        .open_dead_letter_target_counts()
        .unwrap_or_default();
    let open_dead_letter_count = open_dead_letter_target_counts.values().sum::<usize>();

    let mut lines = Vec::new();
    lines.push("# HELP ccbg_up Carrier Cloud Blob Gateway process health indicator.".to_string());
    lines.push("# TYPE ccbg_up gauge".to_string());
    lines.push("ccbg_up 1".to_string());
    lines.push(
        "# HELP ccbg_release_info Static release provenance for this gateway binary.".to_string(),
    );
    lines.push("# TYPE ccbg_release_info gauge".to_string());
    lines.push(format!(
        "ccbg_release_info{{version=\"{}\",fingerprint=\"{}\",license=\"{}\"}} 1",
        env!("CARGO_PKG_VERSION"),
        release_fingerprint(),
        CCBG_LICENSE_ID
    ));
    lines.push("# HELP ccbg_uptime_ms Gateway uptime in milliseconds.".to_string());
    lines.push("# TYPE ccbg_uptime_ms gauge".to_string());
    lines.push(format!("ccbg_uptime_ms {}", runtime.uptime_ms));
    lines.push(
        "# HELP ccbg_process_memory_bytes Gateway process memory usage in bytes.".to_string(),
    );
    lines.push("# TYPE ccbg_process_memory_bytes gauge".to_string());
    if let Some(value) = runtime.process_memory.rss_bytes {
        lines.push(format!(
            "ccbg_process_memory_bytes{{kind=\"rss\"}} {}",
            value
        ));
    }
    if let Some(value) = runtime.process_memory.virtual_bytes {
        lines.push(format!(
            "ccbg_process_memory_bytes{{kind=\"virtual\"}} {}",
            value
        ));
    }
    lines.push("# HELP ccbg_admin_alerts_open Current open alert count.".to_string());
    lines.push("# TYPE ccbg_admin_alerts_open gauge".to_string());
    lines.push(format!(
        "ccbg_admin_alerts_open {}",
        monitoring.open_alert_count
    ));
    lines.push(
        "# HELP ccbg_data_plane_concurrency_configured Configured max in-flight data-plane requests."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_concurrency_configured gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_concurrency_configured {}",
        runtime.data_plane_max_in_flight
    ));
    lines.push(
        "# HELP ccbg_data_plane_concurrency_available Currently available data-plane permits."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_concurrency_available gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_concurrency_available {}",
        state.data_plane_concurrency.semaphore.available_permits()
    ));
    let rate_limiter = snapshot_data_plane_rate_limiter(&state, current_unix_ms());
    lines.push(
        "# HELP ccbg_data_plane_rate_limit_configured Configured max data-plane requests per second (0 means disabled)."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_rate_limit_configured gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_rate_limit_configured {}",
        runtime.data_plane_max_requests_per_second
    ));
    lines.push(
        "# HELP ccbg_data_plane_rate_limit_current_second Data-plane requests observed in the current one-second window."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_rate_limit_current_second gauge".to_string());
    lines.push(format!(
        "ccbg_data_plane_rate_limit_current_second {}",
        rate_limiter.requests_in_window
    ));
    lines.push(
        "# HELP ccbg_data_plane_requests_total Total data-plane requests observed by the gateway."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_requests_total counter".to_string());
    lines.push(format!(
        "ccbg_data_plane_requests_total {}",
        data_plane_transfer.requests_total
    ));
    lines.push(
        "# HELP ccbg_data_plane_fallback_reads_total Total read requests served through fallback placement."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_fallback_reads_total counter".to_string());
    lines.push(format!(
        "ccbg_data_plane_fallback_reads_total {}",
        data_plane_transfer.fallback_reads_total
    ));
    lines.push(
        "# HELP ccbg_data_plane_bytes_total Total data-plane bytes transferred by direction."
            .to_string(),
    );
    lines.push("# TYPE ccbg_data_plane_bytes_total counter".to_string());
    lines.push(format!(
        "ccbg_data_plane_bytes_total{{direction=\"in\"}} {}",
        data_plane_transfer.bytes_in_total
    ));
    lines.push(format!(
        "ccbg_data_plane_bytes_total{{direction=\"out\"}} {}",
        data_plane_transfer.bytes_out_total
    ));
    lines.push("# HELP ccbg_provider_health Provider health status by role and provider (healthy=2,degraded=1,unavailable=0).".to_string());
    lines.push("# TYPE ccbg_provider_health gauge".to_string());
    for provider in &provider_health {
        let value = match provider.health.status {
            blob_core::HealthStatus::Healthy => 2,
            blob_core::HealthStatus::Degraded => 1,
            blob_core::HealthStatus::Unavailable => 0,
        };
        lines.push(format!(
            "ccbg_provider_health{{provider=\"{}\",role=\"{}\"}} {}",
            provider.provider, provider.role, value
        ));
    }
    lines.push(
        "# HELP ccbg_provider_io_operations_total Provider I/O operation counters by provider, operation, and outcome."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_operations_total counter".to_string());
    lines.push(
        "# HELP ccbg_provider_io_latency_ms Provider I/O observed latency in milliseconds."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_latency_ms gauge".to_string());
    lines.push(
        "# HELP ccbg_provider_io_bytes_per_second Provider I/O observed bytes per second."
            .to_string(),
    );
    lines.push("# TYPE ccbg_provider_io_bytes_per_second gauge".to_string());
    for provider in &provider_health {
        for (operation_name, operation) in
            [("read", &provider.io.read), ("write", &provider.io.write)]
        {
            lines.push(format!(
                "ccbg_provider_io_operations_total{{provider=\"{}\",operation=\"{}\",outcome=\"success\"}} {}",
                provider.provider, operation_name, operation.success_count
            ));
            lines.push(format!(
                "ccbg_provider_io_operations_total{{provider=\"{}\",operation=\"{}\",outcome=\"failure\"}} {}",
                provider.provider, operation_name, operation.failure_count
            ));
            if let Some(value) = operation.first_success_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"first_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.first_response_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"first_response\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_success_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"last_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_response_latency_ms {
                lines.push(format!(
                    "ccbg_provider_io_latency_ms{{provider=\"{}\",operation=\"{}\",kind=\"last_response\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_success_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"last_success\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.rolling_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"rolling\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
            if let Some(value) = operation.last_large_success_bytes_per_sec {
                lines.push(format!(
                    "ccbg_provider_io_bytes_per_second{{provider=\"{}\",operation=\"{}\",kind=\"last_large\"}} {}",
                    provider.provider, operation_name, value
                ));
            }
        }
    }
    lines.push("# HELP ccbg_replication_jobs Replication jobs by persisted status.".to_string());
    lines.push("# TYPE ccbg_replication_jobs gauge".to_string());
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"pending\"}} {}",
        monitoring.replication.pending_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"retry_scheduled\"}} {}",
        monitoring.replication.retry_scheduled_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"failed\"}} {}",
        monitoring.replication.failed_jobs
    ));
    lines.push(format!(
        "ccbg_replication_jobs{{status=\"completed\"}} {}",
        monitoring.replication.completed_jobs
    ));
    lines.push(
        "# HELP ccbg_replication_oldest_job_age_ms Oldest observed replication job age by status in milliseconds."
            .to_string(),
    );
    lines.push("# TYPE ccbg_replication_oldest_job_age_ms gauge".to_string());
    lines.push(format!(
        "ccbg_replication_oldest_job_age_ms{{status=\"pending\"}} {}",
        oldest_pending_job_age_ms
    ));
    lines.push(format!(
        "ccbg_replication_oldest_job_age_ms{{status=\"retry_scheduled\"}} {}",
        oldest_retry_scheduled_job_age_ms
    ));
    lines.push(format!(
        "ccbg_replication_oldest_job_age_ms{{status=\"latest_failed_object\"}} {}",
        oldest_latest_failed_object_age_ms
    ));
    lines.push(
        "# HELP ccbg_replication_dead_letter_jobs Open replication dead-letter jobs by target."
            .to_string(),
    );
    lines.push("# TYPE ccbg_replication_dead_letter_jobs gauge".to_string());
    lines.push(format!(
        "ccbg_replication_dead_letter_jobs{{target=\"all\"}} {}",
        open_dead_letter_count
    ));
    for (target, count) in open_dead_letter_target_counts {
        lines.push(format!(
            "ccbg_replication_dead_letter_jobs{{target=\"{}\"}} {}",
            prometheus_label_value(&target),
            count
        ));
    }
    lines.push("# HELP ccbg_object_action_entries Object action history counts.".to_string());
    lines.push("# TYPE ccbg_object_action_entries gauge".to_string());
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"total\"}} {}",
        monitoring.object_actions.total_entries
    ));
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"successful\"}} {}",
        monitoring.object_actions.successful_entries
    ));
    lines.push(format!(
        "ccbg_object_action_entries{{outcome=\"failed\"}} {}",
        monitoring.object_actions.failed_entries
    ));
    lines.push(
        "# HELP ccbg_object_action_unique_operators Unique operators in retained action history."
            .to_string(),
    );
    lines.push("# TYPE ccbg_object_action_unique_operators gauge".to_string());
    lines.push(format!(
        "ccbg_object_action_unique_operators {}",
        monitoring.object_actions.unique_operators
    ));
    lines.push(
        "# HELP ccbg_replication_target_jobs Replication job counters per target.".to_string(),
    );
    lines.push("# TYPE ccbg_replication_target_jobs gauge".to_string());
    for target in &replication_state.target_statuses {
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"queued\"}} {}",
            target.provider, target.queued_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"pending\"}} {}",
            target.provider, target.pending_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"retry_scheduled\"}} {}",
            target.provider, target.retry_scheduled_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"completed\"}} {}",
            target.provider, target.completed_count
        ));
        lines.push(format!(
            "ccbg_replication_target_jobs{{target=\"{}\",status=\"failed\"}} {}",
            target.provider, target.failed_count
        ));
    }

    Ok((
        [(CONTENT_TYPE, "text/plain; version=0.0.4; charset=utf-8")],
        lines.join("\n") + "\n",
    )
        .into_response())
}

async fn list_containers(
    State(state): State<AppState>,
) -> Result<Json<Vec<blob_core::ContainerInfo>>, DataPlaneApiError> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())
        .map_err(DataPlaneApiError::from_s3_error)?;
    let _permit =
        try_acquire_data_plane_permit(&state).map_err(DataPlaneApiError::from_s3_error)?;
    let read = list_containers_with_fallback(&state).await?;
    record_data_plane_fallback_read(&state, read.source);
    let payload = read.value;
    record_serialized_json_bytes(&state, &payload);
    Ok(Json(payload))
}

async fn list_objects(
    State(state): State<AppState>,
    Query(query): Query<ObjectsQuery>,
) -> Result<Json<Vec<blob_core::ObjectInfo>>, DataPlaneApiError> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())
        .map_err(DataPlaneApiError::from_s3_error)?;
    let _permit =
        try_acquire_data_plane_permit(&state).map_err(DataPlaneApiError::from_s3_error)?;
    let (_, backend) = current_primary_backend(&state)?;
    let request = ListObjectsRequest {
        container: query.container,
        prefix: query.prefix,
        limit: query.limit,
    };

    let payload = backend.list_objects(request).await?;
    record_serialized_json_bytes(&state, &payload);
    Ok(Json(payload))
}

async fn list_buckets(
    State(state): State<AppState>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    if let Some(bucket) = bucket_from_virtual_host(&headers) {
        let query = parse_list_objects_v2_query(uri.query());
        return list_objects_v2_with_bucket(state, bucket, query, method, uri, headers).await;
    }

    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(&application, S3ActionKind::ListBuckets, None, None)?;

    let read = list_containers_with_fallback(&state)
        .await
        .map_err(map_backend_error_to_s3)?;
    record_data_plane_fallback_read(&state, read.source);
    let containers = filter_containers_for_application(read.value, &application);

    let mut body = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
    body.push_str(&format!(
        "<ListAllMyBucketsResult xmlns=\"{S3_NS}\"><Owner><ID>ccbg</ID><DisplayName>ccbg</DisplayName></Owner><Buckets>"
    ));

    for bucket in containers {
        body.push_str(&format!(
            "<Bucket><Name>{}</Name><CreationDate>{}</CreationDate></Bucket>",
            xml_escape(&bucket.name),
            DEFAULT_TIMESTAMP
        ));
    }

    body.push_str("</Buckets></ListAllMyBucketsResult>");
    record_data_plane_bytes_out(&state, body.len() as u64);
    let mut response = xml_response(StatusCode::OK, body);
    apply_read_source_headers(response.headers_mut(), read.source);
    Ok(response)
}

async fn head_bucket(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(&application, S3ActionKind::ListObjects, Some(&bucket), None)?;

    let read_backend = resolve_bucket_read_backend(&state, &bucket)
        .await
        .map_err(|error| map_bucket_error(error, &bucket))?;
    record_data_plane_fallback_read(&state, read_backend.source);

    let mut response = StatusCode::OK.into_response();
    response.headers_mut().insert(
        "x-amz-bucket-region",
        HeaderValue::from_str(&state.config.s3_region)
            .expect("configured region should be a valid header value"),
    );
    apply_read_source_headers(response.headers_mut(), read_backend.source);
    Ok(response)
}

