fn restore_copy_destination_metadata(
    state: &AppState,
    bucket: &str,
    key: &str,
    previous_placement: Option<(ProviderId, u64)>,
    previous_logical: Option<LogicalObjectRecord>,
    previous_protection_plan: Option<PersistedObjectProtectionPlan>,
) {
    restore_previous_object_write_state(state, bucket, key, previous_placement, previous_logical);
    match previous_protection_plan {
        Some(previous) => {
            let _ = persist_object_protection_plan(
                state,
                bucket,
                key,
                &previous.sync_targets,
                &previous.fallback_read_order,
                previous.updated_at_unix_ms,
            );
        }
        None => {
            let _ = delete_object_protection_plan(state, bucket, key);
        }
    }
}

fn build_put_encryption_plan(
    state: &AppState,
    bucket: &str,
    key: &str,
    plaintext_size: u64,
    content_type: Option<String>,
    application: &S3ApplicationIdentity,
) -> Result<Option<PutEncryptionPlan>, S3Error> {
    let Some(profile) = effective_encryption_profile_for_write(
        state,
        application,
        bucket,
        key,
        content_type.as_deref(),
    )?
    else {
        return Ok(None);
    };
    let key_encryption_key =
        load_profile_encryption_key_material(state, &profile).map_err(map_backend_error_to_s3)?;
    let request = CryptoEncryptRequest {
        profile_id: profile.id.clone(),
        key_id: profile.key_id.clone(),
        algorithm_preference: profile.algorithm_preference.to_crypto(),
        chunk_plaintext_bytes: profile.chunk_plaintext_bytes,
        plaintext_size,
        logical_content_type: content_type,
    };
    let metadata = request
        .planned_metadata()
        .map_err(|error| S3Error::internal_error(error.to_string()))?;
    let logical_record = LogicalObjectRecord {
        bucket: bucket.to_string(),
        key: key.to_string(),
        etag: None,
        application_id: Some(application.application_id.clone()),
        encrypted: true,
        encryption_profile_id: Some(profile.id.clone()),
        algorithm: Some(metadata.algorithm.as_str().to_string()),
        key_id: Some(profile.key_id.clone()),
        key_source_kind: Some(profile.key_source_kind.as_str().to_string()),
        key_source_ref: Some(profile.key_source_ref.clone()),
        chunk_plaintext_bytes: Some(metadata.chunk_plaintext_bytes),
        plaintext_size: metadata.plaintext_size,
        stored_size: metadata.stored_size,
        logical_content_type: metadata.logical_content_type.clone(),
        updated_at_unix_ms: current_unix_ms(),
    };
    Ok(Some(PutEncryptionPlan {
        request,
        key_encryption_key,
        logical_record,
    }))
}

async fn verify_put_object_visibility(
    backend: &DynBackend,
    provider: ProviderId,
    bucket: &str,
    key: &str,
    expected_size: u64,
) -> Result<u32, BlobError> {
    const PUT_OBJECT_VERIFY_MAX_ATTEMPTS: u32 = 3;
    const PUT_OBJECT_VERIFY_RETRY_DELAY_MS: u64 = 150;

    let mut last_error = None;
    for attempt in 1..=PUT_OBJECT_VERIFY_MAX_ATTEMPTS {
        match backend.head_object(bucket, key).await {
            Ok(object) => {
                if object.size == expected_size {
                    return Ok(attempt);
                }
                last_error = Some(format!(
                    "head returned size {} instead of {}",
                    object.size, expected_size
                ));
            }
            Err(error) => {
                last_error = Some(error.to_string());
            }
        }

        if attempt < PUT_OBJECT_VERIFY_MAX_ATTEMPTS {
            sleep(Duration::from_millis(PUT_OBJECT_VERIFY_RETRY_DELAY_MS)).await;
        }
    }

    Err(BlobError::Upstream(format!(
        "provider {} reported put success for {}/{} but post-write head verification failed after {} attempts: {}",
        provider.as_str(),
        bucket,
        key,
        PUT_OBJECT_VERIFY_MAX_ATTEMPTS,
        last_error.unwrap_or_else(|| "no verification result was captured".to_string())
    )))
}

async fn maybe_cleanup_failed_put_object(
    backend: &DynBackend,
    home_provider: ProviderId,
    bucket: &str,
    key: &str,
    previous_placement: Option<(ProviderId, u64)>,
    failure_context: &'static str,
) {
    if previous_placement
        .as_ref()
        .is_some_and(|(provider, _)| *provider == home_provider)
    {
        warn!(
            bucket = %bucket,
            key = %key,
            provider = home_provider.as_str(),
            context = failure_context,
            "skipping failed-put cleanup because the previous home object used the same provider"
        );
        return;
    }

    if let Err(cleanup_error) = backend.delete_object(bucket, key).await {
        warn!(
            bucket = %bucket,
            key = %key,
            provider = home_provider.as_str(),
            context = failure_context,
            error = %cleanup_error,
            "failed to delete uploaded object after put rollback"
        );
    }
}

async fn rollback_put_after_failure_with_note(
    state: &AppState,
    backend: &DynBackend,
    home_provider: ProviderId,
    bucket: &str,
    key: &str,
    previous_placement_record: Option<ObjectPlacementRecord>,
    previous_placement: Option<(ProviderId, u64)>,
    previous_logical: Option<LogicalObjectRecord>,
    previous_protection_plan_record: Option<ObjectProtectionPlanRecord>,
    failure_context: &'static str,
) -> String {
    let metadata_note = match ensure_previous_object_metadata_state(
        state,
        bucket,
        key,
        previous_placement_record,
        previous_logical,
        previous_protection_plan_record,
    ) {
        Ok(()) => "metadata rollback succeeded".to_string(),
        Err(error) => format!("metadata rollback failed: {error}"),
    };
    maybe_cleanup_failed_put_object(
        backend,
        home_provider,
        bucket,
        key,
        previous_placement,
        failure_context,
    )
    .await;
    format!("remote put already succeeded; {metadata_note}")
}

async fn mark_gateway_write_ahead_log_rolled_back(
    state: &AppState,
    context: &GatewayWriteAheadLogContext,
) -> Result<(), BlobError> {
    let mut record = context.record.clone();
    record.phase = GatewayWriteAheadLogPhase::Committed;
    record.committed_at_unix_ms = Some(current_unix_ms());
    let previous_home_provider = record
        .previous_placement
        .as_ref()
        .map(|placement| {
            ProviderId::parse(&placement.provider).map_err(|error| {
                BlobError::Configuration(format!(
                    "failed to parse previous WAL home provider {}: {error}",
                    placement.provider
                ))
            })
        })
        .transpose()?;
    if let Some(home_provider) = previous_home_provider {
        record.operation = GatewayWriteAheadLogOperation::MetadataSync;
        record.home_provider = home_provider;
        record.logical_record = record.previous_logical_record.clone();
        if let Some(previous_plan) = record.previous_protection_plan.as_ref() {
            let sync_targets = parse_provider_csv(&previous_plan.sync_targets_csv)?;
            let fallback_read_order = sanitize_fallback_order_for_sync_targets(
                &sync_targets,
                &parse_provider_csv(&previous_plan.fallback_read_order_csv)?,
            );
            record.sync_targets = sync_targets;
            record.fallback_read_order = fallback_read_order;
        } else {
            record.sync_targets = Vec::new();
            record.fallback_read_order = Vec::new();
        }
    } else {
        record.operation = GatewayWriteAheadLogOperation::Delete;
        record.logical_record = None;
        record.sync_targets = Vec::new();
        record.fallback_read_order = Vec::new();
    }
    persist_gateway_write_ahead_log_record(state, context.remote_provider, &record).await
}

async fn mark_gateway_write_ahead_log_rolled_back_or_warn(
    state: &AppState,
    context: Option<&GatewayWriteAheadLogContext>,
    bucket: &str,
    key: &str,
    action: &str,
) {
    if let Some(context) = context {
        if let Err(error) = mark_gateway_write_ahead_log_rolled_back(state, context).await {
            warn!(
                bucket = %bucket,
                key = %key,
                action = %action,
                remote_provider = context.remote_provider.as_str(),
                error = %error,
                "failed to persist rolled-back gateway write-ahead log state"
            );
        }
    }
}

async fn execute_put_upload(
    state: &AppState,
    bucket: String,
    key: String,
    application: S3ApplicationIdentity,
    plaintext_size: u64,
    content_type: Option<String>,
    request_body: PreparedPutRequestBody,
    write_path: ProviderWritePathKind,
) -> Result<Response, S3Error> {
    let encryption_plan = build_put_encryption_plan(
        state,
        &bucket,
        &key,
        plaintext_size,
        content_type.clone(),
        &application,
    )?;
    let stored_size = encryption_plan
        .as_ref()
        .map(|plan| plan.logical_record.stored_size)
        .unwrap_or(plaintext_size);
    let stored_content_type = encryption_plan
        .as_ref()
        .and_then(PutEncryptionPlan::stored_content_type)
        .or(content_type.clone());
    let policy_content_type = encryption_plan
        .as_ref()
        .and_then(PutEncryptionPlan::policy_content_type)
        .or(content_type.clone());
    let plaintext_logical_record = build_plaintext_logical_record(
        &bucket,
        &key,
        plaintext_size,
        content_type.clone(),
        &application,
    );

    let (home_provider, home_backend) = select_home_write_provider(
        state,
        &bucket,
        &key,
        Some(&application),
        policy_content_type.as_deref(),
        stored_size,
    )
    .await
    .map_err(|error| S3Error::insufficient_storage(error.to_string()))?;
    if !home_backend.capabilities().streaming_put {
        ensure_object_within_in_memory_limit(&state.config, stored_size)?;
    }
    let desired_logical_record = encryption_plan
        .as_ref()
        .map(|plan| plan.logical_record.clone())
        .unwrap_or_else(|| plaintext_logical_record.clone());
    let effective_topology = effective_topology_for_replication_put(
        state,
        Some(&application),
        &bucket,
        &key,
        Some(home_provider),
        stored_size,
        policy_content_type.as_deref(),
    )
    .await
    .map_err(map_backend_error_to_s3)?;
    let previous_placement_record = state
        .metadata_store
        .object_placement(&bucket, &key)
        .map_err(|error| map_backend_error_to_s3(BlobError::Upstream(error.to_string())))?;
    let previous_placement =
        placed_home_provider_record(state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let previous_logical =
        load_logical_object_record(state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let previous_protection_plan_record = state
        .metadata_store
        .object_protection_plan(&bucket, &key)
        .map_err(|error| map_backend_error_to_s3(BlobError::Upstream(error.to_string())))?;
    let previous_protection_plan =
        load_object_protection_plan(state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let gateway_write_ahead_log = maybe_prepare_gateway_write_ahead_log(
        state,
        &application,
        GatewayWriteAheadLogOperation::Put,
        &bucket,
        &key,
        home_provider,
        Some(&desired_logical_record),
        &effective_topology.sync_targets,
        &effective_topology.fallback_read_order,
        previous_placement_record.clone(),
        previous_logical.clone(),
        previous_protection_plan_record.clone(),
    )
    .await
    .map_err(map_backend_error_to_s3)?;
    if let Err(error) = persist_object_home_provider(state, home_provider, &bucket, &key) {
        mark_gateway_write_ahead_log_rolled_back_or_warn(
            state,
            gateway_write_ahead_log.as_ref(),
            &bucket,
            &key,
            "persist home placement before put",
        )
        .await;
        return Err(map_backend_error_to_s3(error));
    }
    let logical_persist_result = persist_logical_object_record(state, &desired_logical_record);
    if let Err(error) = logical_persist_result {
        restore_previous_object_write_state(
            state,
            &bucket,
            &key,
            previous_placement,
            previous_logical,
        );
        mark_gateway_write_ahead_log_rolled_back_or_warn(
            state,
            gateway_write_ahead_log.as_ref(),
            &bucket,
            &key,
            "persist logical metadata before put",
        )
        .await;
        return Err(map_backend_error_to_s3(error));
    }

    let write_started_at = current_unix_ms();
    state
        .provider_resource_stats
        .record_write_path(home_provider.as_str(), write_path);
    let _write_operation = state
        .provider_resource_stats
        .start_operation(home_provider.as_str(), ProviderResourceOperationKind::Write);
    let (source_body, payload_validation, etag_override_source) =
        request_body.into_parts(state, home_provider.as_str());
    let upload_body = match encryption_plan.as_ref() {
        Some(plan) => {
            match encrypt_upload(source_body, plan.request.clone(), plan.key_encryption_key) {
                Ok(encrypted) => encrypted.body,
                Err(error) => {
                    restore_previous_object_write_state(
                        state,
                        &bucket,
                        &key,
                        previous_placement,
                        previous_logical.clone(),
                    );
                    mark_gateway_write_ahead_log_rolled_back_or_warn(
                        state,
                        gateway_write_ahead_log.as_ref(),
                        &bucket,
                        &key,
                        "build encrypted put body",
                    )
                    .await;
                    return Err(S3Error::internal_error(error.to_string()));
                }
            }
        }
        None => source_body,
    };
    let result = match home_backend
        .put_object(PutObjectRequest {
            container: bucket.clone(),
            key: key.clone(),
            body: upload_body,
            size: Some(stored_size),
            content_type: stored_content_type.clone(),
            preferred_upload_part_size_bytes: None,
        })
        .await
    {
        Ok(result) => result,
        Err(error) => {
            state.provider_io_stats.record_failure(
                home_provider.as_str(),
                ProviderIoOperationKind::Write,
                &error.to_string(),
            );
            restore_previous_object_write_state(
                state,
                &bucket,
                &key,
                previous_placement,
                previous_logical.clone(),
            );
            mark_gateway_write_ahead_log_rolled_back_or_warn(
                state,
                gateway_write_ahead_log.as_ref(),
                &bucket,
                &key,
                "write home object",
            )
            .await;
            return Err(map_backend_error_to_s3(error));
        }
    };
    if let Some(validation) = payload_validation {
        if let Err(error) = validation.ensure_matched() {
            state.provider_io_stats.record_failure(
                home_provider.as_str(),
                ProviderIoOperationKind::Write,
                &error.message,
            );
            restore_previous_object_write_state(
                state,
                &bucket,
                &key,
                previous_placement,
                previous_logical.clone(),
            );
            if let Err(cleanup_error) = home_backend.delete_object(&bucket, &key).await {
                warn!(
                    bucket = %bucket,
                    key = %key,
                    provider = home_provider.as_str(),
                    error = %cleanup_error,
                    "failed to delete uploaded object after request-body hash mismatch"
                );
            }
            mark_gateway_write_ahead_log_rolled_back_or_warn(
                state,
                gateway_write_ahead_log.as_ref(),
                &bucket,
                &key,
                "request-body hash mismatch after put",
            )
            .await;
            return Err(error);
        }
    }
    let effective_etag = etag_override_source
        .as_ref()
        .map(|source| source.resolved_etag())
        .transpose()?
        .or(result.etag.clone());
    let verification_attempts = match verify_put_object_visibility(
        &home_backend,
        home_provider,
        &bucket,
        &key,
        stored_size,
    )
    .await
    {
        Ok(attempts) => attempts,
        Err(error) => {
            state.provider_io_stats.record_failure(
                home_provider.as_str(),
                ProviderIoOperationKind::Write,
                &error.to_string(),
            );
            warn!(
                bucket = %bucket,
                key = %key,
                provider = home_provider.as_str(),
                error = %error,
                "put post-write head verification failed after provider returned success"
            );
            restore_previous_object_write_state(
                state,
                &bucket,
                &key,
                previous_placement,
                previous_logical.clone(),
            );
            maybe_cleanup_failed_put_object(
                &home_backend,
                home_provider,
                &bucket,
                &key,
                previous_placement,
                "post-write head verification failed",
            )
            .await;
            mark_gateway_write_ahead_log_rolled_back_or_warn(
                state,
                gateway_write_ahead_log.as_ref(),
                &bucket,
                &key,
                "post-write head verification failure",
            )
            .await;
            return Err(map_backend_error_to_s3(error));
        }
    };
    if verification_attempts > 1 {
        info!(
            bucket = %bucket,
            key = %key,
            provider = home_provider.as_str(),
            verification_attempts,
            "put post-write head verification recovered after retry"
        );
    }
    state.provider_io_stats.record_success_with_response(
        home_provider.as_str(),
        ProviderIoOperationKind::Write,
        current_unix_ms().saturating_sub(write_started_at),
        result.first_response_latency_ms,
        Some(stored_size),
    );

    if let Err(error) = persist_object_protection_plan(
        state,
        &bucket,
        &key,
        &effective_topology.sync_targets,
        &effective_topology.fallback_read_order,
        current_unix_ms(),
    ) {
        let rollback_note = rollback_put_after_failure_with_note(
            state,
            &home_backend,
            home_provider,
            &bucket,
            &key,
            previous_placement_record.clone(),
            previous_placement,
            previous_logical.clone(),
            previous_protection_plan_record.clone(),
            "persist object protection plan after put",
        )
        .await;
        return Err(map_backend_error_to_s3(BlobError::Upstream(format!(
            "put remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        ))));
    }
    let mut finalized_logical_record = desired_logical_record.clone();
    finalized_logical_record.etag = effective_etag.clone();
    if let Err(error) = maybe_inject_post_put_logical_persist_failure(&bucket, &key) {
        let rollback_note = rollback_put_after_failure_with_note(
            state,
            &home_backend,
            home_provider,
            &bucket,
            &key,
            previous_placement_record.clone(),
            previous_placement,
            previous_logical.clone(),
            previous_protection_plan_record.clone(),
            "persist logical metadata after put",
        )
        .await;
        return Err(map_backend_error_to_s3(BlobError::Upstream(format!(
            "put remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        ))));
    }
    if let Err(error) = persist_logical_object_record(state, &finalized_logical_record) {
        let rollback_note = rollback_put_after_failure_with_note(
            state,
            &home_backend,
            home_provider,
            &bucket,
            &key,
            previous_placement_record.clone(),
            previous_placement,
            previous_logical.clone(),
            previous_protection_plan_record.clone(),
            "persist logical metadata after put",
        )
        .await;
        return Err(map_backend_error_to_s3(BlobError::Upstream(format!(
            "put remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        ))));
    }
    let mut jobs = state.replication.enqueue_put(
        &effective_topology,
        Some(home_provider.as_str().to_string()),
        bucket.clone(),
        key.clone(),
        effective_etag.clone(),
        stored_size,
        stored_content_type.clone(),
    );
    let removed_sync_targets = removed_sync_targets_for_desired_topology(
        previous_protection_plan.as_ref(),
        &effective_topology,
    );
    if !removed_sync_targets.is_empty() {
        let delete_topology = TopologyPolicy {
            primary_provider: effective_topology.primary_provider,
            sync_targets: removed_sync_targets,
            fallback_read_order: Vec::new(),
            onedrive_enabled: effective_topology.onedrive_enabled,
            replication_mode: effective_topology.replication_mode,
        };
        jobs.extend(state.replication.enqueue_delete(
            &delete_topology,
            Some(home_provider.as_str().to_string()),
            bucket.clone(),
            key.clone(),
        ));
    }
    if let Err(error) = enqueue_put_object_replication_jobs(state, &bucket, &key, &jobs) {
        let rollback_note = rollback_put_after_failure_with_note(
            state,
            &home_backend,
            home_provider,
            &bucket,
            &key,
            previous_placement_record,
            previous_placement,
            previous_logical,
            previous_protection_plan_record,
            "persist replication jobs after put",
        )
        .await;
        return Err(S3Error::internal_error(format!(
            "put remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        )));
    }
    if !jobs.is_empty() {
        info!(
            bucket = %bucket,
            key = %key,
            queued_jobs = jobs.len(),
            "replication jobs enqueued after put"
        );
    }
    if let Some(context) = gateway_write_ahead_log.as_ref() {
        if let Err(error) = mark_gateway_write_ahead_log_committed(state, context).await {
            warn!(
                bucket = %bucket,
                key = %key,
                remote_provider = context.remote_provider.as_str(),
                error = %error,
                "failed to mark gateway write-ahead log as committed after put"
            );
        }
    }

    let mut response = StatusCode::OK.into_response();
    if let Some(etag) = effective_etag {
        response.headers_mut().insert(
            ETAG,
            HeaderValue::from_str(&quoted_etag(Some(&etag))).expect("etag should be valid"),
        );
    }
    Ok(response)
}

fn validate_decrypted_object_metadata(
    logical: &LogicalObjectRecord,
    metadata: &object_crypto::EncryptedObjectMetadata,
) -> Result<(), S3Error> {
    if !logical.encrypted {
        return Ok(());
    }
    if logical.plaintext_size != metadata.plaintext_size {
        return Err(S3Error::internal_error(format!(
            "logical metadata plaintext size {} does not match encrypted object header {} for {}/{}",
            logical.plaintext_size, metadata.plaintext_size, logical.bucket, logical.key
        )));
    }
    if logical.stored_size < metadata.plaintext_size {
        return Err(S3Error::internal_error(format!(
            "logical metadata stored size {} is smaller than plaintext size {} for {}/{}",
            logical.stored_size, metadata.plaintext_size, logical.bucket, logical.key
        )));
    }
    if logical.algorithm.as_deref() != Some(metadata.algorithm.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata algorithm {:?} does not match encrypted object header {} for {}/{}",
            logical.algorithm,
            metadata.algorithm.as_str(),
            logical.bucket,
            logical.key
        )));
    }
    if logical.key_id.as_deref() != Some(metadata.key_id.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata key_id {:?} does not match encrypted object header {} for {}/{}",
            logical.key_id, metadata.key_id, logical.bucket, logical.key
        )));
    }
    if logical.encryption_profile_id.as_deref() != Some(metadata.profile_id.as_str()) {
        return Err(S3Error::internal_error(format!(
            "logical metadata profile {:?} does not match encrypted object header {} for {}/{}",
            logical.encryption_profile_id, metadata.profile_id, logical.bucket, logical.key
        )));
    }
    if logical.chunk_plaintext_bytes != Some(metadata.chunk_plaintext_bytes) {
        return Err(S3Error::internal_error(format!(
            "logical metadata chunk size {:?} does not match encrypted object header {} for {}/{}",
            logical.chunk_plaintext_bytes,
            metadata.chunk_plaintext_bytes,
            logical.bucket,
            logical.key
        )));
    }
    if logical.logical_content_type.as_deref() != metadata.logical_content_type.as_deref() {
        return Err(S3Error::internal_error(format!(
            "logical metadata content-type {:?} does not match encrypted object header {:?} for {}/{}",
            logical.logical_content_type,
            metadata.logical_content_type,
            logical.bucket,
            logical.key
        )));
    }
    Ok(())
}

async fn get_object(
    State(state): State<AppState>,
    Path((path_bucket, path_key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    let (bucket, key) =
        resolve_bucket_and_key_for_object_path(&headers, uri.path(), path_bucket, Some(path_key))?;
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::ReadObject,
        Some(&bucket),
        Some(&key),
    )?;

    let resolved = resolve_object_read(&state, &bucket, &key)
        .await
        .map_err(|error| map_object_error(error, &bucket, &key))?;
    record_data_plane_fallback_read(&state, resolved.source);
    if !resolved.backend.capabilities().streaming_get {
        ensure_object_within_in_memory_limit(&state.config, resolved.object.size)?;
    }
    let read_started_at = current_unix_ms();
    let read_usage = state.provider_resource_stats.start_operation(
        resolved.source.provider.as_str(),
        ProviderResourceOperationKind::Read,
    );
    let object = resolved
        .backend
        .get_object(&bucket, &key)
        .await
        .map_err(|error| {
            state.provider_io_stats.record_failure(
                resolved.source.provider.as_str(),
                ProviderIoOperationKind::Read,
                &error.to_string(),
            );
            map_object_error(error, &bucket, &key)
        })?;
    let observed_body = observe_provider_read_body(
        state.provider_io_stats.clone(),
        resolved.source.provider.as_str(),
        read_started_at,
        object.info.size,
        object.first_response_latency_ms,
        object.body,
        read_usage,
    );
    let logical =
        load_logical_object_record(&state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let (response_object, response_body) = if let Some(logical) = logical.as_ref() {
        if logical.encrypted {
            let key_source_kind = logical.key_source_kind.as_deref().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_source_kind metadata"
                ))
            })?;
            let key_source_kind = match key_source_kind {
                "env_var" => EncryptionKeySourceKind::EnvVar,
                "file_path" => EncryptionKeySourceKind::FilePath,
                "external_kms" => EncryptionKeySourceKind::ExternalKms,
                "gateway_managed" => EncryptionKeySourceKind::GatewayManaged,
                other => {
                    return Err(S3Error::internal_error(format!(
                        "encrypted object {bucket}/{key} has unknown key_source_kind {other}"
                    )));
                }
            };
            let key_source_ref = logical.key_source_ref.clone().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_source_ref metadata"
                ))
            })?;
            let key_id = logical.key_id.clone().ok_or_else(|| {
                S3Error::internal_error(format!(
                    "encrypted object {bucket}/{key} is missing key_id metadata"
                ))
            })?;
            let profile = EncryptionProfile {
                id: logical
                    .encryption_profile_id
                    .clone()
                    .unwrap_or_else(|| "restored".to_string()),
                label: None,
                enabled: true,
                algorithm_preference: EncryptionAlgorithmPreference::Auto,
                chunk_plaintext_bytes: logical.chunk_plaintext_bytes.unwrap_or_default(),
                key_id,
                key_source_kind,
                key_source_ref,
                notes: None,
            };
            let key_encryption_key = load_profile_encryption_key_material(&state, &profile)
                .map_err(map_backend_error_to_s3)?;
            let prepared = prepare_decrypt_download(observed_body, key_encryption_key)
                .await
                .map_err(|error| S3Error::internal_error(error.to_string()))?;
            validate_decrypted_object_metadata(logical, &prepared.metadata)?;
            (
                public_object_info(object.info, Some(logical)),
                prepared.body,
            )
        } else {
            (
                public_object_info(object.info, Some(logical)),
                observed_body,
            )
        }
    } else {
        (object.info, observed_body)
    };

    let selected_range = headers
        .get(axum::http::header::RANGE)
        .map(|value| {
            let value = value.to_str().map_err(|_| {
                S3Error::invalid_request("Range header must be valid visible ASCII.")
            })?;
            parse_single_range_header(value, response_object.size)
        })
        .transpose()?;
    let (status, response_body, content_length, content_range) = if let Some(range) = selected_range
    {
        (
            StatusCode::PARTIAL_CONTENT,
            slice_body_by_range(response_body, range),
            range.len(),
            Some(format!(
                "bytes {}-{}/{}",
                range.start, range.end, response_object.size
            )),
        )
    } else {
        (StatusCode::OK, response_body, response_object.size, None)
    };

    let mut response_headers = HeaderMap::new();
    response_headers.insert(
        CONTENT_LENGTH,
        HeaderValue::from_str(&content_length.to_string()).expect("content length should be valid"),
    );
    response_headers.insert(
        CONTENT_TYPE,
        HeaderValue::from_str(
            response_object
                .content_type
                .as_deref()
                .unwrap_or("application/octet-stream"),
        )
        .expect("content type should be valid"),
    );
    if let Some(etag) = object_http_etag(&response_object) {
        response_headers.insert(
            ETAG,
            HeaderValue::from_str(&quoted_etag(Some(etag.as_str()))).expect("etag should be valid"),
        );
    }
    if let Some(last_modified) = http_last_modified(response_object.last_modified.as_deref()) {
        response_headers.insert(
            LAST_MODIFIED,
            HeaderValue::from_str(&last_modified).expect("last-modified should be valid"),
        );
    }
    response_headers.insert(
        axum::http::header::ACCEPT_RANGES,
        HeaderValue::from_static("bytes"),
    );
    if let Some(content_range) = content_range {
        response_headers.insert(
            axum::http::header::CONTENT_RANGE,
            HeaderValue::from_str(&content_range).expect("content range should be valid"),
        );
    }
    apply_read_source_headers(&mut response_headers, resolved.source);

    // Keep the permit alive until the response body stream is fully consumed.
    let data_plane_stats = state.data_plane_stats.clone();
    let body_stream = futures_util::stream::unfold(
        (permit, response_body.into_stream(), data_plane_stats),
        |(permit, mut inner, data_plane_stats)| async move {
            inner.next().await.map(|item| {
                let item = item.map(|chunk| {
                    data_plane_stats.record_bytes_out(chunk.len() as u64);
                    chunk
                });
                (
                    item.map_err(std::io::Error::other),
                    (permit, inner, data_plane_stats),
                )
            })
        },
    );
    Ok((status, response_headers, Body::from_stream(body_stream)).into_response())
}

async fn put_object(
    State(state): State<AppState>,
    Path((path_bucket, path_key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, S3Error> {
    let (bucket, key) =
        resolve_bucket_and_key_for_object_path(&headers, uri.path(), path_bucket, Some(path_key))?;
    let multipart = parse_multipart_query(uri.query())?;
    if let Some(upload_part) = multipart.upload_part {
        return upload_multipart_part(state, bucket, key, method, uri, headers, body, upload_part)
            .await;
    }
    let copy_source = headers
        .get("x-amz-copy-source")
        .map(|value| {
            value
                .to_str()
                .map(ToString::to_string)
                .map_err(|_| S3Error::invalid_request("x-amz-copy-source must be valid UTF-8."))
        })
        .transpose()?;
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    if let Some(copy_source) = copy_source {
        let parsed = parse_copy_source_header(&copy_source)?;
        let payload_hash = headers
            .get("x-amz-content-sha256")
            .and_then(|value| value.to_str().ok())
            .map(ToString::to_string)
            .or_else(|| {
                has_presigned_query_auth(uri.query())
                    .ok()
                    .and_then(|present| present.then_some("UNSIGNED-PAYLOAD".to_string()))
            })
            .ok_or_else(|| S3Error::access_denied("Missing x-amz-content-sha256 header."))?;
        let application = if payload_hash == "UNSIGNED-PAYLOAD" {
            authorize_s3(&state, &method, &uri, &headers, None)?
        } else {
            authorize_s3(&state, &method, &uri, &headers, Some(&[]))?
        };
        ensure_s3_application_permission(
            &application,
            S3ActionKind::ReadObject,
            Some(&parsed.bucket),
            Some(&parsed.key),
        )?;
        ensure_s3_application_permission(
            &application,
            S3ActionKind::WriteObject,
            Some(&bucket),
            Some(&key),
        )?;
        return execute_copy_object(&state, parsed.bucket, parsed.key, bucket, key).await;
    }
    let content_length = headers
        .get(CONTENT_LENGTH)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<u64>().ok());
    let payload_hash = headers
        .get("x-amz-content-sha256")
        .and_then(|value| value.to_str().ok())
        .map(ToString::to_string)
        .or_else(|| {
            has_presigned_query_auth(uri.query())
                .ok()
                .and_then(|present| present.then_some("UNSIGNED-PAYLOAD".to_string()))
        })
        .ok_or_else(|| S3Error::access_denied("Missing x-amz-content-sha256 header."))?;
    let content_type = headers
        .get(CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(ToString::to_string);

    let (application, body_len, request_body, write_path) = if payload_hash == "UNSIGNED-PAYLOAD" {
        let application = authorize_s3(&state, &method, &uri, &headers, None)?;
        ensure_s3_application_permission(
            &application,
            S3ActionKind::WriteObject,
            Some(&bucket),
            Some(&key),
        )?;
        let body_len = content_length.ok_or_else(|| {
            S3Error::access_denied(
                "UNSIGNED-PAYLOAD uploads must include a valid Content-Length header.",
            )
        })?;
        let request_body = PreparedPutRequestBody::plain(ObjectBody::from_stream(
            body.into_data_stream()
                .map_ok({
                    let data_plane_stats = state.data_plane_stats.clone();
                    move |chunk| {
                        data_plane_stats.record_bytes_in(chunk.len() as u64);
                        chunk
                    }
                })
                .map_err(|error| BlobError::BodyStream(error.to_string())),
        ));
        (
            application,
            body_len,
            request_body,
            ProviderWritePathKind::Streaming,
        )
    } else {
        let use_in_memory_body = content_length
            .map(|length| length <= state.config.max_in_memory_object_bytes as u64)
            .unwrap_or(state.config.max_spooled_object_bytes == 0);
        if use_in_memory_body {
            let body = to_bytes(body, state.config.max_in_memory_object_bytes)
                .await
                .map_err(|error| {
                    S3Error::entity_too_large(format!(
                        "request body exceeds in-memory limit: {error}"
                    ))
                })?;
            record_data_plane_bytes_in(&state, body.len() as u64);
            let application = authorize_s3(&state, &method, &uri, &headers, Some(&body))?;
            ensure_s3_application_permission(
                &application,
                S3ActionKind::WriteObject,
                Some(&bucket),
                Some(&key),
            )?;
            ensure_object_within_in_memory_limit(&state.config, body.len() as u64)?;
            (
                application,
                body.len() as u64,
                PreparedPutRequestBody::plain(body.into()),
                ProviderWritePathKind::InMemory,
            )
        } else if let Some(body_len) = content_length {
            let application = authorize_s3_with_verified_payload_hash(
                &state,
                &method,
                &uri,
                &headers,
                &payload_hash,
            )?;
            ensure_s3_application_permission(
                &application,
                S3ActionKind::WriteObject,
                Some(&bucket),
                Some(&key),
            )?;
            let (body, validation) = streaming_verified_request_body(&state, body, &payload_hash);
            (
                application,
                body_len,
                PreparedPutRequestBody::validated(body, validation),
                ProviderWritePathKind::Streaming,
            )
        } else {
            let application = authorize_s3_with_verified_payload_hash(
                &state,
                &method,
                &uri,
                &headers,
                &payload_hash,
            )?;
            ensure_s3_application_permission(
                &application,
                S3ActionKind::WriteObject,
                Some(&bucket),
                Some(&key),
            )?;
            let spooled = spool_signed_request_body(&state, body, content_length).await?;
            if spooled.sha256_hex != payload_hash {
                return Err(S3Error::signature_mismatch(
                    "x-amz-content-sha256 does not match the request body.",
                ));
            }
            (
                application,
                spooled.size,
                PreparedPutRequestBody::Spooled(spooled),
                ProviderWritePathKind::Spooled,
            )
        }
    };

    execute_put_upload(
        &state,
        bucket,
        key,
        application,
        body_len,
        content_type,
        request_body,
        write_path,
    )
    .await
}

async fn post_object(
    State(state): State<AppState>,
    Path((path_bucket, path_key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, S3Error> {
    let (bucket, key) =
        resolve_bucket_and_key_for_object_path(&headers, uri.path(), path_bucket, Some(path_key))?;
    let multipart = parse_multipart_query(uri.query())?;
    if multipart.initiate_upload {
        return initiate_multipart_upload(state, bucket, key, method, uri, headers).await;
    }
    if let Some(upload_id) = multipart.complete_upload_id {
        return complete_multipart_upload(
            state, bucket, key, method, uri, headers, body, upload_id,
        )
        .await;
    }
    Err(S3Error::invalid_request(
        "Unsupported POST request. Use ?uploads or ?uploadId=...",
    ))
}

async fn delete_object(
    State(state): State<AppState>,
    Path((path_bucket, path_key)): Path<(String, String)>,
    method: Method,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Result<Response, S3Error> {
    let (bucket, key) =
        resolve_bucket_and_key_for_object_path(&headers, uri.path(), path_bucket, Some(path_key))?;
    let multipart = parse_multipart_query(uri.query())?;
    if let Some(upload_id) = multipart.abort_upload_id {
        return abort_multipart_upload(state, bucket, key, method, uri, headers, upload_id).await;
    }
    record_data_plane_request(&state);
    try_acquire_data_plane_request_slot(&state, current_unix_ms())?;
    let _permit = try_acquire_data_plane_permit(&state)?;
    let application = authorize_s3(&state, &method, &uri, &headers, None)?;
    ensure_s3_application_permission(
        &application,
        S3ActionKind::DeleteObject,
        Some(&bucket),
        Some(&key),
    )?;
    let home_provider = persisted_or_primary_home_provider(&state, &bucket, &key)
        .map_err(map_backend_error_to_s3)?;
    let previous_placement_record = state
        .metadata_store
        .object_placement(&bucket, &key)
        .map_err(|error| map_backend_error_to_s3(BlobError::Upstream(error.to_string())))?;
    let previous_logical_record =
        load_logical_object_record(&state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let previous_protection_plan_record = state
        .metadata_store
        .object_protection_plan(&bucket, &key)
        .map_err(|error| map_backend_error_to_s3(BlobError::Upstream(error.to_string())))?;
    let protection_plan =
        load_object_protection_plan(&state, &bucket, &key).map_err(map_backend_error_to_s3)?;
    let home_backend =
        backend_for_provider(&state, home_provider).map_err(map_backend_error_to_s3)?;
    let delete_sync_targets = protection_plan
        .as_ref()
        .map(|plan| plan.sync_targets.clone())
        .unwrap_or_default();
    let gateway_write_ahead_log = maybe_prepare_gateway_write_ahead_log(
        &state,
        &application,
        GatewayWriteAheadLogOperation::Delete,
        &bucket,
        &key,
        home_provider,
        previous_logical_record.as_ref(),
        &delete_sync_targets,
        &[],
        previous_placement_record.clone(),
        previous_logical_record.clone(),
        previous_protection_plan_record.clone(),
    )
    .await
    .map_err(map_backend_error_to_s3)?;

    match home_backend.delete_object(&bucket, &key).await {
        Ok(()) => {}
        Err(error) if should_treat_delete_not_found_as_success(&error) => {}
        Err(error) => return Err(map_object_error(error, &bucket, &key)),
    }

    if let Err(error) = delete_object_metadata_records(&state, &bucket, &key) {
        let rollback_note = rollback_delete_after_failure_with_note(
            &state,
            &bucket,
            &key,
            previous_placement_record.clone(),
            previous_logical_record.clone(),
            previous_protection_plan_record.clone(),
        );
        return Err(S3Error::internal_error(format!(
            "delete remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        )));
    }

    let jobs = enqueue_replication_delete_for_object(
        &state,
        home_provider,
        &bucket,
        &key,
        protection_plan.as_ref(),
    )
    .map_err(|error| {
        let rollback_note = rollback_delete_after_failure_with_note(
            &state,
            &bucket,
            &key,
            previous_placement_record.clone(),
            previous_logical_record.clone(),
            previous_protection_plan_record.clone(),
        );
        S3Error::internal_error(format!(
            "delete remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        ))
    })?;
    enqueue_delete_object_replication_jobs(&state, &bucket, &key, &jobs).map_err(|error| {
        let rollback_note = rollback_delete_after_failure_with_note(
            &state,
            &bucket,
            &key,
            previous_placement_record,
            previous_logical_record,
            previous_protection_plan_record,
        );
        S3Error::internal_error(format!(
            "delete remote side effect may have occurred for {}/{}: {error}; {rollback_note}",
            bucket, key
        ))
    })?;
    if !jobs.is_empty() {
        info!(
            bucket = %bucket,
            key = %key,
            queued_jobs = jobs.len(),
            "replication jobs enqueued after delete"
        );
    }
    if let Some(context) = gateway_write_ahead_log.as_ref() {
        if let Err(error) = mark_gateway_write_ahead_log_committed(&state, context).await {
            warn!(
                bucket = %bucket,
                key = %key,
                remote_provider = context.remote_provider.as_str(),
                error = %error,
                "failed to mark gateway write-ahead log as committed after delete"
            );
        }
    }

    Ok(StatusCode::NO_CONTENT.into_response())
}

const MULTIPART_SESSION_TTL_MS: u64 = 24 * 60 * 60 * 1000;

#[derive(Default)]
struct MultipartQuery {
    initiate_upload: bool,
    upload_part: Option<MultipartPartUploadQuery>,
    complete_upload_id: Option<String>,
    abort_upload_id: Option<String>,
}

struct MultipartPartUploadQuery {
    upload_id: String,
    part_number: u16,
}

fn parse_multipart_query(query: Option<&str>) -> Result<MultipartQuery, S3Error> {
    let Some(query) = query else {
        return Ok(MultipartQuery::default());
    };
    let params = query_pairs(query);
    let mut multipart = MultipartQuery::default();
    let mut upload_id: Option<String> = None;
    let mut part_number: Option<u16> = None;
    for (key, value) in params {
        if key == "uploads" {
            multipart.initiate_upload = true;
        } else if key == "uploadId" && !value.is_empty() {
            upload_id = Some(value.to_string());
        } else if key == "partNumber" && !value.is_empty() {
            let parsed = value.parse::<u16>().map_err(|_| {
                S3Error::invalid_request("partNumber must be an integer in 1..=10000")
            })?;
            if parsed == 0 || parsed > 10_000 {
                return Err(S3Error::invalid_request(
                    "partNumber must be an integer in 1..=10000",
                ));
            }
            part_number = Some(parsed);
        }
    }
    if let (Some(upload_id), Some(part_number)) = (upload_id.clone(), part_number) {
        multipart.upload_part = Some(MultipartPartUploadQuery {
            upload_id,
            part_number,
        });
    } else if let Some(upload_id) = upload_id {
        multipart.complete_upload_id = Some(upload_id.clone());
        multipart.abort_upload_id = Some(upload_id);
    }
    Ok(multipart)
}

fn parse_list_objects_v2_query(query: Option<&str>) -> ListObjectsV2Query {
    let mut parsed = ListObjectsV2Query::default();
    let Some(query) = query else {
        return parsed;
    };
    for (key, value) in query_pairs(query) {
        match key {
            "list-type" => parsed.list_type = Some(value.to_string()),
            "prefix" => parsed.prefix = Some(value.to_string()),
            "delimiter" => parsed.delimiter = Some(value.to_string()),
            "continuation-token" => parsed.continuation_token = Some(value.to_string()),
            "start-after" => parsed.start_after = Some(value.to_string()),
            "max-keys" => {
                if let Ok(value) = value.parse::<usize>() {
                    parsed.max_keys = Some(value);
                }
            }
            _ => {}
        }
    }
    parsed
}

fn bucket_from_virtual_host(headers: &HeaderMap) -> Option<String> {
    let host = headers.get(HOST)?.to_str().ok()?;
    let host = host.trim().to_ascii_lowercase();
    let host_without_port = strip_host_port(&host)?;
    let (bucket, suffix) = host_without_port.split_once('.')?;
    if bucket.is_empty() || bucket.contains('.') {
        return None;
    }
    if suffix != "localhost" && suffix != "127.0.0.1" {
        return None;
    }
    Some(bucket.to_string())
}

fn strip_host_port(host: &str) -> Option<&str> {
    let (hostname, maybe_port) = host.rsplit_once(':').unwrap_or((host, ""));
    if maybe_port.is_empty() {
        return Some(host);
    }
    maybe_port
        .parse::<u16>()
        .ok()
        .filter(|port| *port > 0)
        .map(|_| hostname)
}

fn resolve_bucket_and_key_for_object_path(
    headers: &HeaderMap,
    uri_path: &str,
    path_bucket: String,
    path_key: Option<String>,
) -> Result<(String, String), S3Error> {
    if let Some(virtual_bucket) = bucket_from_virtual_host(headers) {
        let key = uri_path.trim_start_matches('/').to_string();
        if key.is_empty() {
            return Err(S3Error::no_such_key(&virtual_bucket, ""));
        }
        return Ok((virtual_bucket, key));
    }
    let key = path_key.ok_or_else(|| S3Error::invalid_request("Object key is missing."))?;
    Ok((path_bucket, key))
}

fn multipart_spool_root(config: &AppConfig) -> PathBuf {
    let base = config
        .body_spool_dir
        .as_deref()
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir);
    base.join("ccbg-multipart-spool")
}

fn multipart_upload_dir(config: &AppConfig, upload_id: &str) -> PathBuf {
    multipart_spool_root(config).join(sha256_hex(upload_id.as_bytes()))
}

fn multipart_part_path(config: &AppConfig, upload_id: &str, part_number: u16) -> PathBuf {
    multipart_upload_dir(config, upload_id).join(format!("part-{part_number:05}.bin"))
}

fn multipart_part_temp_path(config: &AppConfig, upload_id: &str, part_number: u16) -> PathBuf {
    let mut random = [0u8; 8];
    OsRng.fill_bytes(&mut random);
    multipart_upload_dir(config, upload_id)
        .join(format!("part-{part_number:05}-{}.tmp", hex::encode(random)))
}

