    #[test]
    fn admin_log_ring_enforces_entry_and_line_bounds() {
        let mut ring = AdminLogRing::new(3, 120, 16);
        ring.push_line("first");
        ring.push_line("second");
        ring.push_line("third");
        ring.push_line("fourth");
        assert_eq!(ring.entries.len(), 3);
        assert_eq!(
            ring.entries.front().map(|entry| entry.line.as_str()),
            Some("second")
        );
        ring.push_line("0123456789abcdefXYZ");
        let last = ring.entries.back().expect("entry should exist");
        assert!(last.line.starts_with("0123456789abcdef"));
        assert!(last.line.len() >= 16);
    }

    #[test]
    fn admin_log_source_query_applies_limit_cursor_and_filter() {
        let ring = Arc::new(Mutex::new(AdminLogRing::new(16, 2048, 256)));
        {
            let mut lock = ring.lock().expect("lock");
            lock.push_line("INFO startup ok");
            lock.push_line("WARN mobile degraded");
            lock.push_line("ERROR mobile timeout");
        }
        let source = InMemoryAdminLogSource { ring };
        let result = source.query(&AdminLogQuery {
            level: Some("warn".to_string()),
            keyword: Some("mobile".to_string()),
            limit: Some(2),
            cursor: None,
        });
        assert_eq!(result.entries.len(), 1);
        assert_eq!(result.entries[0].level, "warn");
        let cursor = result.next_cursor.clone().unwrap_or_default();
        let paged = source.query(&AdminLogQuery {
            level: None,
            keyword: None,
            limit: Some(1),
            cursor: Some(cursor),
        });
        assert!(paged.entries.len() <= 1);
    }

    #[derive(Debug, Clone)]
    struct RecordedWebhookRequest {
        body: String,
        event_id: Option<String>,
        signature_version: Option<String>,
        signature: Option<String>,
        timestamp: Option<String>,
    }

    async fn spawn_test_webhook_server() -> (
        String,
        Arc<Mutex<Vec<RecordedWebhookRequest>>>,
        oneshot::Sender<()>,
    ) {
        spawn_test_webhook_server_with_first_status(StatusCode::NO_CONTENT).await
    }

    async fn spawn_test_webhook_server_with_first_status(
        first_status: StatusCode,
    ) -> (
        String,
        Arc<Mutex<Vec<RecordedWebhookRequest>>>,
        oneshot::Sender<()>,
    ) {
        let received = Arc::new(Mutex::new(Vec::<RecordedWebhookRequest>::new()));
        let request_count = Arc::new(AtomicU64::new(0));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("test webhook listener should bind");
        let addr = listener.local_addr().expect("local addr should load");
        let received_clone = received.clone();
        let request_count_clone = request_count.clone();
        let app = Router::new().route(
            "/",
            any(move |request: Request<Body>| {
                let received = received_clone.clone();
                let request_count = request_count_clone.clone();
                async move {
                    let status = if request_count.fetch_add(1, Ordering::SeqCst) == 0 {
                        first_status
                    } else {
                        StatusCode::NO_CONTENT
                    };
                    let event_id = request
                        .headers()
                        .get(NOTIFY_EVENT_ID_HEADER)
                        .and_then(|value| value.to_str().ok())
                        .map(ToString::to_string);
                    let signature_version = request
                        .headers()
                        .get(NOTIFY_SIGNATURE_VERSION_HEADER)
                        .and_then(|value| value.to_str().ok())
                        .map(ToString::to_string);
                    let signature = request
                        .headers()
                        .get(NOTIFY_SIGNATURE_HEADER)
                        .and_then(|value| value.to_str().ok())
                        .map(ToString::to_string);
                    let timestamp = request
                        .headers()
                        .get(NOTIFY_TIMESTAMP_HEADER)
                        .and_then(|value| value.to_str().ok())
                        .map(ToString::to_string);
                    let bytes = to_bytes(request.into_body(), usize::MAX)
                        .await
                        .expect("webhook request body should read");
                    let body = String::from_utf8(bytes.to_vec())
                        .expect("webhook request body should be utf-8");
                    received
                        .lock()
                        .expect("received webhook list poisoned")
                        .push(RecordedWebhookRequest {
                            body,
                            event_id,
                            signature_version,
                            signature,
                            timestamp,
                        });
                    status
                }
            }),
        );
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        tokio::spawn(async move {
            let _ = axum::serve(listener, app)
                .with_graceful_shutdown(async {
                    let _ = shutdown_rx.await;
                })
                .await;
        });

        (format!("http://{addr}"), received, shutdown_tx)
    }

