    #[test]
    fn parse_proc_status_memory_payload_reads_kib_values() {
        let payload = parse_proc_status_memory_payload(
            "Name:\tgatewayd\nVmSize:\t   2048 kB\nVmRSS:\t   1024 kB\nVmHWM:\t   1536 kB\nVmData:\t   512 kB\nRssAnon:\t   256 kB\nRssFile:\t   768 kB\nRssShmem:\t   8 kB\nThreads:\t 12\n",
        );
        assert_eq!(payload.virtual_bytes, Some(2_097_152));
        assert_eq!(payload.rss_bytes, Some(1_048_576));
        assert_eq!(payload.hwm_bytes, Some(1_572_864));
        assert_eq!(payload.data_bytes, Some(524_288));
        assert_eq!(payload.rss_anon_bytes, Some(262_144));
        assert_eq!(payload.rss_file_bytes, Some(786_432));
        assert_eq!(payload.rss_shmem_bytes, Some(8_192));
        assert_eq!(payload.threads, Some(12));
    }

