    fn signed_headers_for_application_with_host(
        config: &AppConfig,
        access_key_id: &str,
        secret_access_key: &str,
        method: &Method,
        uri: &Uri,
        body: &[u8],
        extra_headers: &[(&str, &str)],
        host: &str,
    ) -> HeaderMap {
        signed_headers_for_application_with_host_at_time(
            config,
            access_key_id,
            secret_access_key,
            method,
            uri,
            body,
            extra_headers,
            host,
            &test_amz_date_offset(0),
        )
    }

    fn signed_headers_for_application_with_host_at_time(
        config: &AppConfig,
        access_key_id: &str,
        secret_access_key: &str,
        method: &Method,
        uri: &Uri,
        body: &[u8],
        extra_headers: &[(&str, &str)],
        host: &str,
        amz_date: &str,
    ) -> HeaderMap {
        let short_date = amz_date[0..8].to_string();
        let payload_hash = sha256_hex(body);

        let mut headers = HeaderMap::new();
        headers.insert(
            HOST,
            HeaderValue::from_str(host).expect("host should be a valid header value"),
        );
        headers.insert(
            "x-amz-date",
            HeaderValue::from_str(&amz_date).expect("x-amz-date should be valid"),
        );
        headers.insert(
            "x-amz-content-sha256",
            HeaderValue::from_str(&payload_hash).expect("payload hash should be valid"),
        );

        let mut signed_headers = vec![
            "host".to_string(),
            "x-amz-content-sha256".to_string(),
            "x-amz-date".to_string(),
        ];

        for (name, value) in extra_headers {
            let header_name =
                axum::http::HeaderName::from_bytes(name.as_bytes()).expect("header name is valid");
            headers.insert(
                header_name,
                HeaderValue::from_str(value).expect("extra header should be valid"),
            );
            signed_headers.push(name.to_ascii_lowercase());
        }

        signed_headers.sort();
        signed_headers.dedup();

        let canonical_request = format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            method.as_str(),
            canonical_uri(uri.path()),
            canonical_query_string(uri.query()),
            canonical_headers(&headers, &signed_headers)
                .expect("canonical headers should build in tests"),
            signed_headers.join(";"),
            payload_hash
        );

        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{}\n{}/{}/s3/aws4_request\n{}",
            amz_date,
            short_date,
            config.s3_region,
            sha256_hex(canonical_request.as_bytes())
        );

        let signature = sign_v4(
            secret_access_key,
            &short_date,
            &config.s3_region,
            "s3",
            &string_to_sign,
        );
        let authorization = format!(
            "AWS4-HMAC-SHA256 Credential={}/{}/{}/s3/aws4_request, SignedHeaders={}, Signature={}",
            access_key_id,
            short_date,
            config.s3_region,
            signed_headers.join(";"),
            signature
        );

        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&authorization).expect("authorization should be valid"),
        );

        headers
    }

    fn unsigned_payload_headers(
        config: &AppConfig,
        method: &Method,
        uri: &Uri,
        content_length: u64,
        extra_headers: &[(&str, &str)],
    ) -> HeaderMap {
        let amz_date = test_amz_date_offset(0);
        let short_date = amz_date[0..8].to_string();
        let payload_hash = "UNSIGNED-PAYLOAD";

        let mut headers = HeaderMap::new();
        headers.insert(HOST, HeaderValue::from_static("127.0.0.1:61080"));
        headers.insert(
            "x-amz-date",
            HeaderValue::from_str(&amz_date).expect("x-amz-date should be valid"),
        );
        headers.insert(
            "x-amz-content-sha256",
            HeaderValue::from_static(payload_hash),
        );
        headers.insert(
            CONTENT_LENGTH,
            HeaderValue::from_str(&content_length.to_string())
                .expect("content length should be valid"),
        );

        let mut signed_headers = vec![
            "content-length".to_string(),
            "host".to_string(),
            "x-amz-content-sha256".to_string(),
            "x-amz-date".to_string(),
        ];

        for (name, value) in extra_headers {
            let header_name =
                axum::http::HeaderName::from_bytes(name.as_bytes()).expect("header name is valid");
            headers.insert(
                header_name,
                HeaderValue::from_str(value).expect("extra header should be valid"),
            );
            signed_headers.push(name.to_ascii_lowercase());
        }

        signed_headers.sort();
        signed_headers.dedup();

        let canonical_request = format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            method.as_str(),
            canonical_uri(uri.path()),
            canonical_query_string(uri.query()),
            canonical_headers(&headers, &signed_headers)
                .expect("canonical headers should build in tests"),
            signed_headers.join(";"),
            payload_hash
        );

        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{}\n{}/{}/s3/aws4_request\n{}",
            amz_date,
            short_date,
            config.s3_region,
            sha256_hex(canonical_request.as_bytes())
        );

        let signature = sign_v4(
            &config.s3_secret_access_key,
            &short_date,
            &config.s3_region,
            "s3",
            &string_to_sign,
        );
        let authorization = format!(
            "AWS4-HMAC-SHA256 Credential={}/{}/{}/s3/aws4_request, SignedHeaders={}, Signature={}",
            config.s3_access_key_id,
            short_date,
            config.s3_region,
            signed_headers.join(";"),
            signature
        );

        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&authorization).expect("authorization header should be valid"),
        );

        headers
    }

    fn presigned_object_request(
        config: &AppConfig,
        access_key_id: &str,
        secret_access_key: &str,
        method: &Method,
        path: &str,
        amz_date: &str,
        expires: u64,
        signed_headers: &[&str],
        request_headers: &[(&str, &str)],
    ) -> (Uri, HeaderMap) {
        let (canonical_path, existing_query) = match path.split_once('?') {
            Some((path, query)) => (path, Some(query)),
            None => (path, None),
        };
        let short_date = &amz_date[0..8];
        let credential = utf8_percent_encode(
            &format!(
                "{}/{}/{}/s3/aws4_request",
                access_key_id, short_date, config.s3_region
            ),
            NON_ALPHANUMERIC,
        )
        .to_string();
        let signed_headers_value = signed_headers.join(";");
        let signed_headers_query_value =
            utf8_percent_encode(&signed_headers_value, NON_ALPHANUMERIC).to_string();
        let mut headers = HeaderMap::new();
        headers.insert(HOST, HeaderValue::from_static("127.0.0.1:61080"));
        for (name, value) in request_headers {
            let header_name =
                axum::http::HeaderName::from_bytes(name.as_bytes()).expect("header name is valid");
            headers.insert(
                header_name,
                HeaderValue::from_str(value).expect("header should be valid"),
            );
        }
        let auth_query = format!(
            "X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential={credential}&X-Amz-Date={amz_date}&X-Amz-Expires={expires}&X-Amz-SignedHeaders={signed_headers_query_value}"
        );
        let query_without_signature = existing_query
            .map(|query| format!("{query}&{auth_query}"))
            .unwrap_or(auth_query);
        let canonical_request = format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            method.as_str(),
            canonical_uri(canonical_path),
            canonical_query_string(Some(&query_without_signature)),
            canonical_headers(
                &headers,
                &signed_headers
                    .iter()
                    .map(|name| (*name).to_string())
                    .collect::<Vec<_>>()
            )
            .expect("canonical headers should build"),
            signed_headers_value,
            "UNSIGNED-PAYLOAD"
        );
        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{}\n{}/{}/s3/aws4_request\n{}",
            amz_date,
            short_date,
            config.s3_region,
            sha256_hex(canonical_request.as_bytes())
        );
        let signature = sign_v4(
            secret_access_key,
            short_date,
            &config.s3_region,
            "s3",
            &string_to_sign,
        );
        let uri: Uri =
            format!("{canonical_path}?{query_without_signature}&X-Amz-Signature={signature}")
                .parse()
                .expect("uri should parse");
        (uri, headers)
    }

