    #[tokio::test]
    async fn metrics_health_endpoints_expose_runtime_and_metrics() {
        let state = test_state();
        state.provider_io_stats.record_success_with_response(
            "stub",
            ProviderIoOperationKind::Read,
            12,
            None,
            Some(4096),
        );
        state.provider_io_stats.record_failure(
            "stub",
            ProviderIoOperationKind::Write,
            "simulated write failure",
        );

        let Json(health) = metrics_healthz(State(state.clone()))
            .await
            .expect("metrics health should succeed");
        assert_eq!(health.status, "ok");
        assert!(health.ready);
        assert_eq!(health.runtime.metrics_bind_addr, "127.0.0.1:61083");
        assert_eq!(health.runtime.data_plane_max_in_flight, 8);
        assert_eq!(health.runtime.data_plane_max_requests_per_second, 0);
        assert_eq!(
            health.runtime.provenance.release_fingerprint,
            DEFAULT_RELEASE_FINGERPRINT
        );
        assert_eq!(health.runtime.provenance.license_id, CCBG_LICENSE_ID);
        assert_eq!(
            health.runtime.process_memory.sample_limit,
            PROCESS_MEMORY_HISTORY_LIMIT
        );
        assert!(!health.runtime.process_memory.samples.is_empty());
        assert!(
            health
                .runtime
                .catalogs
                .provider_probes
                .providers
                .contains_key("unicom")
        );
        let onedrive_probe_catalog = health
            .runtime
            .catalogs
            .provider_probes
            .providers
            .get("onedrive")
            .expect("onedrive parking probe catalog should be reported");
        assert_eq!(onedrive_probe_catalog.schema_versions, vec![1]);
        assert_eq!(onedrive_probe_catalog.status, "parking");
        let telecom_capability_catalog = health
            .runtime
            .catalogs
            .provider_capabilities
            .providers
            .get("telecom")
            .expect("telecom native capability catalog should be reported");
        assert_eq!(telecom_capability_catalog.schema_versions, vec![1]);
        assert_eq!(telecom_capability_catalog.status, "active");
        assert!(
            health
                .runtime
                .catalogs
                .browser_flows
                .providers
                .contains_key("telecom")
        );
        assert_eq!(health.monitoring.provider_summary.total, 2);

        let ready_status = metrics_readyz(State(state.clone()))
            .await
            .expect("metrics ready should succeed");
        assert_eq!(ready_status, StatusCode::OK);

        let metrics_response = metrics_prometheus(State(state))
            .await
            .expect("metrics should succeed");
        assert_eq!(metrics_response.status(), StatusCode::OK);
        assert_eq!(
            metrics_response
                .headers()
                .get(CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/plain; version=0.0.4; charset=utf-8")
        );
        let body = to_bytes(metrics_response.into_body(), usize::MAX)
            .await
            .expect("metrics body should read");
        let body = String::from_utf8(body.to_vec()).expect("metrics body should be utf-8");
        assert!(body.contains("ccbg_up 1"));
        assert!(body.contains("ccbg_release_info"));
        assert!(body.contains(DEFAULT_RELEASE_FINGERPRINT));
        assert!(body.contains("ccbg_admin_alerts_open"));
        assert!(body.contains("ccbg_process_memory_bytes"));
        assert!(body.contains("ccbg_data_plane_concurrency_configured 8"));
        assert!(body.contains("ccbg_data_plane_concurrency_available 8"));
        assert!(body.contains("ccbg_data_plane_rate_limit_configured 0"));
        assert!(body.contains("ccbg_data_plane_rate_limit_current_second 0"));
        assert!(body.contains("ccbg_data_plane_requests_total 0"));
        assert!(body.contains("ccbg_data_plane_fallback_reads_total 0"));
        assert!(body.contains("ccbg_data_plane_bytes_total{direction=\"in\"} 0"));
        assert!(body.contains("ccbg_data_plane_bytes_total{direction=\"out\"} 0"));
        assert!(body.contains("ccbg_provider_health{provider=\"stub\",role=\"primary\"} 1"));
        assert!(body.contains(
            "ccbg_provider_io_operations_total{provider=\"stub\",operation=\"read\",outcome=\"success\"} 1"
        ));
        assert!(body.contains(
            "ccbg_provider_io_operations_total{provider=\"stub\",operation=\"write\",outcome=\"failure\"} 1"
        ));
        assert!(body.contains(
            "ccbg_provider_io_latency_ms{provider=\"stub\",operation=\"read\",kind=\"first_success\"} 12"
        ));
        assert!(body.contains("ccbg_replication_jobs{status=\"failed\"} 0"));
        assert!(body.contains("ccbg_replication_oldest_job_age_ms{status=\"pending\"} 0"));
        assert!(body.contains("ccbg_replication_dead_letter_jobs{target=\"all\"} 0"));
    }

