    #[tokio::test]
    async fn admin_login_cookie_unlocks_protected_routes() {
        let state = test_state();
        let protected_app = Router::new()
            .route("/", get(|| async { StatusCode::OK }))
            .layer(middleware::from_fn_with_state(
                state.clone(),
                require_admin_access,
            ));
        let public_app = Router::new().route("/api/admin/login", post(admin_login));
        let app = public_app.merge(protected_app).with_state(state.clone());

        let login_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/api/admin/login")
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"username":"admin","password":"test-password"}"#,
                    ))
                    .expect("request should build"),
            )
            .await
            .expect("login request should complete");
        assert_eq!(login_response.status(), StatusCode::OK);
        let session_cookie = login_response
            .headers()
            .get_all(SET_COOKIE)
            .iter()
            .filter_map(|value| value.to_str().ok())
            .find(|value| value.starts_with("ccbg_admin_session="))
            .expect("admin session cookie should be set")
            .split(';')
            .next()
            .expect("session cookie should contain a value")
            .to_string();

        let protected_response = app
            .oneshot(
                Request::builder()
                    .uri("/")
                    .header(COOKIE, session_cookie)
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("protected request should complete");
        assert_eq!(protected_response.status(), StatusCode::OK);
    }

