    #[tokio::test]
    async fn admin_change_password_persists_hash_and_unlocks_sensitive_routes() {
        let mut state = test_state();
        Arc::make_mut(&mut state.config).admin_username = None;
        Arc::make_mut(&mut state.config).admin_password_hash = None;
        Arc::make_mut(&mut state.config).admin_password_plain = None;

        let protected_sensitive_app = Router::new()
            .route("/api/locked", get(|| async { StatusCode::OK }))
            .layer(middleware::from_fn_with_state(
                state.clone(),
                require_admin_password_rotation_completed,
            ))
            .layer(middleware::from_fn_with_state(
                state.clone(),
                require_admin_access,
            ));

        let public_app = Router::new().route("/api/admin/login", post(admin_login));

        let protected_admin_app = Router::new()
            .route("/api/admin/change-password", post(admin_change_password))
            .merge(protected_sensitive_app)
            .layer(middleware::from_fn_with_state(
                state.clone(),
                require_admin_access,
            ));

        let login_app = Router::new()
            .merge(public_app)
            .merge(protected_admin_app)
            .with_state(state.clone());

        let login_response = login_app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/api/admin/login")
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"username":"admin","password":"password"}"#))
                    .expect("request should build"),
            )
            .await
            .expect("login request should complete");
        assert_eq!(login_response.status(), StatusCode::OK);
        let session_cookie = login_response
            .headers()
            .get_all(SET_COOKIE)
            .iter()
            .filter_map(|value| value.to_str().ok())
            .find(|value| value.starts_with("ccbg_admin_session="))
            .expect("admin session cookie should be set")
            .split(';')
            .next()
            .expect("session cookie should contain a value")
            .to_string();

        let blocked_response = login_app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/api/locked")
                    .header(COOKIE, session_cookie.clone())
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("blocked request should complete");
        assert_eq!(blocked_response.status(), StatusCode::FORBIDDEN);

        let change_response = login_app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/api/admin/change-password")
                    .header(CONTENT_TYPE, "application/json")
                    .header(COOKIE, session_cookie.clone())
                    .body(Body::from(
                        r#"{"current_password":"password","new_password":"new-password-1","confirm_password":"new-password-1"}"#,
                    ))
                    .expect("request should build"),
            )
            .await
            .expect("change password request should complete");
        assert_eq!(change_response.status(), StatusCode::OK);

        let unlocked_response = login_app
            .oneshot(
                Request::builder()
                    .uri("/api/locked")
                    .header(COOKIE, session_cookie)
                    .body(Body::empty())
                    .expect("request should build"),
            )
            .await
            .expect("unlocked request should complete");
        assert_eq!(unlocked_response.status(), StatusCode::OK);

        let auth = control_plane_snapshot(&state).admin_auth;
        assert!(auth.password_hash.is_some());
        assert!(auth.password_changed_at_unix_ms.is_some());
    }

