    fn metric_value_for_label(body: &str, metric_prefix: &str) -> u64 {
        let line = body
            .lines()
            .find(|line| line.starts_with(metric_prefix))
            .unwrap_or_else(|| panic!("metric line should exist: {metric_prefix}"));
        line.rsplit_once(' ')
            .and_then(|(_, value)| value.parse::<u64>().ok())
            .unwrap_or_else(|| panic!("metric value should parse: {line}"))
    }

    #[tokio::test]
    async fn metrics_include_nonzero_replication_delay_sli_values() {
        let state = test_state();
        let now_unix_ms = current_unix_ms();
        let mut pending_job = sample_replication_job_for_test(
            90,
            ProviderId::Onedrive,
            "root",
            "metrics/pending.txt",
        );
        pending_job.status = ReplicationStatus::Pending;
        pending_job.enqueued_at_unix_ms = u128::from(now_unix_ms.saturating_sub(45_000));
        let mut retry_job =
            sample_replication_job_for_test(91, ProviderId::Onedrive, "root", "metrics/retry.txt");
        retry_job.status = ReplicationStatus::RetryScheduled;
        retry_job.enqueued_at_unix_ms = u128::from(now_unix_ms.saturating_sub(75_000));
        retry_job.next_attempt_at_unix_ms = Some(u128::from(now_unix_ms.saturating_add(10_000)));
        state.replication.enqueue_existing_job(pending_job.clone());
        state.replication.enqueue_existing_job(retry_job.clone());
        state
            .metadata_store
            .enqueue_jobs(&[pending_job, retry_job])
            .expect("replication jobs should persist");
        record_replication_state(
            &state,
            ProviderId::Onedrive,
            ReplicationOperation::Put,
            ReplicationStatus::Failed,
            "root",
            "metrics/failed.txt",
            Some(5),
            Some("text/plain"),
        );

        let response = metrics_prometheus(State(state))
            .await
            .expect("metrics should succeed");
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("metrics body should read");
        let body = String::from_utf8(body.to_vec()).expect("metrics body should be utf-8");

        assert!(
            metric_value_for_label(
                &body,
                "ccbg_replication_oldest_job_age_ms{status=\"pending\"}"
            ) >= 40_000
        );
        assert!(
            metric_value_for_label(
                &body,
                "ccbg_replication_oldest_job_age_ms{status=\"retry_scheduled\"}"
            ) >= 70_000
        );
        assert!(
            metric_value_for_label(
                &body,
                "ccbg_replication_oldest_job_age_ms{status=\"latest_failed_object\"}"
            ) > 0
        );
    }

