    #[tokio::test]
    async fn admin_alerts_can_be_closed_persistently() {
        let mut state = test_state();
        Arc::make_mut(&mut state.config).admin_bind_addr =
            "0.0.0.0:61081".parse().expect("admin addr should parse");

        let Json(records) = update_admin_alert_suppression(
            State(state.clone()),
            Json(AdminAlertSuppressionInput {
                alert_id: "admin_panel_exposed_beyond_loopback".to_string(),
                title: Some("Admin panel is exposed beyond loopback".to_string()),
                suppressed: true,
            }),
        )
        .await
        .expect("alert suppression should succeed");

        assert_eq!(records.len(), 1);
        assert_eq!(records[0].id, "admin_panel_exposed_beyond_loopback");
        assert!(records[0].closed_at_unix_ms > 0);
        assert_eq!(
            records[0].delete_after_unix_ms,
            records[0]
                .closed_at_unix_ms
                .saturating_add(ADMIN_ALERT_CLOSE_RETENTION_MS)
        );

        let Json(status) = admin_status(State(state), HeaderMap::new())
            .await
            .expect("admin status should succeed");

        assert!(
            status
                .suppressed_alerts
                .iter()
                .any(|alert| alert.id == "admin_panel_exposed_beyond_loopback")
        );
        assert!(status.alerts.iter().all(|alert| {
            alert.id != "admin_panel_exposed_beyond_loopback"
                && !alert
                    .title
                    .contains("Admin panel is exposed beyond loopback")
        }));
    }

    #[test]
    fn closed_admin_alert_records_expire_after_retention_window() {
        let now_unix_ms = 1_800_000_000_000_u64;
        let active = normalize_suppressed_admin_alerts_at(
            &[SuppressedAdminAlertRecord {
                id: "replication_failed_threshold".to_string(),
                title: "latest failed replication object".to_string(),
                closed_at_unix_ms: now_unix_ms.saturating_sub(60_000),
                delete_after_unix_ms: now_unix_ms.saturating_add(60_000),
            }],
            now_unix_ms,
        );
        assert_eq!(active.len(), 1);

        let expired = normalize_suppressed_admin_alerts_at(
            &[SuppressedAdminAlertRecord {
                id: "replication_failed_threshold".to_string(),
                title: "latest failed replication object".to_string(),
                closed_at_unix_ms: now_unix_ms
                    .saturating_sub(ADMIN_ALERT_CLOSE_RETENTION_MS)
                    .saturating_sub(1_000),
                delete_after_unix_ms: now_unix_ms.saturating_sub(1),
            }],
            now_unix_ms,
        );
        assert!(expired.is_empty());
    }

