    async fn spawn_slow_auth_capture_llm_server(delay: Duration) -> (String, oneshot::Sender<()>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("test llm listener should bind");
        let addr = listener
            .local_addr()
            .expect("test llm listener addr should resolve");
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        let app = Router::new().route(
            "/v1/chat/completions",
            post(move || {
                let delay = delay;
                async move {
                    sleep(delay).await;
                    Json(json!({
                        "choices": [
                            {
                                "message": {
                                    "content": "{\"captcha\":\"A1B2\"}"
                                }
                            }
                        ]
                    }))
                }
            }),
        );
        tokio::spawn(async move {
            let _ = axum::serve(listener, app)
                .with_graceful_shutdown(async move {
                    let _ = shutdown_rx.await;
                })
                .await;
        });
        (format!("http://{addr}/v1"), shutdown_tx)
    }

