    #[tokio::test]
    async fn merge_answered_prompts_is_session_scoped_for_same_input_id() {
        let state = test_state();
        let session_a = upsert_browser_flow_auth_session(
            &state,
            Some("auth-session-merge-a".to_string()),
            "unicom".to_string(),
            "pan.wo.cn-web".to_string(),
            "unicom_sms_login".to_string(),
            BTreeMap::new(),
            BTreeMap::new(),
        );
        let session_b = upsert_browser_flow_auth_session(
            &state,
            Some("auth-session-merge-b".to_string()),
            "unicom".to_string(),
            "pan.wo.cn-web".to_string(),
            "unicom_sms_login".to_string(),
            BTreeMap::new(),
            BTreeMap::new(),
        );
        let prompt_a = ensure_auth_capture_prompt_for_interactive_request(
            &state,
            &session_a,
            &BrowserFlowInteractivePromptRequest {
                input_id: "sms_code".to_string(),
                field_label: "SMS".to_string(),
                field_kind: AuthPromptFieldKind::SmsCode,
                placeholder: None,
                message: "session a".to_string(),
            },
        );
        let prompt_b = ensure_auth_capture_prompt_for_interactive_request(
            &state,
            &session_b,
            &BrowserFlowInteractivePromptRequest {
                input_id: "sms_code".to_string(),
                field_label: "SMS".to_string(),
                field_kind: AuthPromptFieldKind::SmsCode,
                placeholder: None,
                message: "session b".to_string(),
            },
        );

        {
            let mut store = state
                .auth
                .capture_prompts
                .lock()
                .expect("auth capture prompt store poisoned");
            store
                .get_mut(&prompt_a.prompt_id)
                .expect("prompt a should exist")
                .answer("111222".to_string(), None, None)
                .expect("answer a should succeed");
            store
                .get_mut(&prompt_b.prompt_id)
                .expect("prompt b should exist")
                .answer("333444".to_string(), None, None)
                .expect("answer b should succeed");
        }

        let mut merged_a = BTreeMap::new();
        merge_answered_prompts_into_inputs(
            &state,
            "auth-session-merge-a",
            &mut merged_a,
            &BTreeSet::new(),
        );
        let mut merged_b = BTreeMap::new();
        merge_answered_prompts_into_inputs(
            &state,
            "auth-session-merge-b",
            &mut merged_b,
            &BTreeSet::new(),
        );
        assert_eq!(
            merged_a.get("sms_code"),
            Some(&serde_json::Value::String("111222".to_string()))
        );
        assert_eq!(
            merged_b.get("sms_code"),
            Some(&serde_json::Value::String("333444".to_string()))
        );
    }

