    #[tokio::test]
    async fn provider_credentials_round_trip_preserves_browser_profile() {
        let state = test_state();

        let profile = BrowserRequestProfile {
            source_url: Some(
                "https://cloud.189.cn/web/main/file/folder/-11?access_token=url-token#session"
                    .to_string(),
            ),
            captured_at_unix_ms: Some(1_778_947_975_011),
            user_agent: Some("Mozilla/5.0 Test Edge".to_string()),
            headers: BTreeMap::from([
                ("accept-language".to_string(), "en-US,en;q=0.9".to_string()),
                (
                    "authorization".to_string(),
                    "Bearer profile-token".to_string(),
                ),
                ("browser-id".to_string(), "profile-browser-id".to_string()),
                (
                    "cookie".to_string(),
                    "COOKIE_LOGIN_USER=profile".to_string(),
                ),
                (
                    "sec-ch-ua".to_string(),
                    "\"Chromium\";v=\"148\"".to_string(),
                ),
                ("x-auth-token".to_string(), "x-profile-token".to_string()),
            ]),
        }
        .normalize();

        let Json(saved) = update_provider_credentials(
            State(state.clone()),
            Path("telecom".to_string()),
            Json(ProviderCredentialInput {
                token: Some("telecom-token".to_string()),
                browser_id: Some("browser-id-123".to_string()),
                cookie_header: Some("COOKIE_LOGIN_USER=def".to_string()),
                family_id: None,
                root_folder_id: Some("-11".to_string()),
                user_domain_id: None,
                client_id: None,
                tenant: None,
                drive_id: None,
                redirect_url: None,
                quota_min_free: None,
                quota_max_used: None,
                personal_quota_min_free: None,
                personal_quota_max_used: None,
                family_quota_min_free: None,
                family_quota_max_used: None,
                browser_profile: Some(profile.clone()),
            ..Default::default() }),
        )
        .await
        .expect("telecom provider credentials update should succeed");

        let saved_profile = saved
            .browser_profile
            .as_ref()
            .expect("telecom payload should preserve browser profile");
        assert_eq!(
            saved_profile.user_agent.as_deref(),
            Some("Mozilla/5.0 Test Edge")
        );
        assert_eq!(
            saved_profile.source_url.as_deref(),
            Some("https://cloud.189.cn/web/main/file/folder/-11")
        );
        assert_eq!(
            saved_profile
                .headers
                .get("accept-language")
                .map(String::as_str),
            Some("en-US,en;q=0.9")
        );
        assert!(!saved_profile.headers.contains_key("authorization"));
        assert!(!saved_profile.headers.contains_key("browser-id"));
        assert!(!saved_profile.headers.contains_key("cookie"));
        assert!(!saved_profile.headers.contains_key("x-auth-token"));
        let saved_payload_json =
            serde_json::to_string(&saved).expect("saved credential payload should encode");
        assert!(!saved_payload_json.contains("profile-token"));
        assert!(!saved_payload_json.contains("profile-browser-id"));
        assert!(!saved_payload_json.contains("COOKIE_LOGIN_USER=profile"));
        assert!(!saved_payload_json.contains("url-token"));

        let Json(current) =
            get_provider_credentials(State(state.clone()), Path("telecom".to_string()))
                .await
                .expect("telecom provider credentials get should succeed");
        let current_payload_json =
            serde_json::to_string(&current).expect("current credential payload should encode");
        assert!(!current_payload_json.contains("profile-token"));
        assert!(!current_payload_json.contains("profile-browser-id"));
        assert!(!current_payload_json.contains("COOKIE_LOGIN_USER=profile"));
        assert!(!current_payload_json.contains("url-token"));

        let credential_path = provider_credentials_path(&state.config, ProviderId::Telecom);
        let stored = fs::read_to_string(&credential_path).expect("credential file should exist");
        assert!(stored.contains("Mozilla/5.0 Test Edge"));
        assert!(stored.contains("accept-language"));
    }

