    #[test]
    fn effective_provider_user_agent_prefers_stored_profile_then_detected_endpoint_persona() {
        let profile = BrowserRequestProfile {
            user_agent: Some("Mozilla/5.0 Stored Profile".to_string()),
            ..BrowserRequestProfile::default()
        }
        .normalize();
        let policy = AuthCapturePolicy {
            browser_endpoints: vec![AuthCaptureBrowserEndpoint {
                id: "edge".to_string(),
                label: Some("Edge".to_string()),
                endpoint_url: "http://127.0.0.1:9222".to_string(),
                enabled: true,
                target_selector: None,
                target_timeout_ms: Some(8000),
                detected_browser: Some("Microsoft Edge/148.0.0.0".to_string()),
                detected_protocol_version: Some("1.3".to_string()),
                detected_user_agent: Some("Mozilla/5.0 Detected Persona".to_string()),
                detected_at_unix_ms: Some(1_778_947_975_011),
            }],
            ..AuthCapturePolicy::from_env_defaults()
        };

        assert_eq!(
            effective_provider_user_agent(
                "CCBG_TEST_MISSING_USER_AGENT",
                Some(&profile),
                Some(&policy),
                "fallback-user-agent",
            ),
            "Mozilla/5.0 Stored Profile"
        );
        assert_eq!(
            effective_provider_user_agent(
                "CCBG_TEST_MISSING_USER_AGENT",
                None,
                Some(&policy),
                "fallback-user-agent",
            ),
            "Mozilla/5.0 Detected Persona"
        );
        assert_eq!(
            effective_provider_user_agent(
                "CCBG_TEST_MISSING_USER_AGENT",
                None,
                None,
                default_browser_compatible_user_agent(),
            ),
            default_browser_compatible_user_agent()
        );
    }

