    #[tokio::test]
    async fn object_actions_api_rename_copy_and_move_against_primary_backend() {
        let mut state = test_state();
        let primary_backend: DynBackend = Arc::new(StubBackend::new());
        replace_backend(&mut state, ProviderId::Stub, primary_backend.clone());

        primary_backend
            .put_object(PutObjectRequest {
                container: "family".to_string(),
                key: "shared/note.txt".to_string(),
                body: Bytes::from_static(b"family note").into(),
                size: Some(11),
                content_type: Some("text/plain".to_string()),
                preferred_upload_part_size_bytes: None,
            })
            .await
            .expect("seed family object should be created");

        let rename_status = run_object_action(
            State(state.clone()),
            Json(ObjectActionInput::Rename {
                bucket: "family".to_string(),
                key: "shared/note.txt".to_string(),
                new_key: "shared/renamed.txt".to_string(),
                mode: ObjectActionMode::GatewayManaged,
                provider: None,
                operator: None,
                ticket: None,
                notes: None,
            }),
        )
        .await
        .expect("rename should succeed");
        assert_eq!(rename_status, StatusCode::NO_CONTENT);

        let copy_status = run_object_action(
            State(state.clone()),
            Json(ObjectActionInput::Copy {
                source_bucket: "family".to_string(),
                source_key: "shared/renamed.txt".to_string(),
                destination_bucket: "root".to_string(),
                destination_key: "docs/copied.txt".to_string(),
                mode: ObjectActionMode::GatewayManaged,
                source_provider: None,
                destination_provider: None,
                operator: None,
                ticket: None,
                notes: None,
            }),
        )
        .await
        .expect("copy should succeed");
        assert_eq!(copy_status, StatusCode::NO_CONTENT);

        let move_status = run_object_action(
            State(state.clone()),
            Json(ObjectActionInput::Move {
                source_bucket: "root".to_string(),
                source_key: "docs/copied.txt".to_string(),
                destination_bucket: "family".to_string(),
                destination_key: "shared/moved.txt".to_string(),
                mode: ObjectActionMode::GatewayManaged,
                source_provider: None,
                destination_provider: None,
                operator: None,
                ticket: None,
                notes: None,
            }),
        )
        .await
        .expect("move should succeed");
        assert_eq!(move_status, StatusCode::NO_CONTENT);

        assert!(
            primary_backend
                .get_object("family", "shared/renamed.txt")
                .await
                .is_ok()
        );
        assert!(
            primary_backend
                .get_object("family", "shared/moved.txt")
                .await
                .is_ok()
        );
        assert!(
            primary_backend
                .get_object("root", "docs/copied.txt")
                .await
                .is_err()
        );

        let rename_job = state
            .metadata_store
            .latest_job_for_object("onedrive", "family", "shared/renamed.txt")
            .expect("rename metadata should load")
            .expect("rename metadata should exist");
        assert!(matches!(rename_job.operation, ReplicationOperation::Put));
        assert_eq!(rename_job.source_provider.as_deref(), Some("stub"));
        assert_eq!(rename_job.object.size, Some(11));

        let renamed_delete_job = state
            .metadata_store
            .latest_job_for_object("onedrive", "family", "shared/note.txt")
            .expect("rename delete metadata should load")
            .expect("rename delete metadata should exist");
        assert!(matches!(
            renamed_delete_job.operation,
            ReplicationOperation::Delete
        ));

        let copied_job = state
            .metadata_store
            .latest_job_for_object("onedrive", "root", "docs/copied.txt")
            .expect("copy metadata should load")
            .expect("copy metadata should exist");
        assert!(matches!(copied_job.operation, ReplicationOperation::Delete));

        let moved_job = state
            .metadata_store
            .latest_job_for_object("onedrive", "family", "shared/moved.txt")
            .expect("move metadata should load")
            .expect("move metadata should exist");
        assert!(matches!(moved_job.operation, ReplicationOperation::Put));
        assert_eq!(moved_job.object.content_type.as_deref(), Some("text/plain"));
    }

    #[tokio::test]
    async fn object_actions_copy_syncs_destination_logical_metadata() {
        let state = test_state();
        install_test_managed_encryption_application(
            &state,
            "object-actions-copy-app",
            "object-actions-copy-access",
            "object-actions-copy-secret",
            "object-actions-copy-profile",
            "object-actions-copy-key",
        );
        let bucket = "root".to_string();
        let encrypted_source_key = "encrypted/object-actions-source.txt".to_string();
        let encrypted_destination_key = "encrypted/object-actions-destination.txt".to_string();
        let encrypted_body = Bytes::from_static(b"object actions encrypted plaintext");

        let encrypted_source_uri: Uri = format!("/{bucket}/{encrypted_source_key}")
            .parse()
            .expect("encrypted source uri should parse");
        let encrypted_source_headers = signed_headers_for_application(
            &state.config,
            "object-actions-copy-access",
            "object-actions-copy-secret",
            &Method::PUT,
            &encrypted_source_uri,
            &encrypted_body,
            &[("content-type", "text/plain")],
        );
        put_object(
            State(state.clone()),
            Path((bucket.clone(), encrypted_source_key.clone())),
            Method::PUT,
            OriginalUri(encrypted_source_uri),
            encrypted_source_headers,
            encrypted_body.clone().into(),
        )
        .await
        .expect("encrypted source put should succeed");

        run_object_action(
            State(state.clone()),
            Json(ObjectActionInput::Copy {
                source_bucket: bucket.clone(),
                source_key: encrypted_source_key.clone(),
                destination_bucket: bucket.clone(),
                destination_key: encrypted_destination_key.clone(),
                mode: ObjectActionMode::GatewayManaged,
                source_provider: None,
                destination_provider: None,
                operator: None,
                ticket: None,
                notes: None,
            }),
        )
        .await
        .expect("object-actions copy should succeed");

        let destination_logical = state
            .metadata_store
            .logical_object(&bucket, &encrypted_destination_key)
            .expect("destination logical metadata should load")
            .expect("destination logical metadata should exist");
        assert!(destination_logical.encrypted);
        assert_eq!(
            destination_logical.plaintext_size,
            encrypted_body.len() as u64
        );

        let encrypted_destination_uri: Uri = format!("/{bucket}/{encrypted_destination_key}")
            .parse()
            .expect("encrypted destination uri should parse");
        let head_headers = signed_headers_for_application(
            &state.config,
            "object-actions-copy-access",
            "object-actions-copy-secret",
            &Method::HEAD,
            &encrypted_destination_uri,
            &[],
            &[],
        );
        let head_response = head_object(
            State(state.clone()),
            Path((bucket.clone(), encrypted_destination_key.clone())),
            Method::HEAD,
            OriginalUri(encrypted_destination_uri.clone()),
            head_headers,
        )
        .await
        .expect("head copied destination should succeed");
        let expected_length = encrypted_body.len().to_string();
        assert_eq!(
            head_response
                .headers()
                .get(CONTENT_LENGTH)
                .and_then(|value| value.to_str().ok()),
            Some(expected_length.as_str())
        );

        let get_headers = signed_headers_for_application(
            &state.config,
            "object-actions-copy-access",
            "object-actions-copy-secret",
            &Method::GET,
            &encrypted_destination_uri,
            &[],
            &[],
        );
        let get_response = get_object(
            State(state.clone()),
            Path((bucket.clone(), encrypted_destination_key.clone())),
            Method::GET,
            OriginalUri(encrypted_destination_uri),
            get_headers,
        )
        .await
        .expect("get copied destination should succeed");
        let get_body = to_bytes(get_response.into_body(), usize::MAX)
            .await
            .expect("destination body should read");
        assert_eq!(get_body.as_ref(), encrypted_body.as_ref());

        let plain_source_key = "notes/plain-source.txt".to_string();
        let stale_destination_key = "notes/stale-destination.txt".to_string();
        let plain_source_uri: Uri = format!("/{bucket}/{plain_source_key}")
            .parse()
            .expect("plain source uri should parse");
        let plain_source_body = Bytes::from_static(b"plain source body");
        let plain_source_headers = signed_headers_for_application(
            &state.config,
            "object-actions-copy-access",
            "object-actions-copy-secret",
            &Method::PUT,
            &plain_source_uri,
            &plain_source_body,
            &[("content-type", "text/plain")],
        );
        put_object(
            State(state.clone()),
            Path((bucket.clone(), plain_source_key.clone())),
            Method::PUT,
            OriginalUri(plain_source_uri),
            plain_source_headers,
            plain_source_body.into(),
        )
        .await
        .expect("plain source put should succeed");
        state
            .metadata_store
            .delete_logical_object(&bucket, &plain_source_key)
            .expect("plain source logical metadata should be removable");

        let stale_destination_uri: Uri = format!("/{bucket}/{stale_destination_key}")
            .parse()
            .expect("stale destination uri should parse");
        let stale_destination_body = Bytes::from_static(b"stale encrypted body");
        let stale_destination_headers = signed_headers_for_application(
            &state.config,
            "object-actions-copy-access",
            "object-actions-copy-secret",
            &Method::PUT,
            &stale_destination_uri,
            &stale_destination_body,
            &[("content-type", "text/plain")],
        );
        put_object(
            State(state.clone()),
            Path((bucket.clone(), stale_destination_key.clone())),
            Method::PUT,
            OriginalUri(stale_destination_uri),
            stale_destination_headers,
            stale_destination_body.into(),
        )
        .await
        .expect("stale destination put should succeed");
        assert!(
            state
                .metadata_store
                .logical_object(&bucket, &stale_destination_key)
                .expect("stale destination logical should load")
                .is_some()
        );

        run_object_action(
            State(state.clone()),
            Json(ObjectActionInput::Copy {
                source_bucket: bucket.clone(),
                source_key: plain_source_key,
                destination_bucket: bucket.clone(),
                destination_key: stale_destination_key.clone(),
                mode: ObjectActionMode::GatewayManaged,
                source_provider: None,
                destination_provider: None,
                operator: None,
                ticket: None,
                notes: None,
            }),
        )
        .await
        .expect("plain source copy should succeed");

        assert!(
            state
                .metadata_store
                .logical_object(&bucket, &stale_destination_key)
                .expect("stale destination logical should load after copy")
                .is_none()
        );
    }

