    #[tokio::test]
    async fn copy_object_put_header_copies_data_and_enqueues_replication_put() {
        let state = test_state();
        let bucket = "root".to_string();
        let source_key = "notes/source.txt".to_string();
        let destination_key = "notes/copied.txt".to_string();
        let source_body = Bytes::from_static(b"copy-source-body");

        let source_uri: Uri = format!("/{bucket}/{source_key}")
            .parse()
            .expect("source uri should parse");
        let source_headers = signed_headers(
            &state.config,
            &Method::PUT,
            &source_uri,
            &source_body,
            &[("content-type", "text/plain")],
        );
        put_object(
            State(state.clone()),
            Path((bucket.clone(), source_key.clone())),
            Method::PUT,
            OriginalUri(source_uri),
            source_headers,
            source_body.clone().into(),
        )
        .await
        .expect("source put should succeed");

        let copy_uri: Uri = format!("/{bucket}/{destination_key}")
            .parse()
            .expect("copy uri should parse");
        let copy_headers = signed_headers(
            &state.config,
            &Method::PUT,
            &copy_uri,
            &[],
            &[("x-amz-copy-source", "/root/notes/source.txt")],
        );
        let copy_response = put_object(
            State(state.clone()),
            Path((bucket.clone(), destination_key.clone())),
            Method::PUT,
            OriginalUri(copy_uri.clone()),
            copy_headers,
            Body::empty(),
        )
        .await
        .expect("copy should succeed");
        assert_eq!(copy_response.status(), StatusCode::OK);
        assert_eq!(
            copy_response
                .headers()
                .get(CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("application/xml")
        );
        let copy_body = to_bytes(copy_response.into_body(), usize::MAX)
            .await
            .expect("copy body should read");
        let copy_body = String::from_utf8(copy_body.to_vec()).expect("copy body should be utf-8");
        assert!(copy_body.contains("<CopyObjectResult"));
        assert!(copy_body.contains("<ETag>"));
        assert!(copy_body.contains("<LastModified>"));

        let head_headers = signed_headers(&state.config, &Method::HEAD, &copy_uri, &[], &[]);
        let head_response = head_object(
            State(state.clone()),
            Path((bucket.clone(), destination_key.clone())),
            Method::HEAD,
            OriginalUri(copy_uri.clone()),
            head_headers,
        )
        .await
        .expect("head destination should succeed");
        assert_eq!(head_response.status(), StatusCode::OK);

        let get_headers = signed_headers(&state.config, &Method::GET, &copy_uri, &[], &[]);
        let get_response = get_object(
            State(state.clone()),
            Path((bucket.clone(), destination_key.clone())),
            Method::GET,
            OriginalUri(copy_uri),
            get_headers,
        )
        .await
        .expect("get destination should succeed");
        let get_body = to_bytes(get_response.into_body(), usize::MAX)
            .await
            .expect("destination body should read");
        assert_eq!(get_body.as_ref(), source_body.as_ref());

        let replication = state
            .metadata_store
            .latest_job_for_object("onedrive", &bucket, &destination_key)
            .expect("replication metadata should load")
            .expect("destination replication job should exist");
        assert_eq!(replication.operation, ReplicationOperation::Put);
        assert_eq!(replication.source_provider.as_deref(), Some("stub"));
    }

