    #[tokio::test]
    async fn replication_worker_copies_encrypted_ciphertext_without_plaintext_rewrite() {
        let mut state = test_state();
        let target_backend: DynBackend = Arc::new(StubBackend::new());
        replace_backend(&mut state, ProviderId::Onedrive, target_backend.clone());
        install_test_managed_encryption_application(
            &state,
            "enc-app",
            "enc-access",
            "enc-secret",
            "enc-profile",
            "managed-test-key",
        );

        let bucket = "root".to_string();
        let key = "encrypted/replicated.txt".to_string();
        let body = Bytes::from_static(b"copy encrypted bytes");
        let uri: Uri = format!("/{bucket}/{key}")
            .parse()
            .expect("uri should parse");
        let put_headers = signed_headers_for_application(
            &state.config,
            "enc-access",
            "enc-secret",
            &Method::PUT,
            &uri,
            &body,
            &[("content-type", "text/plain")],
        );

        put_object(
            State(state.clone()),
            Path((bucket.clone(), key.clone())),
            Method::PUT,
            OriginalUri(uri),
            put_headers,
            body.clone().into(),
        )
        .await
        .expect("encrypted put should succeed");

        let jobs = state.replication.snapshot().pending_jobs;
        assert_eq!(jobs.len(), 1);
        process_replication_job(&state, &jobs[0])
            .await
            .expect("replication worker should succeed");

        let source = backend_for_test(&state, ProviderId::Stub)
            .get_object(&bucket, &key)
            .await
            .expect("source object should exist");
        let source_bytes = source
            .body
            .collect()
            .await
            .expect("source body should collect");
        let copied = target_backend
            .get_object(&bucket, &key)
            .await
            .expect("target object should exist");
        let copied_bytes = copied
            .body
            .collect()
            .await
            .expect("target body should collect");

        assert_ne!(source_bytes.as_ref(), body.as_ref());
        assert!(source_bytes.starts_with(b"CCBGENC1"));
        assert_eq!(copied_bytes.as_ref(), source_bytes.as_ref());
        assert_ne!(copied_bytes.as_ref(), body.as_ref());
    }

