    #[tokio::test]
    async fn object_placement_provider_summary_marks_provider_as_not_safe_to_remove() {
        let state = test_state();
        state
            .metadata_store
            .upsert_object_placement("telecom", "root", "docs/a.txt", 100)
            .expect("placement should persist");
        state
            .metadata_store
            .enqueue_jobs(&[ReplicationJob {
                job_id: 1,
                target: "onedrive".to_string(),
                source_provider: Some("telecom".to_string()),
                operation: ReplicationOperation::Put,
                object: replication_engine::ReplicationObjectRef {
                    bucket: "root".to_string(),
                    key: "docs/a.txt".to_string(),
                    etag: None,
                    size: Some(11),
                    content_type: Some("text/plain".to_string()),
                },
                status: ReplicationStatus::Pending,
                attempts: 0,
                enqueued_at_unix_ms: 1,
                next_attempt_at_unix_ms: None,
                last_error: None,
            }])
            .expect("pending job should persist");

        let Json(payload) = list_object_placement_providers(
            State(state),
            Query(ObjectPlacementProvidersQuery {
                sample_limit: Some(3),
            }),
        )
        .await
        .expect("object placement overview should succeed");

        let telecom = payload
            .providers
            .iter()
            .find(|entry| entry.provider == "telecom")
            .expect("telecom summary should exist");
        assert!(
            payload
                .providers
                .iter()
                .all(|entry| entry.provider != "onedrive")
        );
        assert_eq!(telecom.home_object_count, 1);
        assert_eq!(telecom.pending_source_jobs, 1);
        assert!(!telecom.safe_to_remove_now);
        assert_eq!(telecom.drain_status, "draining");
        assert!(
            telecom
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("persisted home object"))
        );
        assert!(
            telecom
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("still read from this provider"))
        );
    }

