    #[tokio::test]
    async fn delete_stale_object_placement_bulk_deletes_selected_stale_rows_only() {
        let state = test_state();
        backend_for_test(&state, ProviderId::Stub)
            .put_object(PutObjectRequest {
                container: "root".to_string(),
                key: "docs/live.txt".to_string(),
                body: Bytes::from_static(b"stub-home").into(),
                size: Some(9),
                content_type: Some("text/plain".to_string()),
                preferred_upload_part_size_bytes: None,
            })
            .await
            .expect("live stub object should be created");
        state
            .metadata_store
            .upsert_object_placement("stub", "root", "docs/stale-a.txt", 100)
            .expect("stale a placement should persist");
        state
            .metadata_store
            .upsert_object_placement("stub", "root", "docs/stale-b.txt", 200)
            .expect("stale b placement should persist");
        state
            .metadata_store
            .upsert_object_placement("stub", "root", "docs/live.txt", 300)
            .expect("live placement should persist");

        let Json(payload) = delete_stale_object_placement_bulk(
            State(state.clone()),
            Json(DeleteStaleObjectPlacementBulkInput {
                records: vec![
                    DeleteStaleObjectPlacementInput {
                        provider: "stub".to_string(),
                        bucket: "root".to_string(),
                        key: "docs/stale-a.txt".to_string(),
                    },
                    DeleteStaleObjectPlacementInput {
                        provider: "stub".to_string(),
                        bucket: "root".to_string(),
                        key: "docs/stale-b.txt".to_string(),
                    },
                    DeleteStaleObjectPlacementInput {
                        provider: "stub".to_string(),
                        bucket: "root".to_string(),
                        key: "docs/live.txt".to_string(),
                    },
                ],
            }),
        )
        .await
        .expect("bulk stale placement delete should succeed");

        assert_eq!(payload.requested, 3);
        assert_eq!(payload.deleted_count, 2);
        assert_eq!(payload.failed_count, 1);
        assert_eq!(payload.entries.len(), 3);
        assert!(payload.message.contains("已删除 2 条"));
        assert!(
            state
                .metadata_store
                .object_placement("root", "docs/stale-a.txt")
                .expect("placement lookup should succeed")
                .is_none()
        );
        assert!(
            state
                .metadata_store
                .object_placement("root", "docs/stale-b.txt")
                .expect("placement lookup should succeed")
                .is_none()
        );
        assert!(
            state
                .metadata_store
                .object_placement("root", "docs/live.txt")
                .expect("placement lookup should succeed")
                .is_some()
        );
        let failed_entry = payload
            .entries
            .iter()
            .find(|entry| entry.key == "docs/live.txt")
            .expect("failed live entry should be present");
        assert!(!failed_entry.deleted);
        assert!(failed_entry.message.contains("仍然存在"));
    }

