    #[tokio::test]
    async fn provider_limit_probe_halves_chunk_size_after_chunk_failures() {
        let mut state = test_state();
        let mib = 1024_u64 * 1024;
        let backend = Arc::new(LimitProbeRecordingBackend::new(
            4 * mib,
            8 * mib,
            8 * mib,
            mib,
        ));
        let recorder = backend.clone();
        replace_backend(&mut state, ProviderId::Stub, backend);

        let payload = run_provider_limit_probe(
            State(state),
            Path("stub".to_string()),
            Json(ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-tests".to_string()),
                sizes: vec!["8MiB".to_string()],
                sizes_bytes: Vec::new(),
                read_back: false,
                delete_after: true,
                stop_after_first_success: true,
                chunk_size: None,
                chunk_size_bytes: None,
                read_progress_interval_ms: None,
                read_total_timeout_ms: None,
            }),
        )
        .await
        .expect("limit probe should complete")
        .0;

        let chunks = payload
            .results
            .iter()
            .map(|step| step.probe_chunk_size_bytes)
            .collect::<Vec<_>>();
        assert_eq!(chunks, vec![4 * mib, 2 * mib, mib]);
        assert!(!payload.results[0].upload_ok);
        assert!(!payload.results[1].upload_ok);
        assert!(payload.results[2].upload_ok);
        assert_eq!(payload.max_verified_upload_bytes, Some(8 * mib));

        let recorded_chunks = recorder
            .attempts()
            .iter()
            .map(|attempt| attempt.max_body_chunk_bytes)
            .collect::<Vec<_>>();
        assert_eq!(recorded_chunks, vec![4 * mib, 2 * mib, mib]);
        let attempts = recorder.attempts();
        let preferred_parts = attempts
            .iter()
            .map(|attempt| attempt.preferred_upload_part_size_bytes)
            .collect::<Vec<_>>();
        assert_eq!(
            preferred_parts,
            vec![Some(4 * mib), Some(2 * mib), Some(mib)]
        );
        assert!(attempts.iter().all(|attempt| {
            attempt
                .key
                .starts_with(&format!("{}/", payload.probe_directory_key))
        }));
        assert!(
            attempts
                .iter()
                .all(|attempt| attempt.declared_size == Some(8 * mib))
        );
        assert_eq!(attempts[2].received_bytes, 8 * mib);
    }

