    #[tokio::test]
    async fn provider_limit_profile_keeps_dimension_maxima_across_runs() {
        let mut state = test_state();
        let backend = Arc::new(LimitProbeRecordingBackend::new(4, 100, 100, 4));
        replace_backend(&mut state, ProviderId::Stub, backend);

        let _ = run_provider_limit_probe(
            State(state.clone()),
            Path("stub".to_string()),
            Json(ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-profile-tests".to_string()),
                sizes: vec!["8B".to_string()],
                sizes_bytes: Vec::new(),
                read_back: true,
                delete_after: true,
                stop_after_first_success: true,
                chunk_size: Some("4B".to_string()),
                chunk_size_bytes: None,
                read_progress_interval_ms: None,
                read_total_timeout_ms: None,
            }),
        )
        .await
        .expect("first limit probe should complete");

        let second = run_provider_limit_probe(
            State(state.clone()),
            Path("stub".to_string()),
            Json(ProviderLimitProbeInput {
                bucket: Some("root".to_string()),
                key_prefix: Some("probe-profile-tests".to_string()),
                sizes: vec!["4B".to_string()],
                sizes_bytes: Vec::new(),
                read_back: true,
                delete_after: true,
                stop_after_first_success: true,
                chunk_size: Some("2B".to_string()),
                chunk_size_bytes: None,
                read_progress_interval_ms: None,
                read_total_timeout_ms: None,
            }),
        )
        .await
        .expect("second limit probe should complete")
        .0;

        let snapshot = control_plane_snapshot(&state);
        let latest = snapshot
            .provider_limit_probes
            .get(&ProviderId::Stub)
            .expect("latest probe should persist");
        assert_eq!(latest.max_verified_upload_bytes, Some(4));

        let profile = snapshot
            .provider_limit_profiles
            .get(&ProviderId::Stub)
            .expect("merged profile should persist");
        assert_eq!(profile.updated_at_unix_ms, second.checked_at_unix_ms);
        assert_eq!(profile.max_verified_upload_bytes, Some(8));
        assert_eq!(profile.max_verified_download_bytes, Some(8));
        assert_eq!(profile.max_verified_upload_part_size_bytes, Some(4));
        assert_eq!(
            profile.latest_probe_directory_key.as_deref(),
            Some(second.probe_directory_key.as_str())
        );

        let providers = provider_health_payloads(&state)
            .await
            .expect("provider health should include limit profiles");
        let stub = providers
            .iter()
            .find(|entry| entry.provider == "stub")
            .expect("stub provider should be present");
        assert_eq!(
            stub.limit_profile
                .as_ref()
                .and_then(|profile| profile.max_verified_upload_bytes),
            Some(8)
        );
    }

    #[tokio::test]
    async fn managed_encryption_keys_generate_export_and_import_round_trip() {
        let state = test_state();
        let Json(generated) = generate_managed_encryption_key(
            State(state.clone()),
            Json(ManagedEncryptionKeyGenerateInput {
                id: "router-kek-2026-01".to_string(),
                label: Some("Router KEK".to_string()),
                notes: Some("offline backup required".to_string()),
            }),
        )
        .await
        .expect("managed encryption key generation should succeed");
        assert_eq!(generated.id, "router-kek-2026-01");
        assert_eq!(generated.kind, ManagedEncryptionKeyKind::Raw256Bit);
        assert_eq!(generated.key_material_bytes, 32);
        assert!(generated.fingerprint_sha256.len() >= 32);
        assert!(generated.referencing_profile_ids.is_empty());

        let Json(keys) = get_managed_encryption_keys(State(state.clone()))
            .await
            .expect("managed encryption keys should list");
        assert_eq!(keys.len(), 1);
        assert_eq!(keys[0].id, "router-kek-2026-01");

        let Json(exported) = export_managed_encryption_key(
            State(state.clone()),
            Path("router-kek-2026-01".to_string()),
        )
        .await
        .expect("managed encryption key export should succeed");
        assert_eq!(exported.backup_format_version, 1);
        assert_eq!(exported.key.id, "router-kek-2026-01");
        assert!(!exported.key.key_material_base64.is_empty());

        let imported_state = test_state();
        let Json(imported) = import_managed_encryption_key_backup(
            State(imported_state.clone()),
            Json(exported.clone()),
        )
        .await
        .expect("managed encryption key import should succeed");
        assert_eq!(imported.id, "router-kek-2026-01");
        assert_eq!(imported.key_material_bytes, 32);

        let Json(re_exported) = export_managed_encryption_key(
            State(imported_state.clone()),
            Path("router-kek-2026-01".to_string()),
        )
        .await
        .expect("re-export after import should succeed");
        assert_eq!(
            re_exported.key.key_material_base64,
            exported.key.key_material_base64
        );
    }

