    #[tokio::test]
    async fn gateway_write_ahead_log_cleanup_deletes_only_checkpointed_committed_records() {
        let mut state = test_state();
        let telecom_backend: DynBackend = Arc::new(StubBackend::new());
        replace_backend(&mut state, ProviderId::Telecom, telecom_backend.clone());
        install_gateway_write_ahead_log_policy(&state, ProviderId::Telecom, &["default"]);

        let committed_record = test_gateway_write_ahead_log_record(
            &state,
            1,
            "tx-cleanup-1",
            GatewayWriteAheadLogPhase::Committed,
            "critical/cleanup-1.txt",
            Vec::new(),
        );
        let prepare_record = test_gateway_write_ahead_log_record(
            &state,
            2,
            "tx-cleanup-2",
            GatewayWriteAheadLogPhase::Prepare,
            "critical/cleanup-2.txt",
            Vec::new(),
        );
        for record in [committed_record.clone(), prepare_record.clone()] {
            telecom_backend
                .put_object(PutObjectRequest {
                    container: GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string(),
                    key: record.remote_key.clone(),
                    body: ObjectBody::from_bytes(
                        serde_json::to_vec(&record)
                            .expect("wal record should encode")
                            .into(),
                    ),
                    size: None,
                    content_type: Some("application/json".to_string()),
                    preferred_upload_part_size_bytes: None,
                })
                .await
                .expect("wal record should persist");
        }
        state
            .metadata_store
            .update_gateway_write_ahead_log_checkpoint_lsn(1, current_unix_ms())
            .expect("checkpoint should update");

        let status = cleanup_gateway_write_ahead_log_remote(&state)
            .await
            .expect("cleanup should succeed");

        let keys = telecom_backend
            .list_objects(ListObjectsRequest {
                container: Some(GATEWAY_WRITE_AHEAD_LOG_REMOTE_BUCKET.to_string()),
                prefix: Some(format!(
                    "{}/",
                    gateway_write_ahead_log_remote_prefix(&state.config)
                )),
                limit: None,
            })
            .await
            .expect("wal listing should succeed")
            .into_iter()
            .map(|object| object.key)
            .collect::<Vec<_>>();
        assert_eq!(keys, vec![prepare_record.remote_key]);
        assert_eq!(status.remote.total_records, 1);
        assert_eq!(status.remote.prepare_records, 1);
        assert_eq!(status.remote.by_operation.put, 1);
        assert_eq!(status.remote.by_operation.delete, 0);
        assert_eq!(status.remote.by_operation.metadata_sync, 0);
        assert_eq!(status.remote.by_phase_operation.prepare.put, 1);
        assert_eq!(status.remote.by_phase_operation.committed.put, 0);
        assert_eq!(status.remote.cleanup_ready_records, 0);
        assert!(status.cleanup_required);
    }

