    #[tokio::test]
    async fn encryption_profiles_accept_gateway_managed_keys_and_block_key_deletion() {
        let state = test_state();
        let _ = generate_managed_encryption_key(
            State(state.clone()),
            Json(ManagedEncryptionKeyGenerateInput {
                id: "router-kek-2026-01".to_string(),
                label: Some("Router KEK".to_string()),
                notes: None,
            }),
        )
        .await
        .expect("managed encryption key generation should succeed");

        let profiles = update_encryption_profiles(
            State(state.clone()),
            Json(EncryptionProfilesInput {
                profiles: vec![EncryptionProfileInput {
                    id: "router-default".to_string(),
                    label: Some("Router default".to_string()),
                    enabled: true,
                    algorithm_preference: EncryptionAlgorithmPreference::Auto,
                    chunk_plaintext_bytes: 1024 * 1024,
                    key_id: "router-kek-2026-01".to_string(),
                    key_source_kind: EncryptionKeySourceKind::GatewayManaged,
                    key_source_ref: "router-kek-2026-01".to_string(),
                    notes: Some("gateway-managed".to_string()),
                }],
            }),
        )
        .await
        .expect("gateway-managed encryption profile should save")
        .0;
        assert_eq!(profiles.len(), 1);
        assert_eq!(
            profiles[0].key_source_kind,
            EncryptionKeySourceKind::GatewayManaged
        );

        let reloaded = load_control_plane_state(
            &state.config.control_plane_file,
            &state.config.credentials_dir,
            default_control_plane_state(&state.config),
            state.config.onedrive.enabled,
        )
        .expect("persisted control plane with managed key ref should load");
        assert_eq!(reloaded.encryption_profiles.len(), 1);
        assert_eq!(
            reloaded.encryption_profiles[0].key_source_kind,
            EncryptionKeySourceKind::GatewayManaged
        );

        let ApiError(error) = delete_managed_encryption_key(
            State(state.clone()),
            Path("router-kek-2026-01".to_string()),
        )
        .await
        .expect_err("managed encryption keys referenced by profiles must not delete");
        let message = error.to_string();
        assert!(message.contains("router-kek-2026-01"));
        assert!(message.contains("router-default"));
    }

