    #[tokio::test]
    async fn presigned_multipart_upload_part_and_complete_succeeds_without_payload_hash_header() {
        let mut state = test_state();
        let amz_date = test_amz_date_offset(0);
        Arc::make_mut(&mut state.config).max_spooled_object_bytes = 64;
        let bucket = "root".to_string();
        let key = "presigned/multipart-put-ok.txt".to_string();

        let (init_uri, mut init_headers) = presigned_object_request(
            &state.config,
            &state.config.s3_access_key_id,
            &state.config.s3_secret_access_key,
            &Method::POST,
            &format!("/{bucket}/{key}?uploads"),
            &amz_date,
            120,
            &["host"],
            &[],
        );
        init_headers.remove("x-amz-content-sha256");
        let init_response = post_object(
            State(state.clone()),
            Path((bucket.clone(), key.clone())),
            Method::POST,
            OriginalUri(init_uri),
            init_headers,
            Body::empty(),
        )
        .await
        .expect("presigned multipart initiate should succeed");
        let init_body = to_bytes(init_response.into_body(), usize::MAX)
            .await
            .expect("body");
        let upload_id = extract_upload_id(&String::from_utf8(init_body.to_vec()).expect("utf8"));

        let part = Bytes::from_static(b"presigned-part");
        let part_path = format!("/{bucket}/{key}?partNumber=1&uploadId={upload_id}");
        let part_length = part.len().to_string();
        let (part_uri, mut part_headers) = presigned_object_request(
            &state.config,
            &state.config.s3_access_key_id,
            &state.config.s3_secret_access_key,
            &Method::PUT,
            &part_path,
            &amz_date,
            120,
            &["content-length", "host"],
            &[("content-length", part_length.as_str())],
        );
        part_headers.remove("x-amz-content-sha256");
        let part_response = put_object(
            State(state.clone()),
            Path((bucket.clone(), key.clone())),
            Method::PUT,
            OriginalUri(part_uri),
            part_headers,
            part.clone().into(),
        )
        .await
        .expect("presigned multipart UploadPart should succeed");
        assert_eq!(part_response.status(), StatusCode::OK);

        let parts = state
            .metadata_store
            .list_multipart_upload_parts(&upload_id)
            .expect("parts should list");
        let complete_xml = format!(
            "<CompleteMultipartUpload><Part><PartNumber>1</PartNumber><ETag>\"{}\"</ETag></Part></CompleteMultipartUpload>",
            parts[0].etag
        );
        let complete_uri: Uri = format!("/{bucket}/{key}?uploadId={upload_id}")
            .parse()
            .expect("uri");
        let complete_headers = signed_headers(
            &state.config,
            &Method::POST,
            &complete_uri,
            complete_xml.as_bytes(),
            &[("content-type", "application/xml")],
        );
        let complete_response = post_object(
            State(state.clone()),
            Path((bucket.clone(), key.clone())),
            Method::POST,
            OriginalUri(complete_uri),
            complete_headers,
            Body::from(complete_xml),
        )
        .await
        .expect("complete should succeed");
        assert_complete_multipart_upload_succeeded(complete_response).await;

        let get_uri: Uri = format!("/{bucket}/{key}").parse().expect("uri");
        let get_headers = signed_headers(&state.config, &Method::GET, &get_uri, &[], &[]);
        let get_response = get_object(
            State(state),
            Path((bucket, key)),
            Method::GET,
            OriginalUri(get_uri),
            get_headers,
        )
        .await
        .expect("get should succeed");
        let body = to_bytes(get_response.into_body(), usize::MAX)
            .await
            .expect("read body");
        assert_eq!(body.as_ref(), part.as_ref());
    }

